window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II et phrases avec wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Si j'étais toi, je …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La réalité d'Eva – les souhaits d'Eva. Complétez : würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Elle aimerait pourtant être plus grande.","why":"*grösser sein* : la forme de souhait de *sein* est **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Elle aimerait pourtant bien parler espagnol.","why":"Un infinitif se trouve à la fin (*sprechen*), donc le souhait se forme avec **würde** + infinitif.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Elle préférerait pourtant travailler comme guide touristique.","why":"Infinitif à la fin (*arbeiten*) → **würde** + infinitif. *lieber* = plutôt.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Elle aimerait pourtant avoir un grand appartement.","why":"*eine Wohnung haben* : la forme de souhait de *haben* est **hätte**. Pas besoin d'infinitif.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"À quoi pensent ces personnes ?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Associez chaque image à une expression de l'encadré.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Si je ne devais pas travailler, je serais assis au jardin en ce moment.","why":"L'image 1 le montre en train de travailler, puis rêvant sur une chaise longue. Après une subordonnée en *wenn*, la principale commence par le verbe (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Si j'avais une voiture, je ne devrais pas faire du vélo sous la pluie.","why":"Il fait du vélo sous la pluie ; une voiture lui éviterait cela. *müsste* est le Konjunktiv II de *müssen*. *Velo* est le mot suisse pour *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Si le bus n'avait pas de retard, je serais à l'heure au bureau.","why":"Un bus en retard la met en retard au travail. *wäre* est le Konjunktiv II de *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Réécrivez les phrases de a : commencez par la principale, puis la subordonnée en wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Je ne devrais pas faire du vélo sous la pluie si j'avais une voiture.","why":"D'abord la principale, puis la subordonnée en *wenn*. Dans la subordonnée en *wenn*, le verbe (*hätte*) va à la fin.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Je serais à l'heure au bureau si le bus n'avait pas de retard.","why":"Même schéma : principale, virgule, *wenn* … verbe à la fin (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Complétez avec les mots de l'encadré. Chaque mot est utilisé une fois ; les mots barrés sont utilisés dans l'exemple.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Je ferais certaines choses autrement si j'étais la cheffe de notre entreprise.","why":"*machen* à la fin → **würde** + infinitif. *Chefin sein* → **wäre**, à la fin de la subordonnée en *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Si j'étais Marco, je ferais absolument une formation professionnelle.","why":"*Marco sein* → **wäre** (comme *Wenn ich du wäre …*). La principale a l'infinitif *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Si je pouvais décider librement, je travaillerais dans une petite entreprise.","why":"*frei entscheiden können* → **könnte** à la fin de la subordonnée en *wenn*. Principale avec *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Si nous avions des enfants, je ne devrais travailler qu'à mi-temps.","why":"*Kinder haben* avec *wir* → **hätten**. L'encadré laisse **müsste** pour le dernier trou.","source":"k2","check":"*müsste* et *würde* sont tous deux corrects en b, c et e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* est tout aussi bon). L'encadré indique seulement quels trois trous reçoivent *würde* et lequel reçoit *müsste* ; ce corrigé donne la répartition la plus probable. Demandez à votre enseignant ce que le livre attend."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Je dois me dépêcher à cause de mon travail.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Réécrivez les réponses avec weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Parce que mon amie n'est pas ponctuelle.","why":"*wegen* + nom devient *weil* + une proposition avec un verbe ; le verbe (*ist*) va à la fin.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Parce qu'il fait mauvais.","why":"*des schlechten Wetters* → *das Wetter ist schlecht* ; après *weil*, le verbe va à la fin.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Parce que j'ai un rendez-vous important.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusatif après *haben*) ; verbe à la fin.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Complétez : wegen – weshalb – weil – deswegen – denn. Un mot peut être utilisé plusieurs fois.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"Je le comprends mal à cause de sa prononciation.","why":"Un nom suit (*seiner Aussprache*, génitif), pas une proposition → la préposition **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Un jour, j'aimerais bien aller en Italie, car j'aimerais voir la mer.","why":"Le verbe reste en 2e position après le trou (*ich möchte*) → **denn**. Avec *weil*, il irait à la fin.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Je dois améliorer ma compréhension orale, c'est pourquoi je regarde beaucoup de films.","why":"La deuxième partie est la conséquence, et le verbe vient juste après le trou (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"Mes enfants ont vite appris l'allemand parce qu'à l'école enfantine, ils sont toujours avec des enfants suisses.","why":"Le verbe est à la fin (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Pourquoi écris-tu les mots sur des petites cartes ?","why":"Il faut un mot interrogatif : **Weshalb** signifie *warum* (pourquoi)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Ma sœur parle déjà presque couramment l'allemand, c'est pourquoi elle peut m'aider à apprendre l'allemand.","why":"Conséquence, et le verbe vient juste après le trou (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Au cours de langue. Complétez : weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Je n'ai pas pu faire le dernier exercice parce que je ne l'ai pas compris.","why":"Le verbe est à la fin (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"Il n'y avait personne à l'inscription. C'est pourquoi je suis rentré à la maison.","why":"Une nouvelle phrase qui donne la conséquence, avec le verbe juste après le trou (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"En raison de mes bonnes notes, je n'ai pas dû passer de test au début du cours.","why":"Un groupe nominal suit (*meiner guten Noten*, génitif pluriel) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"Il y a un cours de langue supplémentaire parce que de très nombreux participants se sont inscrits.","why":"Le verbe est à la fin (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Hier, je n'ai malheureusement pas pu venir au cours à cause de mon mal de dents.","why":"Un groupe nominal suit (*meiner Zahnschmerzen*, génitif pluriel) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Qui trouve les meilleures excuses ? Choisissez une situation et écrivez. Les réponses modèles ne sont chaque fois qu'une possibilité parmi d'autres.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Malheureusement, je n'ai pas pu ranger la cuisine parce que j'ai soudain eu très mal au dos. J'ai dû m'allonger. C'est pourquoi j'ai regardé un film.","why":"Emploie *weil* (verbe à la fin : *hatte*) et *Deswegen* (verbe juste après : *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"À cause d'une grippe, je ne suis pas allé à l'examen final. J'avais beaucoup de fièvre, c'est pourquoi je suis resté au lit.","why":"Emploie *wegen* + génitif (*einer Grippe*) et *deswegen* + verbe (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Je suis vraiment désolé ! Malheureusement, je suis arrivé en retard, car il y avait un accident sur l'autoroute. À cause de l'embouteillage, j'ai perdu deux heures.","why":"*denn* garde le verbe en 2e position (*war*). *wegen des Staus* : génitif de *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (phrases conditionnelles, y compris les irréelles au Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis, dictionnaire des connecteurs : wenn (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis, dictionnaire des connecteurs : weil (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, dictionnaire des connecteurs : denn (causal, le verbe reste en 2e position)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs : deswegen (conséquence ; se place devant le verbe ou au milieu)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen avec le génitif)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Grandir avec plusieurs langues · lecture, message de forum, mots croisés, mots préférés","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"À la maison dans plusieurs langues","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Deux ou trois langues dans une même famille – aucun problème ?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Qui dit quoi ? Lisez les trois textes et écrivez le nom de la personne qui dit chaque phrase.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"«Les enfants veulent parler la même langue que leurs amis.» – Janusz","why":"Janusz (texte B) : *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"«C'est bien de parler plusieurs langues très bien, non ?» – Yara","why":"Yara (texte C) : *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"«Mes enfants passent d'une langue à l'autre.» – Amira","why":"Amira (texte A) : *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* Elle est la seule à parler de ses propres enfants."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Qu'est-ce qui est juste ? Relisez les textes. Tapez *richtig* (juste) ou *falsch* (faux) après chaque phrase ; dans le livre, vous cochez seulement les phrases justes.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Les enfants d'Amira parlent mieux l'arabe que l'allemand. → juste","why":"La famille parle toujours arabe à la maison : *Darum können das die Kinder viel besser.* (Leur allemand ici est du suisse allemand.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"Dans la famille d'Amira, on ne parle qu'allemand. → faux","why":"Le contraire : *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz a appris l'allemand pendant six ans. → faux","why":"Il avait six ans quand la famille a déménagé (*als ich sechs Jahre alt war*), et il parlait couramment le haut allemand après un an."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz et sa sœur ne voulaient pas parler polonais avec leurs parents. → juste","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara parle couramment trois langues. → juste","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* L'allemand est sa quatrième langue, et elle ne le parle pas encore bien."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara va bientôt apprendre l'allemand aussi. → faux","why":"Elle ne commence pas bientôt (*bald*) : elle apprend déjà l'allemand depuis deux ans (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"À la maison dans plusieurs langues","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Écrire un message de forum. Vous avez regardé un débat télévisé sur le fait de grandir avec plusieurs langues. Dans le forum en ligne de l'émission, vous trouvez cet avis :","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Prenez des notes sur les quatre questions. De courtes notes suffisent, pas de phrases complètes. Les notes modèles ne sont qu'une possibilité.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Oui : le fils de ma voisine – italien avec sa mère, suisse allemand à l'école","why":"Notes seulement : un nom ou une personne, et quelles langues où."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"apprendre deux langues sans cours, contact avec la famille à l'étranger, avantages au travail","why":"Rassemblez deux ou trois avantages ; vous en avez besoin pour *Ich finde es sehr gut, dass …* en b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mélanger les langues, une langue est plus faible, beaucoup de travail pour les parents","why":"Ces notes vont dans *Es könnte schwierig sein, dass …* et *Auf der anderen Seite …* en b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"non – les enfants apprennent bien deux langues si leurs parents leur parlent beaucoup","why":"Décidez oui ou non et donnez une raison : cela devient *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Écrivez maintenant votre opinion sur le sujet (environ 80 mots). Utilisez vos notes de a et quelques-unes des expressions.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"Je ne suis pas d'accord avec Sandra, car beaucoup d'enfants apprennent deux langues sans problèmes. Le fils de ma voisine grandit avec l'italien et l'allemand. Il parle italien avec sa mère et suisse allemand à l'école. Je trouve très bien qu'il apprenne deux langues si tôt. Le fait qu'il mélange parfois les langues pourrait être difficile. D'un autre côté, c'est normal chez les petits enfants. Le plus important de tout, c'est que les parents parlent beaucoup avec l'enfant. C'est pourquoi chaque parent devrait parler sa propre langue.","why":"Environ 85 mots, avec six des expressions. *denn* garde le verbe en 2e position (*lernen*) ; après *Deswegen*, le verbe vient tout de suite (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Résolvez les mots croisés. Chaque phrase donne la première lettre du mot manquant. La grille n'est pas affichée ici : tapez le mot en entier. Dans la grille du livre, Ä occupe une seule case.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Notre pays d'origine est l'Espagne. Nous venons d'Espagne.","why":"*aus einem Land stammen* = venir d'un pays (comme *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda et Mike ne se voient pas pendant six mois. C'est une longue séparation.","why":"*die Trennung* = la séparation, le nom de *sich trennen*. *eine lange* → un nom féminin."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"L'allemand et l'arabe n'ont pas la même écriture.","why":"*die Schrift* = l'écriture, les lettres dans lesquelles une langue s'écrit. L'arabe utilise un autre alphabet."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter vit maintenant en Amérique. Depuis qu'il y vit, il a beaucoup changé.","why":"*sich verändern* = changer (en parlant d'une personne). Perfekt : *hat sich verändert*. Le Ä occupe une seule case."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Elle écrit des livres. Elle est auteure de profession.","why":"*Sie* → la forme féminine en *-in* : *der Autor → die Autorin*. Pas d'article après *sein … von Beruf*."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"Les enfants ne font pas leurs devoirs. C'est pourquoi leurs parents les grondent.","why":"*mit jemandem schimpfen* = gronder quelqu'un. Sujet au pluriel *die Eltern* → *schimpfen*. Après *Deshalb*, le verbe vient tout de suite."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Elle ne travaille que depuis quelques mois. Elle a encore peu d'expérience dans son métier.","why":"*die Erfahrung* = l'expérience. *wenig Erfahrung haben* = avoir peu d'expérience."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Maintenant, c'est le chaos. Tout est sens dessus dessous.","why":"*durcheinander sein* = être en désordre, mélangé. S'écrit en un seul mot."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Pour Ye-Jon, les sons P et F se ressemblent. Elle ne peut pas les distinguer.","why":"*unterscheiden* = distinguer. Avec *kann*, l'infinitif va à la fin. *tönen* est le mot suisse pour *klingen* (sonner)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"Je pars en Grèce pendant les vacances, mais malheureusement je ne parle pas du tout grec.","why":"*Griechisch* = la langue grecque, avec une majuscule. *kein Griechisch können* = ne pas parler du tout grec."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"Il ne mange que des légumes et du riz. Il mange exclusivement des légumes et du riz.","why":"*ausschliesslich* = exclusivement, rien d'autre que. Orthographe suisse avec *ss* ; en Allemagne, on l'écrit avec le s dur (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Mot solution (la ligne en surbrillance dans la grille) : langue maternelle","why":"Chaque mot donne une lettre de la ligne en surbrillance : stam**M**en, trenn**U**ng, schrif**T**, (T dans la grille), veränd**E**rt, auto**R**in, (S dans la grille), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"À la maison dans plusieurs langues","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"Mon plus beau mot allemand","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Associez chaque photo à un mot de l'encadré. Les points de couleur du livre indiquent l'article : bleu = der, vert = das, rouge = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (un dessert à la crème au caramel)","why":"Nom suisse de la crème caramel. *Chöpfli* signifie en suisse allemand ‘petite tête’ (*Kopf*). Point vert → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – étoile filante","why":"*der Stern* = l'étoile ; *die Sternschnuppe* = l'étoile filante. Point rouge → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – papillon","why":"Mot suisse pour *der Schmetterling* (papillon) ; le Duden le marque *schweizerisch, sonst landschaftlich*. Point bleu → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Pourquoi quelqu'un pourrait-il trouver justement ces mots les plus beaux ? Qu'en pensez-vous ? Prenez des notes, puis discutez-en. Les notes modèles ne sont qu'une possibilité.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"si coloré et léger, rappelle l'été, drôle : l'animal n'est pas du tout un oiseau","why":"Pensez à ce que le mot vous fait voir ou ressentir, et à sa sonorité."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"doux, rappelle l'enfance, sonne drôle et typiquement suisse","why":"*tönen* = mot suisse pour *klingen* (sonner)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantique, on peut faire un vœu, sonne doux","why":"De courtes notes suffisent : des adjectifs et une raison."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"Mon mot préféré","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Quel mot allemand et quel mot de votre langue maternelle aimez-vous ? Pourquoi ? Écrivez un court texte en utilisant les expressions. La réponse modèle n'est qu'une possibilité.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"Mon mot allemand préféré est “gemütlich” (douillet, chaleureux). Quand j'entends ce mot, je pense à une soirée d'hiver avec du thé, des bougies et des amis. C'est pourquoi je le trouve si beau. Il sonne doux et chaud. Dans ma langue maternelle, l'anglais, il n'y a pas de mot avec exactement ce sens. En anglais, j'aime le mot “sunshine”. Pour moi, c'est un mot joyeux, parce qu'il sonne clair et aimable.","why":"*Wenn …, dann* + verbe tout de suite (*denke ich*) ; *Deshalb* + verbe tout de suite (*finde ich*). Remplacez par votre propre langue maternelle et vos propres mots.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Présentez votre texte en classe. Le modèle montre une façon possible de commencer.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Aujourd'hui, j'aimerais vous présenter mon mot préféré. C'est le mot “gemütlich”. …","why":"Commencez par nommer le mot, puis lisez votre texte de a. *euch* pour les camarades de classe, *Ihnen* si vous parlez de façon formelle."}]}]}],"sources":[{"id":"sommervogel","title":"Duden : Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs : deswegen (conséquence ; se place devant le verbe ou au milieu)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis, dictionnaire des connecteurs : wenn (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]},{"id":"03-nachfragen-test","no":3,"title":"Nachfragen · Fremdsprachen lernen · Test Lektion 4","title_en":"Faire répéter poliment, apprendre des langues, chercher un emploi · Test de la leçon 4","added":"2026-11-10","book":"Schritte plus Neu 5 · Arbeitsbuch und Testheft · Lektion 4","sources":[{"id":"hueber","title":"Hueber : Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (corrigé officiel, Lektion 4)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (phrases conditionnelles, y compris les irréelles au Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"weil","title":"grammis, dictionnaire des connecteurs : weil (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, dictionnaire des connecteurs : denn (causal, le verbe reste en 2e position)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs : deswegen (conséquence ; se place devant le verbe ou au milieu)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"deshalb","title":"grammis, dictionnaire des connecteurs : deshalb (conséquence ; synonymes daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"darum","title":"grammis, dictionnaire des connecteurs : d(a)rum (conséquence)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen avec le génitif)","url":"https://grammis.ids-mannheim.de/fragen/67"}],"pages":[{"page":"AB 133","heading":"C  Entschuldigung, könnten Sie das bitte wiederholen?","heading_en":"Excusez-moi, pourriez-vous répéter, s'il vous plaît ?","exercises":[{"no":"13","tag":"C2","instruction":"Ordnen Sie zu.","instruction_en":"Complétez chaque question ou phrase avec un début de l'encadré. Chaque début est utilisé une fois ; celui qui est barré est utilisé dans l'exemple.","box":["Tut mir leid, das Wort habe ich","Könnten Sie bitte langsamer","Entschuldigung, habe ich das","Könnten Sie das bitte","Darf ich Sie schnell","Was bedeutet","Könnten Sie mir vielleicht sagen","Wissen Sie, ob"],"box_used":[4],"box_exact":true,"example":[{"label":"a","text":"**Darf ich Sie schnell** etwas fragen?"}],"items":[{"label":"b","text":"___ der Ausdruck «es eilig haben»?","gaps":[["Was bedeutet"]],"solution":"**Was bedeutet** der Ausdruck «es eilig haben»?","en":"Que signifie l'expression « es eilig haben » ?","why":"*Was bedeutet …?* demande le sens d'un mot ou d'une expression. (*es eilig haben* = être pressé.)","source":"hueber"},{"label":"c","text":"___ sprechen?","gaps":[["Könnten Sie bitte langsamer"]],"solution":"**Könnten Sie bitte langsamer** sprechen?","en":"Pourriez-vous parler plus lentement, s'il vous plaît ?","why":"*Könnten Sie …* (Konjunktiv II) rend la demande polie ; l'infinitif *sprechen* va à la fin.","source":"hueber"},{"label":"d","text":"___ nicht verstanden.","gaps":[["Tut mir leid, das Wort habe ich"]],"solution":"**Tut mir leid, das Wort habe ich** nicht verstanden.","en":"Désolé, je n'ai pas compris ce mot.","why":"Perfekt : *habe … verstanden* ; *das Wort* est placé en tête pour insister, donc le verbe *habe* vient juste après.","source":"hueber"},{"label":"e","text":"Wie bitte? ___ wiederholen?","gaps":[["Könnten Sie das bitte"]],"solution":"Wie bitte? **Könnten Sie das bitte** wiederholen?","en":"Pardon ? Pourriez-vous répéter, s'il vous plaît ?","why":"Une demande polie avec *Könnten Sie …* ; *wiederholen* (répéter) va à la fin.","source":"hueber"},{"label":"f","text":"___ es hier auch Integrationskurse gibt?","gaps":[["Wissen Sie, ob"]],"solution":"**Wissen Sie, ob** es hier auch Integrationskurse gibt?","en":"Savez-vous s'il y a aussi des cours d'intégration ici ?","why":"*ob* introduit une question indirecte fermée (oui/non), donc le verbe *gibt* va à la fin.","source":"hueber"},{"label":"g","text":"___ richtig verstanden?","gaps":[["Entschuldigung, habe ich das"]],"solution":"**Entschuldigung, habe ich das** richtig verstanden?","en":"Excusez-moi, est-ce que j'ai bien compris ?","why":"Une question fermée (oui/non) au Perfekt : *habe* en premier, *verstanden* à la fin.","source":"hueber"},{"label":"h","text":"___, wo die Mensa ist?","gaps":[["Könnten Sie mir vielleicht sagen"]],"solution":"**Könnten Sie mir vielleicht sagen**, wo die Mensa ist?","en":"Pourriez-vous peut-être me dire où se trouve la cafétéria ?","why":"Une question indirecte avec *wo* : le verbe *ist* va à la fin. *die Mensa* = une cafétéria universitaire.","source":"hueber"}]},{"no":"14","tag":"C2","instruction":"Ergänzen Sie.","instruction_en":"Complétez les dialogues. Les premières lettres imprimées (et quelques lettres à l'intérieur des mots) sont données ; tapez les mots manquants en entier.","example":[{"label":"a","lead":"◆ Was ist denn das? ○ Das ist ein Zigerkrapfen. ◆ Entschuldigung, Zigerkrapfen kenne ich nicht.","text":"**Könnten Sie mir sagen**, was das ist?"}],"items":[{"label":"b","lead":"◆ Entschuldigen Sie bitte. Wo ist denn da die Mensa?  ○ Wie bitte? Das letzte Wort h… i… n… v… .  ◆ Die Mensa, die Uni-Kantine.","text":"Wie bitte? Das letzte Wort ___.","gaps":[["habe ich nicht verstanden"]],"solution":"Wie bitte? Das letzte Wort **habe ich nicht verstanden**.","en":"Pardon ? Je n'ai pas compris le dernier mot.","why":"Perfekt : *habe* en position 2 après *Das letzte Wort*, *verstanden* à la fin.","source":"hueber"},{"label":"c","lead":"◆ Also, dann treffen wir uns am 12.5. um 13.35 Uhr am Bahnhof.  ○ Entschuldigen Sie, es ist so laut da. K… S… den Termin b… w…?","text":"Entschuldigen Sie, es ist so laut da. ___ den Termin ___ ___?","gaps":[["Könnten Sie"],["bitte"],["wiederholen"]],"solution":"Entschuldigen Sie, es ist so laut da. **Könnten Sie** den Termin **bitte wiederholen**?","en":"Excusez-moi, il y a tellement de bruit ici. Pourriez-vous répéter l'heure du rendez-vous, s'il vous plaît ?","why":"Demande polie : *Könnten Sie* … infinitif *wiederholen* à la fin. *der Termin* = ici, l'heure du rendez-vous.","source":"hueber"},{"label":"d","lead":"◆ D… i… S… etwas f…?  ○ Ja, gern.  ◆ W… S…, o… es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","text":"◆ ___ etwas ___? ○ Ja, gern. ◆ ___, ___ es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","gaps":[["Darf ich Sie"],["fragen"],["Wissen Sie"],["ob"]],"solution":"◆ **Darf ich Sie** etwas **fragen**? ○ Ja, gern. ◆ **Wissen Sie**, **ob** es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","en":"Puis-je vous poser une question ? – Oui, bien sûr. – Savez-vous s'il y a aussi un bistro ou un restaurant dans le train de 14 h 33 pour Genève ?","why":"*Darf ich Sie etwas fragen?* ouvre poliment la conversation ; *ob* introduit une question indirecte fermée, donc *gibt* va à la fin.","source":"hueber"}]},{"no":"15","tag":"C2","instruction":"Bilden Sie Wörter und ordnen Sie zu.","instruction_en":"Formez des mots avec les syllabes de l'encadré et complétez les phrases. Les syllabes barrées (Men, sa) sont utilisées dans l'exemple.","phrases":["schrei · druck · ni · lung · ker · der · auf · Aus · ben · ho · Me · Wie · cha  (durchgestrichen im Beispiel: Men, sa)"],"example":[{"label":"a","text":"Ich wähle in der **Mensa** immer ein vegetarisches Gericht."}],"items":[{"label":"b","text":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten ___ geben? Diesmal will ich sie mir gleich in meinem Adressbuch ___, damit ich sie nicht wieder verliere.","gaps":[["Mechaniker"],["aufschreiben"]],"solution":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten **Mechaniker** geben? Diesmal will ich sie mir gleich in meinem Adressbuch **aufschreiben**, damit ich sie nicht wieder verliere.","en":"Ma voiture est de nouveau en panne. Pourrais-tu me redonner le numéro de téléphone de ton bon mécanicien, s'il te plaît ? Cette fois, je veux le noter tout de suite dans mon carnet d'adresses, pour ne pas le perdre à nouveau.","why":"Me-cha-ni-ker (une personne qui répare les voitures) et auf-schrei-ben (infinitif à la fin après *will*).","source":"hueber"},{"label":"c","text":"Was bedeutet der ___ «eine Entscheidung treffen»? Den habe ich noch nie gehört.","gaps":[["Ausdruck"]],"solution":"Was bedeutet der **Ausdruck** «eine Entscheidung treffen»? Den habe ich noch nie gehört.","en":"Que signifie l'expression « eine Entscheidung treffen » ? Je ne l'ai jamais entendue.","why":"Aus-druck : *der Ausdruck* = expression ; *der* et *Den* montrent que le mot est masculin. (*eine Entscheidung treffen* = prendre une décision.)","source":"hueber"},{"label":"d","text":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur ___.","gaps":[["Wiederholung"]],"solution":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur **Wiederholung**.","en":"Malheureusement, j'oublie souvent des mots allemands importants. J'ai besoin de plus de temps pour réviser.","why":"Wie-der-ho-lung : *zur* = *zu der*, donc un nom féminin suit : *die Wiederholung* (révision, répétition).","source":"hueber"}]}]},{"page":"AB 134","heading":"D  Fremdsprachen lernen – aber wie?","heading_en":"Apprendre des langues étrangères – mais comment ?","exercises":[{"no":"16","tag":"D1","instruction":"Fremdsprachen lernen – aber wie?","instruction_en":"Apprendre des langues étrangères – mais comment ?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ordnen Sie zu.","part_instruction_en":"Qui dit quoi ? Lisez les trois textes et écrivez la lettre du texte (A, B ou C) après chaque phrase.","reading":[{"label":"A  Mila, 17 Jahre","text":"Ich finde es total wichtig, dass man neue Wörter lernt und sie immer wieder wiederholt. Ich schreibe sie auf kleine Zettel oder Karten, auf der einen Seite das fremdsprachige Wort und auf der anderen die Übersetzung in meine Muttersprache. Diese Wortkarten habe ich immer in meiner Handtasche. Jeden Tag fahre ich eine Stunde mit dem Zug zur Schule. Das ist langweilig. Da habe ich viel Zeit und dann hole ich meine Wortkarten heraus und wiederhole die Wörter."},{"label":"B  Hakan, 19 Jahre","text":"Ich lerne seit vier Jahren Englisch in der Schule. Mir hilft es sehr, wenn ich viel Englisch höre. Ich habe viele MP3s mit Übungen aus dem Englischbuch und für die Aussprache auf meinem Smartphone. Ausserdem habe ich im Internet gute englische Podcasts gefunden. Die höre ich, wenn ich unterwegs bin. Ich möchte irgendwann nach der Schule ein Jahr nach London gehen und mir dort einen Job suchen. Darum will ich gut Englisch sprechen und auch meine Aussprache verbessern."},{"label":"C  Danila, 16 Jahre","text":"Ich bin vor drei Jahren in die Schweiz gekommen. Jetzt kann ich schon ziemlich gut Deutsch. Viel Zuhören ist für mich am allerwichtigsten. Deswegen habe ich im Bus, auf der Strasse, einfach überall immer den Schweizern zugehört und viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien. So habe ich viele Wörter und kleine Sätze der Alltagssprache gelernt, sogar auf Dialekt. Immer nur Grammatik und Wörter lernen, das finde ich uninteressant."}],"example":[{"label":"1","text":"Ich möchte meine Aussprache verbessern. → **B**"}],"items":[{"label":"2","text":"Ich höre oft anderen Leuten zu. → ___","gaps":[["C","Danila"]],"solution":"Ich höre oft anderen Leuten zu. → **C**","en":"J'écoute souvent les autres. → C (Danila)","why":"Danila : *Deswegen habe ich … einfach überall immer den Schweizern zugehört.*","source":"hueber"},{"label":"3","text":"Auf dem Weg zur Schule lerne ich Wörter. → ___","gaps":[["A","Mila"]],"solution":"Auf dem Weg zur Schule lerne ich Wörter. → **A**","en":"J'apprends des mots sur le chemin de l'école. → A (Mila)","why":"Mila sort ses fiches de vocabulaire pendant le trajet d'une heure en train jusqu'à l'école.","source":"hueber"},{"label":"4","text":"Ich möchte nach der Schule in England arbeiten. → ___","gaps":[["B","Hakan"]],"solution":"Ich möchte nach der Schule in England arbeiten. → **B**","en":"Après l'école, j'aimerais travailler en Angleterre. → B (Hakan)","why":"Hakan : *… ein Jahr nach London gehen und mir dort einen Job suchen.*","source":"hueber"},{"label":"5","text":"Ich schaue viel deutschsprachiges Fernsehen. → ___","gaps":[["C","Danila"]],"solution":"Ich schaue viel deutschsprachiges Fernsehen. → **C**","en":"Je regarde beaucoup la télévision en allemand. → C (Danila)","why":"Danila : *… viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien.*","source":"hueber"},{"label":"6","text":"Ich schreibe Wortkarten. → ___","gaps":[["A","Mila"]],"solution":"Ich schreibe Wortkarten. → **A**","en":"J'écris des fiches de vocabulaire. → A (Mila)","why":"Mila écrit le mot étranger d'un côté de la fiche et la traduction de l'autre.","source":"hueber"}]},{"no":"16","part":"b","part_instruction":"Schreiben Sie Sätze.","part_instruction_en":"Écrivez la deuxième phrase : commencez par le mot donné (Deshalb, Darum …) et utilisez les mots entre parenthèses. Le verbe vient juste après le mot de départ.","example":[{"label":"1","lead":"Mila möchte viele neue Wörter lernen. (neue Wörter auf Wortkarten schreiben)","text":"Deshalb **schreibt sie neue Wörter auf Wortkarten**."}],"items":[{"label":"2","lead":"Mila findet den Weg zur Schule langweilig. (mit Wortkarten neue Wörter wiederholen)","text":"","accept":["Darum wiederholt sie neue Wörter mit Wortkarten.","Darum wiederholt sie mit Wortkarten neue Wörter."],"solution":"**Darum wiederholt sie neue Wörter mit Wortkarten.**","en":"C'est pourquoi elle révise les nouveaux mots avec des fiches de vocabulaire.","why":"*Darum* occupe la position 1, donc le verbe conjugué *wiederholt* vient ensuite, puis le sujet *sie*.","source":"darum"},{"label":"3","lead":"Hakan hilft es, wenn er viel Englisch hört. (viele Podcasts auf seinem Smartphone haben)","text":"","accept":["Aus diesem Grund hat er viele Podcasts auf seinem Smartphone."],"solution":"**Aus diesem Grund hat er viele Podcasts auf seinem Smartphone.**","en":"Pour cette raison, il a beaucoup de podcasts sur son smartphone.","why":"*Aus diesem Grund* occupe la position 1, comme *deshalb* : le verbe *hat* vient ensuite, puis *er*.","source":"hueber"},{"label":"4","lead":"Hakan möchte nach der Schule ein Jahr in London arbeiten. (gut Englisch sprechen wollen)","text":"","accept":["Deswegen will er gut Englisch sprechen."],"solution":"**Deswegen will er gut Englisch sprechen.**","en":"C'est pour cela qu'il veut bien parler anglais.","why":"*Deswegen* + verbe de modalité *will* en position 2, infinitif *sprechen* à la fin.","source":"deswegen"},{"label":"5","lead":"Danila findet Grammatik und Wörter lernen uninteressant. (viel deutschsprachiges Fernsehen schauen)","text":"","accept":["Daher schaut sie viel deutschsprachiges Fernsehen."],"solution":"**Daher schaut sie viel deutschsprachiges Fernsehen.**","en":"Elle regarde donc beaucoup la télévision en allemand.","why":"*Daher* signifie la même chose que *deshalb* ; le verbe *schaut* vient juste après.","source":"deshalb"},{"label":"6","lead":"Für Danila ist Zuhören am allerwichtigsten. (einfach überall immer den Schweizern zugehört)","text":"","accept":["Aus diesem Grund hört sie einfach überall immer den Schweizern zu.","Aus diesem Grund hat sie einfach überall immer den Schweizern zugehört."],"solution":"**Aus diesem Grund hört sie einfach überall immer den Schweizern zu.**","en":"Pour cette raison, elle écoute tout simplement les Suisses, partout et tout le temps.","why":"*zuhören* est séparable : *hört … zu*. La consigne imprime *zugehört*, donc le Perfekt *hat … zugehört* (comme dans le texte de Danila) est aussi correct.","source":"hueber","check":"Le corrigé officiel donne le présent (*hört … zu*), bien que la consigne imprime le participe *zugehört*. Les deux phrases sont correctes en allemand ; demandez à votre enseignant ce que le livre attend."}]}]},{"page":"AB 138","heading":"Test Lektion 4","heading_en":"Test de la leçon 4","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Complétez le texte d'Arif. Le livre donne la première lettre et quelques lettres à l'intérieur de chaque mot ; tapez le mot en entier.","reading":[{"text":"Ich heisse Arif und bin 16 Jahre alt. Meine Familie und ich stammen (a) aus Syrien und unsere M… (b) ist Arabisch. Jetzt lerne ich seit einem Jahr Deutsch. Nächstes Jahr möchte ich eine Lehre beginnen. D… (c) möchte ich mein Deutsch verbessern. Natürlich spreche ich dann noch nicht f… (d) Deutsch. Besonders die Schrift und die A… (e) finde ich schwierig und ich verstehe auch noch nicht alle A… (f). Aber ich bin optimistisch."}],"example":[{"label":"a","text":"Meine Familie und ich **stammen** aus Syrien."}],"items":[{"label":"b","lead":"… und unsere M _ t _ _ _ s _ _ _ c _ _ ist Arabisch.","text":"… und unsere ___ ist Arabisch.","gaps":[["Muttersprache"]],"solution":"… und unsere **Muttersprache** ist Arabisch.","en":"… et notre langue maternelle est l'arabe.","why":"*die Muttersprache* = la première langue avec laquelle on grandit."},{"label":"c","lead":"D _ _ _ e _ e _ möchte ich mein Deutsch verbessern.","text":"___ möchte ich mein Deutsch verbessern.","gaps":[["Deswegen"]],"solution":"**Deswegen** möchte ich mein Deutsch verbessern.","en":"C'est pourquoi j'aimerais améliorer mon allemand.","why":"Les lettres données (D, e, e) correspondent à *Deswegen* ; il exprime la conséquence, et le verbe *möchte* suit juste après.","source":"deswegen"},{"label":"d","lead":"Natürlich spreche ich dann noch nicht f _ _ _ _ _ e _ _ Deutsch.","text":"Natürlich spreche ich dann noch nicht ___ Deutsch.","gaps":[["fliessend"]],"solution":"Natürlich spreche ich dann noch nicht **fliessend** Deutsch.","en":"Bien sûr, à ce moment-là, je ne parlerai pas encore couramment allemand.","why":"*fliessend* = couramment. Orthographe suisse avec *ss*."},{"label":"e","lead":"Besonders die Schrift und die A _ _ _ p _ _ _ _ e finde ich schwierig …","text":"Besonders die Schrift und die ___ finde ich schwierig …","gaps":[["Aussprache"]],"solution":"Besonders die Schrift und die **Aussprache** finde ich schwierig …","en":"Je trouve surtout l'écriture et la prononciation difficiles …","why":"*die Aussprache* = la prononciation (*aussprechen* = prononcer)."},{"label":"f","lead":"… und ich verstehe auch noch nicht alle A _ _ d _ _ c _ e.","text":"… und ich verstehe auch noch nicht alle ___.","gaps":[["Ausdrücke"]],"solution":"… und ich verstehe auch noch nicht alle **Ausdrücke**.","en":"… et je ne comprends pas encore toutes les expressions non plus.","why":"*der Ausdruck, die Ausdrücke* = expression(s) ; *alle* demande le pluriel."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit wenn.","instruction_en":"Écrivez des phrases conditionnelles irréelles avec *wenn* et le Konjunktiv II (*wäre, hätte, könnte, müsste* ou *würde* + infinitif).","example":[{"label":"a","lead":"(ich heute nicht so viel vorhaben – spazieren gehen)","text":"Wenn **ich heute nicht so viel vorhätte, würde ich spazieren gehen**."}],"items":[{"label":"b","lead":"(ich mein Englisch besser sein – dir bei der Hausaufgabe helfen können)","text":"","accept":["Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.","Wenn mein Englisch besser wäre, würde ich dir bei der Hausaufgabe helfen können."],"solution":"**Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.**","en":"Si mon anglais était meilleur, je pourrais t'aider pour les devoirs.","why":"*sein* → **wäre** à la fin de la subordonnée en *wenn* ; *können* → **könnte**, puis la principale commence par le verbe.","source":"kond"},{"label":"c","lead":"(ich euch besser verstehen – ihr nicht durcheinander sprechen)","text":"","accept":["Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.","Ich würde euch besser verstehen, wenn ihr nicht durcheinandersprechen würdet.","Ich könnte euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet."],"solution":"**Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.**","en":"Je vous comprendrais mieux si vous ne parliez pas tous en même temps.","why":"D'abord la principale ; *würde* + infinitif dans les deux parties. Dans la subordonnée en *wenn*, *würdet* va à la fin.","source":"kond"},{"label":"d","lead":"(ich mehr Freizeit haben – nicht so viel arbeiten müssen)","text":"","accept":["Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste."],"solution":"**Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste.**","en":"J'aurais plus de temps libre si je ne devais pas autant travailler.","why":"*haben* → **hätte**, *müssen* → **müsste** (à la fin de la subordonnée en *wenn*).","source":"k2"}]},{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Complétez avec un mot de l'encadré. Chaque mot est utilisé une fois ; celui qui est barré est utilisé dans l'exemple (la réponse de l'item a).","box":["denn","Weshalb","Weil","Wegen","Deswegen"],"box_used":[2],"box_exact":true,"items":[{"label":"a","text":"___ möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","gaps":[["Weshalb"]],"solution":"**Weshalb** möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","en":"Pourquoi Costa veut-il devenir mécatronicien ? – Parce qu'il s'intéresse aux voitures.","why":"Il faut un mot interrogatif ; **Weshalb** = *warum* (pourquoi). La réponse imprimée commence par *Weil*.","source":"weil"},{"label":"b","text":"___ seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","gaps":[["Wegen"]],"solution":"**Wegen** seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","en":"Grâce à ses bonnes connaissances d'allemand, il a vite trouvé une place d'apprentissage.","why":"Un groupe nominal suit (*seiner guten Deutschkenntnisse*, génitif pluriel) → la préposition **Wegen**.","source":"wegen"},{"label":"c","text":"Er ist erst 17 Jahre alt. ___ wohnt er noch bei seinen Eltern.","gaps":[["Deswegen"]],"solution":"Er ist erst 17 Jahre alt. **Deswegen** wohnt er noch bei seinen Eltern.","en":"Il n'a que 17 ans. C'est pourquoi il habite encore chez ses parents.","why":"Une conséquence, et le verbe vient juste après le trou (*wohnt er*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Jetzt spart er Geld, ___ er möchte nach der Ausbildung eine eigene Wohnung haben.","gaps":[["denn"]],"solution":"Jetzt spart er Geld, **denn** er möchte nach der Ausbildung eine eigene Wohnung haben.","en":"Maintenant, il économise de l'argent, car il aimerait avoir son propre appartement après sa formation.","why":"Une cause, et le verbe reste en 2e position (*er möchte*) → **denn**.","source":"denn"}]},{"no":"4","instruction":"Wie kann man auch sagen? Ergänzen Sie.","instruction_en":"Comment le dire autrement ? Complétez la deuxième expression. Le livre donne quelques lettres ; tapez les mots en entier.","example":[{"label":"a","text":"Können Sie mir sagen, wo …? – **Wissen Sie**, wo …?"}],"items":[{"label":"b","lead":"Ich habe eine Frage. – D _ _ _  i _ _  S _ _  e _ _ _ _  f _ _ _ _ _?","text":"Ich habe eine Frage. – ___?","gaps":[["Darf ich Sie etwas fragen"]],"solution":"Ich habe eine Frage. – **Darf ich Sie etwas fragen**?","en":"J'ai une question. – Puis-je vous poser une question ?","why":"Une façon polie de commencer une question : *Darf ich Sie etwas fragen?*"},{"label":"c","lead":"Könnten Sie das bitte noch einmal sagen? – K _ _ _ t _ _  S _ _  d _ s  b _ _ t _  wi _ _ _ h _ _ _ _?","text":"Könnten Sie das bitte noch einmal sagen? – ___?","gaps":[["Könnten Sie das bitte wiederholen"]],"solution":"Könnten Sie das bitte noch einmal sagen? – **Könnten Sie das bitte wiederholen**?","en":"Pourriez-vous le redire, s'il vous plaît ? – Pourriez-vous répéter, s'il vous plaît ?","why":"*wiederholen* = répéter = *noch einmal sagen*."},{"label":"d","lead":"Was meinen Sie mit …? – W _ _  b _ _ e _ _ _ _ …?","text":"Was meinen Sie mit …? – ___ …?","gaps":[["Was bedeutet"]],"solution":"Was meinen Sie mit …? – **Was bedeutet** …?","en":"Que voulez-vous dire par … ? – Que signifie … ?","why":"*Was bedeutet …?* demande le sens, comme *Was meinen Sie mit …?*","check":"Les lettres de ce trou sont difficiles à lire sur la photo ; *Was bedeutet …?* leur correspond, et c'est l'expression de l'exercice 13. Demandez à votre enseignant si votre livre montre autre chose."},{"label":"e","lead":"Entschuldigung. – T _ _  m _ _  l _ _ _.","text":"Entschuldigung. – ___.","gaps":[["Tut mir leid"]],"solution":"Entschuldigung. – **Tut mir leid**.","en":"Excusez-moi. / Pardon. – Je suis désolé.","why":"*Tut mir leid* = je suis désolé, une autre façon de s'excuser."}]}]},{"page":"AB 139","heading":"Fokus Beruf: Stellensuche","heading_en":"Focus métier : chercher un emploi","exercises":[{"no":"1","instruction":"Yusuf sucht eine neue Stelle als Coiffeur. Er liest eine Broschüre mit Tipps für die Stellensuche. Lesen Sie die Tipps und ordnen Sie die Überschriften zu.","instruction_en":"Yusuf cherche un nouvel emploi de coiffeur. Il lit une brochure de conseils pour la recherche d'emploi. Lisez les conseils et écrivez la lettre du titre correspondant (A–E) après chaque paragraphe.","reading":[{"label":"1","text":"Machen Sie eine Liste von Personen, die Sie persönlich kennen: Bekannte, Kollegen, Freunde und Verwandte. Notieren Sie auch die Namen von früheren Arbeitgebern und Arbeitskollegen. Informieren Sie diese Personen – mündlich oder schriftlich – darüber, dass Sie auf Stellensuche sind. Wichtig: Informieren Sie Ihre Kontaktpersonen, wenn Sie eine Stelle gefunden haben."},{"label":"2","text":"Werden Sie aktiv. Warten Sie nicht, bis Sie ein passendes Stelleninserat finden, sondern schreiben Sie Ihre eigene Stellenanzeige. Suchen Sie ein Internet-Portal, das zu Ihrer Branche passt, und präsentieren Sie sich. Solche Annoncen kosten viel weniger als gedruckte Annoncen und Sie können sie ausserdem noch mit einer eigenen Bewerber-Website verbinden."},{"label":"3","text":"Erhöhen Sie Ihre Erfolgschancen mit einer Kurzbewerbung. Suchen Sie sich Ihre Wunschfirma und bewerben Sie sich. Dafür braucht es natürlich eine gute Recherche, damit Sie die «richtige» Firma und die «richtige» Person anschreiben. Wie ihr Name sagt, ist diese Bewerbung kurz: Sie besteht aus einem Bewerbungsschreiben und dem tabellarischen Lebenslauf."},{"label":"4","text":"Sind in Ihrer Branche Bewerbungen per Telefon üblich? Sind Sie besonders mutig und überzeugen vor allem mündlich sehr gut? Aus welchem Grund Sie sich für diese Bewerbungsform entscheiden: Wichtig ist auch hier eine gründliche Vorbereitung. Machen Sie Notizen und üben Sie das Gespräch mit Freunden. Fehlt Ihnen der Mut dazu, wählen Sie die schriftliche Bewerbung."},{"label":"5","text":"Die grösste Auswahl an Stelleninseraten finden Sie im Internet. Wichtig ist eine sorgfältige Analyse der Inserate: Was will die Firma? Welche Qualifikationen und Erfahrungen haben Sie? Machen Sie eine Liste und beantworten Sie diese Fragen. Können Sie ca. 80 Prozent der Anforderungen erfüllen, dann ist eine Bewerbung sinnvoll."}],"items":[{"label":"1","text":"Absatz 1 (Liste von Personen, die Sie kennen) → ___","gaps":[["C","C Das persönliche Netzwerk"]],"solution":"Absatz 1 (Liste von Personen, die Sie kennen) → **C**","en":"Paragraphe 1 (une liste de personnes que vous connaissez) → C, Votre réseau personnel","why":"Les amis, les collègues et les anciens employeurs forment votre réseau personnel.","source":"hueber"},{"label":"2","text":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → ___","gaps":[["A","A Online-Stellengesuch"]],"solution":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → **A**","en":"Paragraphe 2 (votre propre annonce sur Internet) → A, Annonce de recherche d'emploi en ligne","why":"*das Stellengesuch* = une annonce dans laquelle vous cherchez un emploi ; ici, sur un portail Internet.","source":"hueber"},{"label":"3","text":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → ___","gaps":[["E","E Spontanbewerbung"]],"solution":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → **E**","en":"Paragraphe 3 (une courte candidature auprès de l'entreprise de vos rêves) → E, Candidature spontanée","why":"Vous postulez auprès d'une entreprise qui n'a pas publié d'offre : *die Spontanbewerbung*.","source":"hueber"},{"label":"4","text":"Absatz 4 (Bewerbungen per Telefon) → ___","gaps":[["D","D Telefonische Bewerbung"]],"solution":"Absatz 4 (Bewerbungen per Telefon) → **D**","en":"Paragraphe 4 (postuler par téléphone) → D, Candidature par téléphone","why":"*per Telefon* = *telefonisch*.","source":"hueber"},{"label":"5","text":"Absatz 5 (Stelleninserate im Internet analysieren) → ___","gaps":[["B","B Stelleninserate"]],"solution":"Absatz 5 (Stelleninserate im Internet analysieren) → **B**","en":"Paragraphe 5 (analyser les offres d'emploi sur Internet) → B, Offres d'emploi","why":"*das Stelleninserat* (suisse) = une offre d'emploi publiée par une entreprise.","source":"hueber"}],"phrases":["A Online-Stellengesuch","B Stelleninserate","C Das persönliche Netzwerk","D Telefonische Bewerbung","E Spontanbewerbung"]},{"no":"2","instruction":"Yusuf hat entschieden, selbst aktiv zu werden, und hat ein Stellengesuch geschrieben. Lesen Sie seinen Text und unterstreichen Sie: – Wer und wie ist Yusuf? – Was kann er? – Was sucht er?","instruction_en":"Yusuf a décidé de prendre l'initiative et a rédigé une annonce de recherche d'emploi. Lisez son texte et trouvez qui est Yusuf et comment il est, ce qu'il sait faire et ce qu'il cherche. Écrivez les mots correspondants pour chaque question.","reading":[{"text":"Suchen Sie einen engagierten Coiffeur, der kreativ und flexibel ist? Dann rufen Sie mich, 24, an. Ich biete sechs Jahre Berufserfahrung und diverse Weiterbildungen im Bereich Stilberatung. Ich suche eine Herausforderung, bei der ich Neues lernen und mich weiter spezialisieren kann."}],"items":[{"label":"1","lead":"Wer und wie ist Yusuf?","text":"","open":true,"solution":"ein engagierter Coiffeur, kreativ und flexibel, 24 Jahre alt","en":"un coiffeur engagé, créatif et flexible, 24 ans","why":"Qui il est (métier, âge) et comment il est (adjectifs).","source":"hueber"},{"label":"2","lead":"Was kann er?","text":"","open":true,"solution":"sechs Jahre Berufserfahrung, diverse Weiterbildungen im Bereich Stilberatung","en":"six ans d'expérience professionnelle, diverses formations continues en conseil en style","why":"Ce qu'il offre : expérience et formation.","source":"hueber"},{"label":"3","lead":"Was sucht er?","text":"","open":true,"solution":"eine Herausforderung, bei der er Neues lernen und sich weiter spezialisieren kann","en":"un défi qui lui permette d'apprendre de nouvelles choses et de se spécialiser davantage","why":"La dernière phrase : *Ich suche …*","source":"hueber"}]},{"no":"3","instruction":"Ein Stellengesuch im Internet aufgeben. Sie suchen eine neue Stelle. Machen Sie eine Tabelle. Schreiben Sie dann einen Profiltext wie in 2.","instruction_en":"Publiez une annonce de recherche d'emploi sur Internet. Vous cherchez un nouvel emploi. Faites un tableau à trois colonnes (Qui suis-je et comment suis-je ? Que sais-je faire ? Qu'est-ce que je cherche ?), puis rédigez un profil comme celui de Yusuf en 2. La réponse modèle n'est qu'une possibilité.","phrases":["teamfähig/selbstständig/kontaktfreudig/zuverlässig/verantwortungsbewusst / … sein","gute Computer-/Sprachkenntnisse/Kenntnisse in … haben","gut mit … umgehen können","… Vollzeit/Teilzeit/auf Stundenbasis arbeiten","ab sofort / ab nächstem Monat / … suchen"],"example":[{"label":"Tabelle","text":"Wer und wie bin ich? flexibel, teamfähig, … | Was kann ich? … | Was suche ich? …"}],"items":[{"label":"1","lead":"Tabelle","text":"","open":true,"solution":"Wer und wie bin ich? flexibel, teamfähig, zuverlässig, kontaktfreudig | Was kann ich? gut mit Kunden umgehen, gute Computerkenntnisse, fliessend Deutsch und Englisch | Was suche ich? eine Teilzeitstelle ab nächstem Monat, ein internationales Team","en":"Qui suis-je et comment suis-je ? flexible, esprit d'équipe, fiable, sociable | Que sais-je faire ? bien m'occuper des clients, bonnes connaissances en informatique, allemand et anglais courants | Qu'est-ce que je cherche ? un emploi à temps partiel dès le mois prochain, une équipe internationale","why":"Quelques mots-clés par colonne suffisent ; utilisez les expressions de l'encadré.","source":"hueber"},{"label":"2","lead":"Profiltext","text":"","open":true,"solution":"Suchen Sie eine zuverlässige Verkäuferin, die teamfähig und kontaktfreudig ist? Ich kann gut mit Kunden umgehen, habe gute Computerkenntnisse und spreche fliessend Deutsch und Englisch. Ich suche ab nächstem Monat eine Teilzeitstelle in einem internationalen Team.","en":"Vous cherchez une vendeuse fiable, qui a l'esprit d'équipe et qui est sociable ? Je sais bien m'occuper des clients, j'ai de bonnes connaissances en informatique et je parle couramment allemand et anglais. Je cherche un emploi à temps partiel dans une équipe internationale dès le mois prochain.","why":"Les trois mêmes étapes que Yusuf : qui vous êtes, ce que vous savez faire, ce que vous cherchez. *die* dans la relative renvoie à *Verkäuferin*.","source":"hueber"}]}]},{"page":"Test L4 · 19","heading":"Grammatik","heading_en":"Grammaire","exercises":[{"no":"1","instruction":"Wunsch und Realität?","instruction_en":"Souhait et réalité ?","part":"a","part_instruction":"Ergänzen Sie.","part_instruction_en":"Nina doit faire une chose mais préférerait en faire une autre. Écrivez ce qu'elle préférerait faire avec *würde* + les mots entre parenthèses (avec *lieber*, ou *gern* à l'item 5).","example":[{"label":"1","lead":"Nina macht Diät. (Sahnetorte essen)","text":"Aber sie **würde lieber Sahnetorte essen**."}],"items":[{"label":"2","lead":"Nina muss für eine Sprachprüfung lernen. (Musik hören)","text":"Aber sie ___.","gaps":[["würde lieber Musik hören"]],"solution":"Aber sie **würde lieber Musik hören**.","en":"Mais elle préférerait écouter de la musique.","why":"*würde* en position 2, *lieber* = plutôt, infinitif *hören* à la fin.","source":"k2"},{"label":"3","lead":"Nina muss ihre Kleider aufräumen. (mit ihrer Freundin telefonieren)","text":"Aber sie ___.","gaps":[["würde lieber mit ihrer Freundin telefonieren"]],"solution":"Aber sie **würde lieber mit ihrer Freundin telefonieren**.","en":"Mais elle préférerait téléphoner à son amie.","why":"*würde* + *lieber* + infinitif à la fin.","source":"k2"},{"label":"4","lead":"Nina arbeitet am Computer. (Computerspiele spielen)","text":"Aber sie ___.","gaps":[["würde lieber Computerspiele spielen"]],"solution":"Aber sie **würde lieber Computerspiele spielen**.","en":"Mais elle préférerait jouer à des jeux vidéo.","why":"*würde* + *lieber* + infinitif à la fin.","source":"k2"},{"label":"5","lead":"Nina hat morgen sehr früh einen Termin. (bis spät in die Nacht lesen)","text":"Sie ___ gern ___.","gaps":[["würde aber"],["bis spät in die Nacht lesen"]],"solution":"Sie **würde aber** gern **bis spät in die Nacht lesen**.","en":"Mais elle aimerait bien lire jusque tard dans la nuit.","why":"Le livre imprime *gern* : *würde* + *gern* + infinitif (un souhait), avec *aber* après le verbe.","source":"k2"},{"label":"6","lead":"Nina verbringt den Abend mit ihren Eltern. (tanzen gehen)","text":"Aber sie ___.","gaps":[["würde lieber tanzen gehen"]],"solution":"Aber sie **würde lieber tanzen gehen**.","en":"Mais elle préférerait aller danser.","why":"*würde* + *lieber* ; les deux infinitifs *tanzen gehen* à la fin.","source":"k2"}]},{"no":"1","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Réécrivez les phrases de a sous forme de phrases conditionnelles irréelles : *Wenn Nina nicht …, würde sie …*","example":[{"label":"1","text":"Wenn Nina nicht Diät machen würde, würde sie Sahnetorte essen."}],"items":[{"label":"2","text":"","accept":["Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören."],"solution":"**Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören.**","en":"Si Nina ne devait pas réviser pour un examen de langue, elle écouterait de la musique.","why":"*muss* → **müsste** à la fin de la subordonnée en *wenn* ; la principale commence par *würde*.","source":"kond"},{"label":"3","text":"","accept":["Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.","Wenn Nina ihre Kleider nicht aufräumen müsste, würde sie mit ihrer Freundin telefonieren."],"solution":"**Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.**","en":"Si Nina ne devait pas ranger ses vêtements, elle téléphonerait à son amie.","why":"*müsste* + infinitif *aufräumen* : dans la subordonnée en *wenn*, *müsste* va en dernier.","source":"kond"},{"label":"4","text":"","accept":["Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.","Wenn Nina nicht am Computer arbeiten müsste, würde sie Computerspiele spielen."],"solution":"**Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.**","en":"Si Nina ne travaillait pas à l'ordinateur, elle jouerait à des jeux vidéo.","why":"Le corrigé accepte *arbeiten würde* ou *arbeiten müsste* dans la subordonnée en *wenn*."},{"label":"5","text":"","accept":["Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.","Wenn Nina morgen keinen Termin sehr früh hätte, würde sie bis spät in die Nacht lesen."],"solution":"**Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.**","en":"Si Nina n'avait pas un rendez-vous très tôt demain, elle lirait jusque tard dans la nuit.","why":"*hat* → **hätte**, à la fin de la subordonnée en *wenn*."},{"label":"6","text":"","accept":["Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.","Wenn Nina den Abend nicht mit ihren Eltern verbringen müsste, würde sie tanzen gehen."],"solution":"**Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.**","en":"Si Nina ne passait pas la soirée avec ses parents, elle irait danser.","why":"*würde* + infinitif dans les deux parties ; *verbringen würde* à la fin de la subordonnée en *wenn*."}]},{"no":"2","instruction":"Ergänzen Sie: darum – weil – wegen.","instruction_en":"Complétez avec *darum*, *weil* ou *wegen*. Chaque mot est utilisé deux fois.","box":["darum","weil","wegen"],"items":[{"label":"a","text":"Viele Deutsche hören Majids Grammatikfehler nicht, ___ er eine sehr gute Aussprache hat.","gaps":[["weil"]],"solution":"Viele Deutsche hören Majids Grammatikfehler nicht, **weil** er eine sehr gute Aussprache hat.","en":"Beaucoup d'Allemands ne remarquent pas les fautes de grammaire de Majid, parce qu'il a une très bonne prononciation.","why":"Une cause, et le verbe *hat* est à la fin → **weil**.","source":"weil"},{"label":"b","text":"Mirko hat die Prüfung nicht bestanden, ___ will er jetzt einen Intensivkurs machen.","gaps":[["darum"]],"solution":"Mirko hat die Prüfung nicht bestanden, **darum** will er jetzt einen Intensivkurs machen.","en":"Mirko n'a pas réussi l'examen, c'est pourquoi il veut maintenant suivre un cours intensif.","why":"Une conséquence, et le verbe *will* vient juste après le trou → **darum**.","source":"darum"},{"label":"c","text":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, ___ braucht er sehr gute Deutschkenntnisse.","gaps":[["darum"]],"solution":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, **darum** braucht er sehr gute Deutschkenntnisse.","en":"Hassan veut travailler comme médecin dans un hôpital allemand, c'est pourquoi il a besoin de très bonnes connaissances d'allemand.","why":"Conséquence + verbe juste après le trou (*braucht er*) → **darum**.","source":"darum"},{"label":"d","text":"Camilla ist Managerin und kann ___ ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","gaps":[["wegen"]],"solution":"Camilla ist Managerin und kann **wegen** ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","en":"Camilla est manager et ne peut pas suivre régulièrement le cours d'allemand à cause de ses nombreuses conférences.","why":"Un groupe nominal suit (*ihrer vielen Konferenzen*, génitif pluriel) → **wegen**.","source":"wegen"},{"label":"e","text":"Boris wird ___ seines Akzents sofort als Russe erkannt.","gaps":[["wegen"]],"solution":"Boris wird **wegen** seines Akzents sofort als Russe erkannt.","en":"Boris est tout de suite reconnu comme Russe à cause de son accent.","why":"Groupe nominal au génitif (*seines Akzents*) → **wegen**.","source":"wegen"},{"label":"f","text":"Anja würde gern Arabisch lernen, ___ sie die arabische Schrift so schön findet.","gaps":[["weil"]],"solution":"Anja würde gern Arabisch lernen, **weil** sie die arabische Schrift so schön findet.","en":"Anja aimerait apprendre l'arabe, parce qu'elle trouve l'écriture arabe si belle.","why":"Une cause, avec le verbe *findet* à la fin → **weil**.","source":"weil"}]}]},{"page":"Test L4 · 20","heading":"Wortschatz","heading_en":"Vocabulaire","exercises":[{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Complétez le texte de Ferdez avec les mots de l'encadré. Chaque mot est utilisé une fois ; celui qui est barré est utilisé dans l'exemple. La fiche suit l'orthographe d'Allemagne avec l'eszett ; ici, orthographe suisse avec *ss* (*fliessend*).","box":["Akzent","fliessend","schimpfe","Muttersprache","Schrift","übersetzen","vergleiche"],"box_used":[3],"box_exact":true,"example":[{"label":"a","text":"Mein Name ist Ferdez. Ich komme aus Mazedonien. Meine **Muttersprache** ist Albanisch, aber ich spreche auch Mazedonisch."}],"items":[{"label":"b","text":"Im Mazedonischen wird die kyrillische ___ verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","gaps":[["Schrift"]],"solution":"Im Mazedonischen wird die kyrillische **Schrift** verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","en":"En macédonien, on utilise l'alphabet cyrillique. C'est pourquoi, au début, il n'était pas facile pour moi d'écrire en allemand.","why":"*die kyrillische Schrift* = l'alphabet cyrillique."},{"label":"c","text":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich ___ Deutsch, finde ich.","gaps":[["fliessend"]],"solution":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich **fliessend** Deutsch, finde ich.","en":"Je vis en Bavière depuis huit ans. Aujourd'hui, je parle couramment allemand, je trouve.","why":"*fliessend Deutsch sprechen* = parler couramment allemand."},{"label":"d","text":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen ___ habe!","gaps":[["Akzent"]],"solution":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen **Akzent** habe!","en":"Mais mes collègues du nord de l'Allemagne disent que j'ai un accent bavarois !","why":"*einen … Akzent haben* = avoir un accent ; *einen bayerischen* → nom masculin."},{"label":"e","text":"Wenn ich auf Bayerisch ___, lachen meine Kollegen sich kaputt.","gaps":[["schimpfe"]],"solution":"Wenn ich auf Bayerisch **schimpfe**, lachen meine Kollegen sich kaputt.","en":"Quand je rouspète en bavarois, mes collègues sont pliés de rire.","why":"*schimpfen* = rouspéter, jurer ; *ich schimpfe* à la fin de la subordonnée en *wenn*."},{"label":"f","text":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander ___, dann fällt mir auf, …","gaps":[["vergleiche"]],"solution":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander **vergleiche**, dann fällt mir auf, …","en":"Quand je compare l'allemand, le macédonien et l'albanais entre eux, je remarque …","why":"*miteinander vergleichen* = comparer entre eux ; *ich vergleiche* à la fin de la subordonnée en *wenn*."},{"label":"g","text":"… dass man nicht alle Wörter wirklich gut in die andere Sprache ___ kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","gaps":[["übersetzen"]],"solution":"… dass man nicht alle Wörter wirklich gut in die andere Sprache **übersetzen** kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","en":"… qu'on ne peut pas vraiment bien traduire tous les mots dans l'autre langue. Aujourd'hui, je me sens chez moi en Macédoine et en Allemagne.","why":"*in eine Sprache übersetzen* = traduire dans une langue ; l'infinitif se place avant *kann*, à la fin de la subordonnée en *dass*."}]},{"no":"Pause","instruction":"Was bedeutet das? Kreuzen Sie an. «Lügen haben kurze Beine.»","instruction_en":"Que signifie le proverbe « Lügen haben kurze Beine » (les mensonges ont les jambes courtes) ? Tapez A ou B.","items":[{"label":"A/B","lead":"A Die Wahrheit kommt immer schnell ans Licht. Darum sollte man nicht lügen.  B Wer lügt, der bekommt zur Strafe kurze Beine.","text":"___","gaps":[["A"]],"solution":"**A**","en":"A : La vérité éclate toujours vite. C'est pourquoi il ne faut pas mentir.","why":"Un mensonge ne va pas loin, comme quelqu'un qui a les jambes courtes : il est vite découvert. B joue sur le sens littéral des mots."}]},{"no":"4","instruction":"Welches Wort passt auch? Notieren Sie.","instruction_en":"Quel mot de l'encadré pourrait remplacer le mot souligné ? Écrivez-le. Chaque mot est utilisé une fois ; celui qui est barré est utilisé dans l'exemple. Les mots soulignés sont affichés en gras.","box":["allerdings","allmählich","aufschreiben","deswegen","ebenso","irgendwann","korrekt","stammt"],"box_used":[7],"box_exact":true,"example":[{"label":"a","text":"Meine Familie **kommt** aus Iran. → stammt"}],"items":[{"label":"b","lead":"Ich selbst bin **aber** in Mainz geboren.","text":"___","gaps":[["allerdings"]],"solution":"**allerdings**","en":"Moi, en revanche, je suis né à Mayence.","why":"*allerdings* = *aber* : il nuance ce qui a été dit avant."},{"label":"c","lead":"Mit mir haben meine Eltern immer Deutsch gesprochen, **deshalb** kann ich leider nicht Farsi.","text":"___","gaps":[["deswegen"]],"solution":"**deswegen**","en":"Mes parents ont toujours parlé allemand avec moi, c'est pourquoi je ne sais malheureusement pas parler farsi.","why":"*deswegen* = *deshalb* (conséquence, le verbe suit juste après).","source":"deswegen"},{"label":"d","lead":"Jetzt nehme ich an einem Sprachkurs teil. Ich finde, Farsi ist **genauso** schwierig wie Deutsch.","text":"___","gaps":[["ebenso"]],"solution":"**ebenso**","en":"Maintenant, je suis un cours de langue. Je trouve le farsi tout aussi difficile que l'allemand.","why":"*ebenso … wie* = *genauso … wie* = tout aussi … que."},{"label":"e","lead":"Besonders die Schrift! Ich bin ein Mensch, der sich alle neuen Wörter **notieren** muss.","text":"___","gaps":[["aufschreiben"]],"solution":"**aufschreiben**","en":"Surtout l'écriture ! Je suis quelqu'un qui doit noter tous les nouveaux mots.","why":"*sich etwas notieren* = *sich etwas aufschreiben* = noter quelque chose."},{"label":"f","lead":"Das ist schwierig, wenn man es in einer Schrift tun muss, die man auch erst **langsam** lernt.","text":"___","gaps":[["allmählich"]],"solution":"**allmählich**","en":"C'est difficile quand on doit le faire dans une écriture qu'on n'apprend que peu à peu.","why":"*allmählich* = lentement, pas à pas, peu à peu."},{"label":"g","lead":"Auch die Aussprache ist nicht leicht. Es gibt da diesen Laut «gh», den kann ich nicht **richtig** aussprechen.","text":"___","gaps":[["korrekt"]],"solution":"**korrekt**","en":"La prononciation n'est pas facile non plus. Il y a ce son « gh » que je n'arrive pas à prononcer correctement.","why":"*korrekt* = *richtig* = correctement."},{"label":"h","lead":"**Eines Tages** klappt es – hoffe ich jedenfalls!","text":"___","gaps":[["irgendwann","Irgendwann"]],"solution":"**irgendwann**","en":"Un jour, ça marchera – du moins je l'espère !","why":"*irgendwann* = à un moment donné, un jour = *eines Tages*."}]}]},{"page":"Test L4 · 21","heading":"Lesen","heading_en":"Lecture","exercises":[{"no":"5","instruction":"Lesen Sie und kreuzen Sie an: Was ist richtig?","instruction_en":"Lisez les réponses au sondage « Est-ce important d'apprendre l'allemand ? » et choisissez la bonne fin pour chaque phrase. Tapez la fin (ou seulement ses premiers mots).","reading":[{"label":"Brad, 30, aus Australien","text":"«Meine Freundin ist Deutsche. Deshalb bin ich vor einem Jahr nach Deutschland gekommen. Ich dachte, dass ich mit Englisch als Muttersprache keine Schwierigkeiten haben würde, einen Job zu finden. Aber immer wenn ich mich bewarb, bekam ich zur Antwort: Lernen Sie erst einmal richtig Deutsch. Dann können Sie wiederkommen. Offenbar glauben die Leute, dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht. Seit sechs Monaten besuche ich nun einen Deutschkurs.»"},{"label":"Alena, 24, aus Tschechien","text":"«Meine Grossmutter hat 30 Jahre in Wien gelebt. Ich habe sie als Kind oft besucht und Wien dabei sehr gut kennengelernt. Ich denke, ich habe in Wien bessere Karrierechancen als bei uns zu Hause. Darum habe ich jetzt das Zertifikat Deutsch gemacht. Mit dem Zertifikat habe ich bestimmt gute Chancen, wenn ich mich bei österreichischen Firmen bewerbe.»"},{"label":"Ewa, 23, aus Polen","text":"«Ich finde es aus historischen Gründen wichtig, Deutsch zu lernen. Denn Polen und Deutschland verbindet eine lange Geschichte, die nicht immer schön war. Aber gerade deshalb ist es wichtig, dass wir uns gegenseitig gut kennenlernen. Ich würde mir wünschen, dass auch mehr Deutsche sich für die polnische Sprache interessieren würden.»"},{"label":"Sopha, 32, aus Thailand","text":"«Mein Mann stammt aus Hessen. Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche. Aber jetzt gehen unsere beiden Söhne zur Schule, und ich habe gemerkt, dass meine Deutschkenntnisse nicht mehr ausreichend sind: In der Kommunikation mit der Klassenlehrerin und bei Elternabenden habe ich grosse Schwierigkeiten. Deshalb nehme ich jetzt an einem Deutschkurs für Eltern teil.»"},{"label":"Abdullah, 35, aus Bahrain","text":"«Ich arbeite seit ein paar Monaten an einer deutschen Klinik als Arzt. Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen. Im Krankenhaus brauche ich eigentlich gar nicht so viel Deutsch, denn für die Gespräche mit den Patienten genügt mein Deutsch, und die Kollegen sprechen alle sehr gut Englisch. Aber natürlich möchte ich die Sprache des Landes gut können, in dem ich lebe. Dann versteht man die Menschen und ihr Land besser. Aus diesem Grund lerne ich weiter Deutsch.»"},{"label":"Zeliha, 45, aus der Türkei","text":"«Ich bin nach Dortmund gekommen, als ich meinen Mann – einen Deutschtürken – geheiratet habe. Schnell kamen vier Kinder zur Welt. Das Geld war immer knapp bei uns, deswegen habe ich neben dem Haushalt und der Kindererziehung Schicht gearbeitet. Für einen Deutschkurs war nie Zeit und Geld da. Meine Kinder haben oft geschimpft, weil ich so schlecht Deutsch sprach. Jetzt lerne ich endlich richtig Deutsch, und meine Kinder helfen mir beim Lernen.»"}],"items":[{"label":"a","lead":"Wer gut Englisch kann, … ○ findet in Deutschland problemlos einen Job. ○ muss trotzdem gut Deutsch lernen.","text":"Wer gut Englisch kann, ___.","gaps":[["muss trotzdem gut Deutsch lernen","muss trotzdem"]],"solution":"Wer gut Englisch kann, **muss trotzdem gut Deutsch lernen**.","en":"Celui qui parle bien anglais doit quand même bien apprendre l'allemand.","why":"Brad, dont la langue maternelle est l'anglais, s'entendait dire sans cesse : *Lernen Sie erst einmal richtig Deutsch.*"},{"label":"b","lead":"Deutsche glauben offenbar, … ○ dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat. ○ dass man für eine Ausbildung Deutsch braucht.","text":"Deutsche glauben offenbar, ___.","gaps":[["dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat","dass man ohne perfektes Deutsch"]],"solution":"Deutsche glauben offenbar, **dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat**.","en":"Les Allemands croient apparemment que, sans un allemand parfait, on n'a pas de compétences professionnelles.","why":"Brad : *… dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht.*"},{"label":"c","lead":"Alena hofft, dass sie mit dem Zertifikat Deutsch … ○ eine Arbeitsstelle in Österreich findet. ○ besser Bewerbungen schreiben kann.","text":"Alena hofft, dass sie mit dem Zertifikat Deutsch ___.","gaps":[["eine Arbeitsstelle in Österreich findet","eine Arbeitsstelle"]],"solution":"Alena hofft, dass sie mit dem Zertifikat Deutsch **eine Arbeitsstelle in Österreich findet**.","en":"Alena espère trouver un emploi en Autriche grâce au certificat d'allemand.","why":"Alena compte sur de bonnes chances *bei österreichischen Firmen*."},{"label":"d","lead":"Als Polin will Ewa Deutsch können, denn … ○ Deutschland und Polen haben eine gemeinsame Geschichte. ○ sie hat viele Deutsche kennengelernt.","text":"Als Polin will Ewa Deutsch können, denn ___.","gaps":[["Deutschland und Polen haben eine gemeinsame Geschichte","Deutschland und Polen"]],"solution":"Als Polin will Ewa Deutsch können, denn **Deutschland und Polen haben eine gemeinsame Geschichte**.","en":"En tant que Polonaise, Ewa veut savoir l'allemand, car l'Allemagne et la Pologne ont une histoire commune.","why":"Ewa : *Denn Polen und Deutschland verbindet eine lange Geschichte.*"},{"label":"e","lead":"Ewa findet es … ○ toll, dass so viel Deutsche Polnisch sprechen. ○ schade, dass sich nicht so viele Deutsche für Polnisch interessieren.","text":"Ewa findet es ___.","gaps":[["schade, dass sich nicht so viele Deutsche für Polnisch interessieren","schade"]],"solution":"Ewa findet es **schade, dass sich nicht so viele Deutsche für Polnisch interessieren**.","en":"Ewa trouve dommage que peu d'Allemands s'intéressent au polonais.","why":"Ewa aimerait que davantage d'Allemands s'intéressent au polonais."},{"label":"f","lead":"Sopha hat … ○ von ihrem Mann Deutsch gelernt. ○ hat einen Integrationskurs besucht.","text":"Sopha hat ___.","gaps":[["von ihrem Mann Deutsch gelernt","von ihrem Mann"]],"solution":"Sopha hat **von ihrem Mann Deutsch gelernt**.","en":"Sopha a appris l'allemand avec son mari.","why":"Sopha : *Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche.*"},{"label":"g","lead":"Sie … ○ muss ihren Söhnen bei den Deutschhausaufgaben helfen. ○ hat Probleme, weil sie die Lehrer nicht gut genug versteht.","text":"Sie ___.","gaps":[["hat Probleme, weil sie die Lehrer nicht gut genug versteht","hat Probleme"]],"solution":"Sie **hat Probleme, weil sie die Lehrer nicht gut genug versteht**.","en":"Elle a des problèmes parce qu'elle ne comprend pas assez bien les enseignants.","why":"Avec l'enseignant de classe et aux soirées de parents, elle a *grosse Schwierigkeiten*."},{"label":"h","lead":"Für die Arbeitserlaubnis … ○ werden gute Deutschkenntnisse erwartet. ○ braucht man gar nicht so gute Deutschkenntnisse.","text":"Für die Arbeitserlaubnis ___.","gaps":[["werden gute Deutschkenntnisse erwartet","werden gute"]],"solution":"Für die Arbeitserlaubnis **werden gute Deutschkenntnisse erwartet**.","en":"Pour le permis de travail, on attend de bonnes connaissances d'allemand.","why":"Abdullah : *Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen.*"},{"label":"i","lead":"Abdullah will gut Deutsch können, weil … ○ die Patienten nicht Englisch sprechen. ○ er in Deutschland lebt.","text":"Abdullah will gut Deutsch können, weil ___.","gaps":[["er in Deutschland lebt"]],"solution":"Abdullah will gut Deutsch können, weil **er in Deutschland lebt**.","en":"Abdullah veut bien savoir l'allemand parce qu'il vit en Allemagne.","why":"Il veut connaître la langue *des Landes …, in dem ich lebe* ; son allemand suffit déjà pour les patients."},{"label":"j","lead":"Zeliha lernt Deutsch … ○ , weil sie Geld verdienen muss. ○ wegen ihrer Kinder.","text":"Zeliha lernt Deutsch ___.","gaps":[["wegen ihrer Kinder"]],"solution":"Zeliha lernt Deutsch **wegen ihrer Kinder**.","en":"Zeliha apprend l'allemand à cause de ses enfants.","why":"Ses enfants se plaignaient que son allemand soit si mauvais, et maintenant ils l'aident à apprendre."}]}]},{"page":"Test L4 · 22","heading":"Sprechen","heading_en":"Expression orale","exercises":[{"no":"7","instruction":"Welche Reaktion passt am besten? Verbinden Sie.","instruction_en":"Quelle réponse convient le mieux ? Écrivez le numéro de la réponse (1–6) après chaque phrase. (L'exercice 6 de cette page est une compréhension orale et n'est pas repris.)","example":[{"label":"a","text":"Darf ich Sie kurz etwas fragen? → **2** Natürlich, gern."}],"items":[{"label":"b","text":"Mein Name ist Kranitzky-Krampe. → ___","gaps":[["5"]],"solution":"Mein Name ist Kranitzky-Krampe. → **5**","en":"Je m'appelle Kranitzky-Krampe. → 5 Pardon, quel est votre nom, déjà ?","why":"Un nom long et inhabituel : vous redemandez."},{"label":"c","text":"Zu Kleidung kann man auch «Klamotten» sagen. → ___","gaps":[["4"]],"solution":"Zu Kleidung kann man auch «Klamotten» sagen. → **4**","en":"Pour « vêtements », on peut aussi dire « Klamotten ». → 4 Je n'ai jamais entendu ce mot.","why":"Un mot nouveau (familier) : *Das Wort habe ich noch nie gehört.*"},{"label":"d","text":"Was bedeutet dieses Wort? → ___","gaps":[["1"]],"solution":"Was bedeutet dieses Wort? → **1**","en":"Que signifie ce mot ? → 1 Je ne sais malheureusement pas non plus.","why":"Une réponse à une question à laquelle on ne sait pas répondre."},{"label":"e","text":"Da habe ich echt Schwein gehabt. → ___","gaps":[["6"]],"solution":"Da habe ich echt Schwein gehabt. → **6**","en":"J'ai vraiment eu de la chance. → 6 Si j'ai bien compris, vous avez eu de la chance ?","why":"*Schwein haben* (familier) = avoir de la chance ; vous vérifiez que vous avez bien compris."},{"label":"f","text":"Könnten Sie bitte langsamer sprechen? → ___","gaps":[["3"]],"solution":"Könnten Sie bitte langsamer sprechen? → **3**","en":"Pourriez-vous parler plus lentement, s'il vous plaît ? → 3 D'accord, je vais essayer.","why":"Une réponse à une demande."}],"phrases":["1 Das weiss ich leider auch nicht.","2 Natürlich, gern.","3 Okay, ich versuche es.","4 Das Wort habe ich noch nie gehört.","5 Wie war bitte Ihr Name?","6 Habe ich das richtig verstanden: Du hattest Glück?"]},{"no":"8","instruction":"Schreiben Sie die Fragen.","instruction_en":"Écrivez les questions indirectes avec les mots entre parenthèses. Dans une question indirecte, le verbe va à la fin.","example":[{"label":"a","lead":"(Bild: Ein Mann und eine Frau lesen zusammen in einem Buch.) Weisst du vielleicht, … (Aufgabe – wie?)","text":"Weisst du vielleicht, **wie ich diese Aufgaben machen muss**?"}],"items":[{"label":"b","lead":"(Bild: Zwei Männer stehen mit ihren Mülltonnen auf der Strasse.) Können Sie mir sagen, … (Müll – wohin?)","text":"Können Sie mir sagen, ___?","gaps":[["wohin ich den Müll bringen muss","wohin ich den Müll bringen soll"]],"solution":"Können Sie mir sagen, **wohin ich den Müll bringen muss**?","en":"Pouvez-vous me dire où je dois apporter les ordures ?","why":"*wohin* introduit la question indirecte ; le verbe conjugué *muss* va à la fin."},{"label":"c","lead":"(Bild: Eine Frau sitzt beim Arzt.) Können Sie mir bitte sagen, … (Schmerzen – wo?)","text":"Können Sie mir bitte sagen, ___?","gaps":[["wo Sie Schmerzen haben"]],"solution":"Können Sie mir bitte sagen, **wo Sie Schmerzen haben**?","en":"Pouvez-vous me dire, s'il vous plaît, où vous avez mal ?","why":"Le médecin demande : *wo* + sujet + verbe à la fin (*haben*)."},{"label":"d","lead":"(Bild: Eine Frau fragt einen Mann im Zug.) Wissen Sie vielleicht, … (Zug nach Berlin – ob?)","text":"Wissen Sie vielleicht, ___?","gaps":[["ob der Zug nach Berlin fährt","ob dieser Zug nach Berlin fährt","ob das der Zug nach Berlin ist"]],"solution":"Wissen Sie vielleicht, **ob der Zug nach Berlin fährt**?","en":"Savez-vous par hasard si le train va à Berlin ?","why":"Une question fermée (oui/non) devient indirecte avec *ob* ; le verbe *fährt* va à la fin."}]}]},{"page":"Test L4 · 23","heading":"Schreiben","heading_en":"Expression écrite","exercises":[{"no":"9","instruction":"Wählen Sie eine Sprache, die Sie gern lernen würden, und schreiben Sie eine Nachricht an die Sprachschule. – Schreiben Sie, für welche Sprache Sie sich interessieren. – Sagen Sie, wann und wie oft pro Woche Sie Zeit für den Kurs haben. – Fragen Sie, zu welchen Terminen/Zeiten die Sprachschule einen Kurs in Ihrer Wunschsprache anbietet. – Fragen Sie auch nach den Kursgebühren und der Kursdauer. – Bitten Sie um eine Antwort. – Denken Sie an die passende Anrede und den Gruss am Ende.","instruction_en":"Choisissez une langue que vous aimeriez apprendre et écrivez un message à l'école de langues : quelle langue, quand et combien de fois par semaine vous avez du temps, quels jours et horaires de cours l'école propose, le prix et la durée du cours ; demandez une réponse et utilisez une formule d'appel et une formule de politesse adaptées. La réponse modèle suit le corrigé officiel.","phrases":["… Damen und Herren,","ich würde gern …","Ich … und …","Bitte teilen Sie mir mit, …","Auch müsste ich wissen, …","Mit …","**LERNTIPP** Was sagt man in dieser Situation? Notieren und lernen Sie nicht nur einzelne neue Wörter. Wenn Sie sich zu verschiedenen Situationen passende Sätze und Ausdrücke aufschreiben, fühlen Sie sich in Gesprächen sicherer. Benutzen Sie zum Beispiel Karteikärtchen und schreiben Sie eine Situation oder ein Thema auf die Vorderseite: «nachfragen». Schreiben Sie Beispiele zum Thema auf die Rückseite und lernen Sie diese auswendig: «Was meinen Sie mit …?», «Was bedeutet …?» … Diese Methode eignet sich auch gut, wenn Sie sich auf ein Gespräch vorbereiten möchten. Überlegen Sie, was Sie sagen oder fragen möchten und was der Gesprächspartner sagen oder fragen könnte. Sicher können Sie während des Gesprächs einen Ihrer geübten Sätze anwenden."],"items":[{"label":"9","text":"","open":true,"solution":"**Sehr geehrte** Damen und Herren, ich würde gern **Neugriechisch lernen**. Ich **habe von Montag bis Donnerstag abends Zeit** und **könnte zweimal pro Woche kommen**. Bitte teilen Sie mir mit, **zu welchen Zeiten Sie einen Neugriechisch-Kurs anbieten**. Auch müsste ich wissen, **wie viel der Kurs kostet und wie lange er dauert**. **Ich bitte Sie um eine kurze Antwort.** Mit **freundlichen Grüssen** …","en":"Madame, Monsieur, j'aimerais apprendre le grec moderne. J'ai du temps du lundi au jeudi le soir et je pourrais venir deux fois par semaine. Veuillez m'indiquer à quels horaires vous proposez un cours de grec moderne. J'aurais aussi besoin de savoir combien coûte le cours et combien de temps il dure. Je vous prie de me faire parvenir une courte réponse. Meilleures salutations …","why":"Lettre formelle : *Sehr geehrte Damen und Herren* … *Mit freundlichen Grüssen*. Les questions sont indirectes (*zu welchen Zeiten …, wie viel …, wie lange …*) : verbe à la fin."}]}]}]},{"id":"04-zu-infinitiv-bewerbung","no":4,"title":"Infinitiv mit zu · Bewerbung · Test Lektion 5","title_en":"L'infinitif avec zu, la lettre de candidature, bavarder à propos du travail · Test de la leçon 5","added":"2026-11-12","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 5","sources":[{"id":"hueber","title":"Hueber : Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (corrigé officiel, Lektion 5)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g98","title":"grammis: Verben mit einem Infinitiv mit oder ohne zu (verbes de modalité sans zu ; brauchen avec zu)","url":"https://grammis.ids-mannheim.de/fragen/98"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (propositions infinitives avec zu)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"g4069","title":"grammis: Verbflexion (zu entre la particule et le verbe : anzurufen)","url":"https://grammis.ids-mannheim.de/progr@mm/4069"},{"id":"g6393","title":"grammis: Alternation von zu- und dass-Komplementen (subordonnée en dass ou zu + infinitif)","url":"https://grammis.ids-mannheim.de/korpusgrammatik/6393"},{"id":"g299310","title":"grammis: während (Präposition, avec le génitif)","url":"https://grammis.ids-mannheim.de/praepositionen/299310"},{"id":"prep","title":"grammis: Präpositionalphrase (les prépositions et les cas qu'elles régissent)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"}],"pages":[{"page":"AB 140","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Commence enfin à écrire des candidatures !","exercises":[{"no":"1","tag":"A1","instruction":"Ich habe leider keine Zeit …","instruction_en":"Je n'ai malheureusement pas le temps …","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Complétez chaque phrase avec un verbe de l'encadré. Chaque verbe est utilisé une fois ; celui qui est barré est utilisé dans l'exemple.","box":["mitzuarbeiten","auszuschalten","zu erklären","mitzukommen","zu sein","zu gehen"],"box_used":[5],"box_exact":true,"example":[{"label":"1","text":"Erlaubst du uns, ins Kino **zu gehen**?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd ___.","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, den Herd **auszuschalten**.","en":"N'oubliez pas d'éteindre la cuisinière, s'il vous plaît.","why":"*ausschalten* est un verbe à particule séparable, donc *zu* se place entre la particule et le verbe : *aus**zu**schalten*.","source":"g4069"},{"label":"3","text":"Ich habe Angst, nachts allein ___.","gaps":[["zu sein"]],"solution":"Ich habe Angst, nachts allein **zu sein**.","en":"J'ai peur d'être seul la nuit.","why":"*Angst haben* + *zu* + infinitif ; *sein* est un verbe simple, donc *zu* se place devant lui.","source":"g6865"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein ___.","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein **mitzuarbeiten**.","en":"Non, ce n'est pas trop stressant de donner un coup de main dans une association.","why":"*Es ist* + adjectif + *zu* + infinitif. *mitarbeiten* est séparable : *mit**zu**arbeiten*. (Le premier *zu* signifie ici « trop ».)","source":"g4069"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg ___.","gaps":[["zu erklären"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg **zu erklären**.","en":"Je n'ai malheureusement pas le temps de vous expliquer le chemin.","why":"*keine Zeit haben* + *zu* + infinitif. *erklären* n'est pas séparable (*er-* est un préfixe inséparable), donc *zu* se place devant lui.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, ins Training ___.","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, ins Training **mitzukommen**.","en":"Aujourd'hui, je n'ai pas envie de venir à l'entraînement.","why":"*keine Lust haben* + *zu* + infinitif ; *mitkommen* est séparable : *mit**zu**kommen*.","source":"g4069"}]},{"no":"1","part":"b","part_instruction":"Nach welchen Ausdrücken folgt *zu*? Markieren Sie in a wie im Beispiel.","part_instruction_en":"Quelles expressions sont suivies de *zu* ? Tapez l'expression (le verbe ou verbe + nom/adjectif) qui déclenche *zu* dans chaque phrase de a.","example":[{"label":"1","text":"**Erlaubst** du uns, ins Kino zu gehen?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd auszuschalten. → ___","gaps":[["Vergesst","Vergesst bitte nicht","vergessen","vergesst nicht"]],"solution":"Vergesst bitte nicht, den Herd auszuschalten. → **Vergesst**","en":"N'oubliez pas d'éteindre la cuisinière, s'il vous plaît. → oublier","why":"Le verbe *vergessen* (ici *Vergesst*) est suivi de *zu* + infinitif.","source":"hueber"},{"label":"3","text":"Ich habe Angst, nachts allein zu sein. → ___","gaps":[["habe Angst","Angst haben","Ich habe Angst","Angst"]],"solution":"Ich habe Angst, nachts allein zu sein. → **habe Angst**","en":"J'ai peur d'être seul la nuit. → avoir peur","why":"*haben* + nom (*Angst, Lust, Zeit, Interesse*) est suivi de *zu* + infinitif.","source":"hueber"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → ___","gaps":[["ist nicht zu stressig","es ist nicht zu stressig","ist stressig","stressig sein","es ist stressig","stressig"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → **ist nicht zu stressig**","en":"Non, ce n'est pas trop stressant de donner un coup de main dans une association. → être (pas trop) stressant","why":"*Es ist* + adjectif est suivi de *zu* + infinitif.","source":"hueber"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → ___","gaps":[["habe leider keine Zeit","habe keine Zeit","keine Zeit haben","Zeit haben","keine Zeit","Zeit"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → **habe leider keine Zeit**","en":"Je n'ai malheureusement pas le temps de vous expliquer le chemin. → (ne pas) avoir le temps","why":"*Zeit haben* (ici *keine Zeit*) est suivi de *zu* + infinitif.","source":"hueber"},{"label":"6","text":"Ich habe heute keine Lust, ins Training mitzukommen. → ___","gaps":[["habe heute keine Lust","habe keine Lust","keine Lust haben","Lust haben","keine Lust","Lust"]],"solution":"Ich habe heute keine Lust, ins Training mitzukommen. → **habe heute keine Lust**","en":"Aujourd'hui, je n'ai pas envie de venir à l'entraînement. → (ne pas) avoir envie","why":"*Lust haben* (ici *keine Lust*) est suivi de *zu* + infinitif.","source":"hueber"}]},{"no":"1","part":"c","part_instruction":"Wo steht *zu*? Ergänzen Sie die Tabelle mit den Sätzen aus a.","part_instruction_en":"Où se place *zu* ? Le tableau a trois colonnes : le début de la phrase, la partie du milieu, puis le verbe avec *zu*. Placez-y les phrases de a qui ont un verbe à particule séparable (2, 4, 6) et tapez la dernière colonne. Les éléments du verbe sont entre parenthèses.","example":[{"label":"1","text":"Erlaubst du uns, | ins Kino | **zu gehen**? (gehen)"}],"items":[{"label":"2","text":"Vergesst bitte nicht, | den Herd | ___. (aus·schalten)","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, | den Herd | **auszuschalten**. (aus·schalten)","en":"N'oubliez pas, s'il vous plaît, | la cuisinière | d'éteindre.","why":"Verbe à particule séparable : *zu* se place entre *aus* et *schalten*, et le tout s'écrit en un seul mot.","source":"g4069"},{"label":"4","text":"Nein, es ist nicht zu stressig, | in einem Verein | ___. (mit·arbeiten)","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, | in einem Verein | **mitzuarbeiten**. (mit·arbeiten)","en":"Non, ce n'est pas trop stressant | dans une association | de donner un coup de main.","why":"Verbe à particule séparable : *mit* + *zu* + *arbeiten*, en un seul mot.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, | ins Training | ___. (mit·kommen)","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, | ins Training | **mitzukommen**. (mit·kommen)","en":"Aujourd'hui, je n'ai pas envie | à l'entraînement | de venir.","why":"Verbe à particule séparable : *mit* + *zu* + *kommen*, en un seul mot.","source":"g4069"}]},{"no":"2","tag":"A1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Qu'est-ce qui est juste ? Tapez *zu* si la phrase a besoin de *zu*, ou *–* (un tiret) si elle n'a besoin de rien.","example":[{"label":"a","text":"Ich höre nicht auf, nach meinem Traumjob **zu** suchen."}],"items":[{"label":"b","text":"Möchten Sie nicht auch in Ihrem Traumberuf ___ arbeiten?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Möchten Sie nicht auch in Ihrem Traumberuf **–** arbeiten?","en":"Vous n'aimeriez pas, vous aussi, travailler dans le métier de vos rêves ?","why":"Après un verbe de modalité (*möchten*), l'infinitif ne prend jamais *zu*.","source":"g98"},{"label":"c","text":"Ich könnte mir gut vorstellen, ein Handwerk ___ lernen.","gaps":[["zu"]],"solution":"Ich könnte mir gut vorstellen, ein Handwerk **zu** lernen.","en":"Je pourrais bien m'imaginer apprendre un métier artisanal.","why":"*sich vorstellen können* introduit une deuxième proposition après la virgule, avec *zu* + infinitif. *könnte* se rapporte seulement à *vorstellen*.","source":"g6865"},{"label":"d","text":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz ___ finden.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz **–** finden.","en":"Avec une formation d'artisan, on peut trouver un bon emploi.","why":"Verbe de modalité *kann* + infinitif sans *zu*.","source":"g98"},{"label":"e","text":"Könnten Sie mir bei der Berufswahl ___ helfen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Könnten Sie mir bei der Berufswahl **–** helfen?","en":"Pourriez-vous m'aider à choisir un métier ?","why":"*Könnten* est un verbe de modalité (Konjunktiv II de *können*) : pas de *zu*.","source":"g98"},{"label":"f","text":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten ___ informieren.","gaps":[["zu"]],"solution":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten **zu** informieren.","en":"C'est assez stressant de s'informer sur les possibilités professionnelles.","why":"*Es ist* + adjectif (*stressig*) + *zu* + infinitif.","source":"g6865"}]},{"no":"3","tag":"A1","marker":"◇","instruction":"Ergänzen Sie: *zu* oder *–*.","instruction_en":"Complétez avec *zu*, ou tapez *–* (un tiret) là où rien ne manque.","example":[{"label":"a","text":"Ich habe schon einmal angefangen, das Bewerbungsgespräch vor**zu**bereiten."}],"items":[{"label":"b","text":"Wir dürfen den Geburtstag der Chefin nicht ___ vergessen!","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Wir dürfen den Geburtstag der Chefin nicht **–** vergessen!","en":"Nous ne devons pas oublier l'anniversaire de la cheffe !","why":"Verbe de modalité *dürfen* + infinitif sans *zu*.","source":"g98"},{"label":"c","text":"Es ist nicht leicht, eine Stelle in seinem Traumjob ___ finden.","gaps":[["zu"]],"solution":"Es ist nicht leicht, eine Stelle in seinem Traumjob **zu** finden.","en":"Ce n'est pas facile de trouver un poste dans le métier de ses rêves.","why":"*Es ist nicht leicht* + *zu* + infinitif.","source":"g6865"},{"label":"d","text":"Ich würde am liebsten in einem Team ___ arbeiten.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Ich würde am liebsten in einem Team **–** arbeiten.","en":"Ce que je préférerais, c'est travailler dans une équipe.","why":"*würde* + infinitif (Konjunktiv II) fonctionne comme un verbe de modalité : pas de *zu*.","source":"g98"},{"label":"e","text":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung ___ helfen?","gaps":[["zu"]],"solution":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung **zu** helfen?","en":"Tu aurais un moment pour m'aider avec ma candidature ?","why":"*Zeit haben* + *zu* + infinitif.","source":"g6865"},{"label":"f","text":"Kannst du dir eine Lehre im Büro vor ___ stellen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Kannst du dir eine Lehre im Büro vor **–** stellen?","en":"Tu peux t'imaginer faire un apprentissage dans un bureau ?","why":"*Kannst* est un verbe de modalité, donc rien ne s'insère : *vorstellen* s'écrit en un seul mot.","source":"g98"}]}]},{"page":"AB 141","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Commence enfin à écrire des candidatures !","exercises":[{"no":"4","instruction":"Schreiben Sie Sätze.","instruction_en":"Écrivez des phrases sur votre vie professionnelle : combinez une expression de l'encadré de gauche avec une activité de l'encadré de droite. Les mots barrés sont utilisés dans l'exemple. La réponse modèle n'est qu'une possibilité.","box":["(keine) Lust haben","möchten","hoffen","Freude machen","können","sich vorstellen können","würde … gern","anstrengend sein","…","ein halbes Jahr um die Welt reisen","am Abend arbeiten","(nicht) immer dasselbe machen","sehr gut selbstständig arbeiten","mit netten Kollegen zusammenarbeiten","Neues lernen","wenig Freizeit haben"],"box_used":[0,1,10],"example":[{"label":"Beispiel","text":"Ich habe keine Lust, am Abend **zu arbeiten**. Ich möchte in meinem Berufsleben …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich möchte in meinem Berufsleben nicht immer dasselbe machen. Ich hoffe, mit netten Kollegen zusammenzuarbeiten. Es macht mir Freude, Neues zu lernen. Ich kann sehr gut selbstständig arbeiten. Es ist anstrengend, wenig Freizeit zu haben. Ich würde gern ein halbes Jahr um die Welt reisen.","en":"Dans ma vie professionnelle, je ne veux pas toujours faire la même chose. J'espère travailler avec des collègues sympathiques. J'aime apprendre de nouvelles choses. Je sais très bien travailler de façon autonome. C'est fatigant d'avoir peu de temps libre. J'aimerais bien faire le tour du monde pendant six mois.","why":"Après *hoffen, Freude machen, sich vorstellen können, anstrengend sein, Lust haben*, employez *zu* + infinitif (verbes à particule séparable : *zusammen**zu**arbeiten*). Après *möchten, können, würde … gern*, pas de *zu*.","source":"g98"}]},{"no":"5","instruction":"Ordnen Sie zu und schreiben Sie Sätze mit *zu*.","instruction_en":"Associez chaque affirmation à un verbe de l'encadré et écrivez une phrase avec *zu* + infinitif. Le verbe barré est utilisé dans l'exemple.","box":["sich vorstellen können","versuchen","aufhören","versprechen","vorhaben"],"box_used":[1],"example":[{"label":"a","lead":"Morgen will ich pünktlich sein. Vielleicht!","text":"versuchen: Morgen versuche ich, pünktlich **zu sein**."}],"items":[{"label":"b","lead":"Ich hole dich morgen ab. Ganz sicher.","text":"","accept":["Ich verspreche, dich morgen abzuholen.","Ich verspreche dir, dich morgen abzuholen.","versprechen: Ich verspreche, dich morgen abzuholen."],"solution":"**Ich verspreche, dich morgen abzuholen.**","en":"Je promets de venir te chercher demain.","why":"« Certainement » = une promesse : *versprechen*. *abholen* est séparable : *ab**zu**holen*.","source":"hueber"},{"label":"c","lead":"Einen interessanten Job finden! Das ist mein Plan.","text":"","accept":["Ich habe vor, einen interessanten Job zu finden.","vorhaben: Ich habe vor, einen interessanten Job zu finden."],"solution":"**Ich habe vor, einen interessanten Job zu finden.**","en":"J'ai l'intention de trouver un travail intéressant.","why":"Un projet = *vorhaben* : *Ich habe vor, … zu finden.* La particule *vor* va à la fin de la principale.","source":"hueber"},{"label":"d","lead":"Ein Handwerk lernen? Ja, warum eigentlich nicht?","text":"","accept":["Ich kann mir vorstellen, ein Handwerk zu lernen.","Ich kann mir gut vorstellen, ein Handwerk zu lernen.","sich vorstellen können: Ich kann mir vorstellen, ein Handwerk zu lernen."],"solution":"**Ich kann mir vorstellen, ein Handwerk zu lernen.**","en":"Je peux m'imaginer apprendre un métier artisanal.","why":"« Pourquoi pas ? » = vous pouvez l'imaginer : *Ich kann mir vorstellen, … zu lernen.*","source":"hueber"},{"label":"e","lead":"Ich arbeite als Pflegefachmann. Aber nur noch bis Ende Monat.","text":"","accept":["Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.","Ende Monat höre ich auf, als Pflegefachmann zu arbeiten.","aufhören: Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten."],"solution":"**Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.**","en":"À la fin du mois, j'arrête de travailler comme infirmier.","why":"« Seulement jusqu'à la fin du mois » = arrêter : *aufhören*, avec *auf* à la fin de la principale, avant la virgule.","source":"hueber"}]},{"no":"6","instruction":"Markieren Sie noch neun Wörter und ordnen Sie zu.","instruction_en":"Trouvez neuf autres mots dans la grille de lettres et placez-les dans les offres d'emploi A–C. Les mots entourés (*Bewerbung, Tätigkeit*) sont les exemples. Tapez chaque mot sous la forme que demande la phrase (majuscule pour les noms).","reading":[{"label":"Buchstabengitter","text":"AUFGABENSGBESCHÄFTIGSTIBEWERBUNGTERWARTENZTÄTIGKEIT\nBEWERBUNGSUNTERLAGENZYTWHANDELUTPOÜKENNTNISSENKWAQ\nUNTERSTÜTZUNGMUSJÄMTILVORAUSSETZUNGDUQSCHRIFTLICHLW"},{"label":"A  Heimpflegedienst Bachmann","text":"Wir suchen für 15 Stunden pro Woche … (1) für den Patientenfahrdienst.\n… (2) für die Tätigkeit ist: + Führerausweis Kategorie B + … (3) in Erster Hilfe + Freude an der Arbeit mit Menschen\nEs … (4) Sie: + interessante … (5) + Weiterbildungsmöglichkeiten + ein angenehmes Betriebsklima\nBitte schicken Sie Ihre Bewerbung an personal@hpfd-bachmann.ch"},{"label":"B","text":"Detailhandelsassistent/in für unser kleines Modegeschäft gesucht!\nErfahrung im … (1) und Verkauf von Vorteil. Wenden Sie sich bei Fragen … (2) oder telefonisch an Frau Kleinert: kleinert@neuemode.ch / 031 330 110 10."},{"label":"C","text":"HAST DU HANDWERKLICHES TALENT?\n… (1) du dich gern mit Holz? Dann komm zu uns! Wir bieten dir eine Lehrstelle als Schreiner/in EFZ.\nSchick deine … (2) noch heute an: Clemens Meier (cl.meier@schreinerei-meier.ch)"}],"example":[{"label":"A","text":"… für die **Tätigkeit** ist: … Bitte schicken Sie Ihre **Bewerbung** an personal@hpfd-bachmann.ch"}],"items":[{"label":"A1","text":"Wir suchen für 15 Stunden pro Woche ___ für den Patientenfahrdienst.","gaps":[["Unterstützung"]],"solution":"Wir suchen für 15 Stunden pro Woche **Unterstützung** für den Patientenfahrdienst.","en":"Nous cherchons du renfort pour notre service de transport de patients, 15 heures par semaine.","why":"*die Unterstützung* = soutien, aide ; ici, une personne qui aide.","source":"hueber"},{"label":"A2","text":"___ für die Tätigkeit ist: Führerausweis Kategorie B","gaps":[["Voraussetzung"]],"solution":"**Voraussetzung** für die Tätigkeit ist: Führerausweis Kategorie B","en":"Condition requise pour ce poste : permis de conduire catégorie B","why":"*die Voraussetzung* = condition requise, prérequis. *der Führerausweis* est le mot suisse pour le permis de conduire.","source":"hueber"},{"label":"A3","text":"+ ___ in Erster Hilfe","gaps":[["Kenntnisse"]],"solution":"+ **Kenntnisse** in Erster Hilfe","en":"+ connaissances en premiers secours","why":"*Kenntnisse in* + datif = connaissances en, compétences en.","source":"hueber"},{"label":"A4","text":"Es ___ Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","gaps":[["erwarten"]],"solution":"Es **erwarten** Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","en":"Ce qui vous attend : des tâches intéressantes, des possibilités de formation continue, une bonne ambiance de travail","why":"*Es erwarten Sie …* = « … vous attendent » ; *es* occupe seulement la position 1, le verbe s'accorde avec le sujet au pluriel qui suit.","source":"hueber"},{"label":"A5","text":"+ interessante ___","gaps":[["Aufgaben"]],"solution":"+ interessante **Aufgaben**","en":"+ des tâches intéressantes","why":"*die Aufgabe, die Aufgaben* = tâche(s) ; *interessante* indique un pluriel.","source":"hueber"},{"label":"B1","text":"Erfahrung im ___ und Verkauf von Vorteil.","gaps":[["Handel"]],"solution":"Erfahrung im **Handel** und Verkauf von Vorteil.","en":"Une expérience dans le commerce et la vente est un atout.","why":"*der Handel* = commerce ; *im* = *in dem*. *von Vorteil* = un atout.","source":"hueber"},{"label":"B2","text":"Wenden Sie sich bei Fragen ___ oder telefonisch an Frau Kleinert.","gaps":[["schriftlich"]],"solution":"Wenden Sie sich bei Fragen **schriftlich** oder telefonisch an Frau Kleinert.","en":"Pour toute question, adressez-vous par écrit ou par téléphone à Mme Kleinert.","why":"*schriftlich oder telefonisch* = par écrit ou par téléphone.","source":"hueber"},{"label":"C1","text":"___ du dich gern mit Holz?","gaps":[["Beschäftigst"]],"solution":"**Beschäftigst** du dich gern mit Holz?","en":"Tu aimes travailler le bois ?","why":"*sich beschäftigen mit* = s'occuper de ; *du beschäftigst dich*. Le mot ouvre la question fermée (réponse oui ou non), il prend donc une majuscule.","source":"hueber"},{"label":"C2","text":"Schick deine ___ noch heute an: Clemens Meier","gaps":[["Bewerbungsunterlagen"]],"solution":"Schick deine **Bewerbungsunterlagen** noch heute an: Clemens Meier","en":"Envoie ton dossier de candidature dès aujourd'hui à : Clemens Meier","why":"*die Bewerbungsunterlagen* (pluriel) = CV, certificats et lettre réunis.","source":"hueber"}]}]},{"page":"AB 142","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Commence enfin à écrire des candidatures !","exercises":[{"no":"7","tag":"A2","instruction":"Ergänzen Sie in der richtigen Form: *brauchen – müssen*.","instruction_en":"Complétez avec la bonne forme de *brauchen* ou *müssen*. Astuce : *brauchen* se construit avec *zu* + infinitif et une négation ou *nur* ; *müssen* n'est jamais suivi de *zu*.","example":[{"label":"a","text":"Ich **brauche** nur die neuen Wörter zu lernen, dann schaffe ich die Prüfung schon."}],"items":[{"label":"b","text":"Dein Zeugnis ist doch so gut. Du ___ dir wirklich keine Gedanken um einen Job zu machen.","gaps":[["brauchst"]],"solution":"Dein Zeugnis ist doch so gut. Du **brauchst** dir wirklich keine Gedanken um einen Job zu machen.","en":"Ton bulletin est pourtant si bon. Tu n'as vraiment pas besoin de te faire du souci pour trouver un emploi.","why":"Négation (*keine*) + *zu machen* : *brauchen … zu* = *nicht müssen*.","source":"g98"},{"label":"c","text":"Wenn sie nur Teilzeit arbeitet, dann ___ sie nicht den ganzen Tag am Computer sitzen.","gaps":[["muss"]],"solution":"Wenn sie nur Teilzeit arbeitet, dann **muss** sie nicht den ganzen Tag am Computer sitzen.","en":"Si elle ne travaille qu'à temps partiel, elle ne doit pas rester assise toute la journée devant l'ordinateur.","why":"L'infinitif *sitzen* n'a pas de *zu*, donc le verbe est *müssen* : *sie muss … sitzen*.","source":"g98"},{"label":"d","text":"Wenn wir für drei Monate ins Ausland reisen wollen, dann ___ wir jetzt viel Geld sparen.","gaps":[["müssen"]],"solution":"Wenn wir für drei Monate ins Ausland reisen wollen, dann **müssen** wir jetzt viel Geld sparen.","en":"Si nous voulons voyager trois mois à l'étranger, nous devons économiser beaucoup d'argent dès maintenant.","why":"Ni *zu* ni négation : c'est une obligation, donc *müssen*.","source":"g98"}]},{"no":"8","tag":"A2","instruction":"Mein Traumjob. Schreiben Sie Sätze mit *brauchen … zu*.","instruction_en":"Le métier de mes rêves. Écrivez des phrases avec *brauchen … zu* + infinitif (= ne pas devoir / ne devoir que).","example":[{"label":"a","lead":"(nicht früh aufstehen)","text":"In meinem Traumjob **brauche ich nicht früh aufzustehen**."}],"items":[{"label":"b","lead":"(keine langweiligen Aufgaben übernehmen)","text":"","accept":["Ich brauche keine langweiligen Aufgaben zu übernehmen.","In meinem Traumjob brauche ich keine langweiligen Aufgaben zu übernehmen."],"solution":"**Ich brauche keine langweiligen Aufgaben zu übernehmen.**","en":"Je n'ai pas besoin de me charger de tâches ennuyeuses.","why":"*brauchen* en position 2, *zu übernehmen* à la fin. *übernehmen* n'est pas séparable ici, donc *zu* se place devant lui.","source":"g98"},{"label":"c","lead":"(keine Überstunden machen)","text":"","accept":["Ich brauche keine Überstunden zu machen.","In meinem Traumjob brauche ich keine Überstunden zu machen."],"solution":"**Ich brauche keine Überstunden zu machen.**","en":"Je n'ai pas besoin de faire des heures supplémentaires.","why":"*keine* + *brauchen … zu* = aucune obligation.","source":"g98"},{"label":"d","lead":"(nur arbeiten, wenn ich Lust dazu habe)","text":"","accept":["Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.","In meinem Traumjob brauche ich nur zu arbeiten, wenn ich Lust dazu habe."],"solution":"**Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.**","en":"Je n'ai besoin de travailler que quand j'en ai envie.","why":"*nur brauchen … zu* = ne devoir que. *zu arbeiten* termine la principale avant la subordonnée en *wenn*.","source":"g98"},{"label":"e","lead":"(nicht mit unfreundlichen Kollegen zusammenarbeiten)","text":"","accept":["Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.","In meinem Traumjob brauche ich nicht mit unfreundlichen Kollegen zusammenzuarbeiten."],"solution":"**Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.**","en":"Je n'ai pas besoin de travailler avec des collègues désagréables.","why":"*zusammenarbeiten* est séparable : *zusammen**zu**arbeiten*, en un seul mot.","source":"g4069"}]},{"no":"9","tag":"A4","instruction":"Ein Bewerbungsschreiben","instruction_en":"Une lettre de candidature","part":"a","part_instruction":"Lesen Sie und ordnen Sie.","part_instruction_en":"Lisez les parties de la lettre et mettez-les dans le bon ordre : tapez le numéro (1–8) de chaque partie. Les parties portent ici les lettres A–H, dans l'ordre où le livre les imprime ; B est l'exemple.","example":[{"label":"B","text":"Bewerbung als Verkäufer von E-Bikes → **1**"}],"items":[{"label":"A","text":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → ___","gaps":[["5"]],"solution":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → **5**","en":"J'apprends facilement de nouvelles choses. En outre, j'aime conseiller les clients. C'est pourquoi j'aimerais travailler chez vous comme vendeur. → 5","why":"La raison pour laquelle vous voulez le poste vient après votre expérience (4) et avant la demande finale (6).","source":"hueber"},{"label":"C","text":"Freundliche Grüsse / Tibor Kelemen → ___","gaps":[["7"]],"solution":"Freundliche Grüsse / Tibor Kelemen → **7**","en":"Meilleures salutations / Tibor Kelemen → 7","why":"La formule de politesse et votre nom viennent après la dernière phrase.","source":"hueber"},{"label":"D","text":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → ___","gaps":[["3"]],"solution":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → **3**","en":"J'ai lu votre annonce avec grand intérêt et je pose ma candidature pour le poste vacant de vendeur de vélos électriques. → 3","why":"La première phrase après la formule d'appel indique pour quel poste vous postulez.","source":"hueber"},{"label":"E","text":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → ___","gaps":[["6"]],"solution":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → **6**","en":"Je serais heureux d'être convié à un entretien. → 6","why":"La dernière phrase standard d'une lettre de candidature.","source":"hueber"},{"label":"F","text":"Beilagen: Lebenslauf, Arbeitszeugnisse → ___","gaps":[["8"]],"solution":"Beilagen: Lebenslauf, Arbeitszeugnisse → **8**","en":"Annexes : CV, certificats de travail → 8","why":"Les *Beilagen* (annexes) viennent tout à la fin, sous le nom.","source":"hueber"},{"label":"G","text":"Sehr geehrte Damen und Herren → ___","gaps":[["2"]],"solution":"Sehr geehrte Damen und Herren → **2**","en":"Madame, Monsieur → 2","why":"La formule d'appel suit la ligne d'objet. En Suisse, on ne met pas de virgule après.","source":"hueber"},{"label":"H","text":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → ___","gaps":[["4"]],"solution":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → **4**","en":"Comme vous pouvez le voir dans mon dossier, après avoir terminé l'école secondaire, j'ai fait une formation de mécanicien vélo dans l'entreprise « Velo-XL ». J'ai ensuite travaillé deux ans comme employé dans un magasin de vélos et j'ai aussi pu acquérir une première expérience dans la vente. → 4","why":"Votre formation et votre expérience viennent après la phrase d'introduction.","source":"hueber"}]}]},{"page":"AB 143","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Commence enfin à écrire des candidatures !","exercises":[{"no":"9","part":"b","part_instruction":"Ergänzen Sie das Bewerbungsschreiben. Hilfe finden Sie in a.","part_instruction_en":"Complétez la lettre de candidature. Vous trouverez de l'aide en a.","reading":[{"label":"Lerntipp","text":"Ein Bewerbungsschreiben muss fehlerfrei sein! Notieren Sie zuerst Ihre typischen Fehler. Überprüfen Sie dann Ihren Text pro Fehlertyp einmal. Lassen Sie Ihre Bewerbung am Ende noch einmal von einem Muttersprachler Korrektur lesen."}],"example":[{"label":"1","text":"Bewerbung **als** Physiotherapeutin im Altersheim"}],"items":[{"label":"2","text":"Sehr ___ Frau Zerlich","gaps":[["geehrte"]],"solution":"Sehr **geehrte** Frau Zerlich","en":"Madame Zerlich","why":"*Sehr geehrte Frau …*, *Sehr geehrter Herr …* : la terminaison dépend de la personne.","source":"hueber"},{"label":"3","text":"___ habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","gaps":[["Mit grossem Interesse"]],"solution":"**Mit grossem Interesse** habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","en":"J'ai lu votre offre d'emploi avec grand intérêt et je pose ma candidature pour le poste de physiothérapeute.","why":"Formule d'introduction fixe de a ; elle occupe la position 1, donc le verbe *habe* suit.","source":"hueber"},{"label":"4","text":"Wie Sie ___ entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","gaps":[["meinen Unterlagen"]],"solution":"Wie Sie **meinen Unterlagen** entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","en":"Comme vous pouvez le voir dans mon dossier, après ma formation de physiothérapeute en Pologne, j'ai travaillé quatre ans dans un hôpital à Lodz.","why":"*etwas (Dativ) entnehmen* = tirer une information de quelque chose : *meinen Unterlagen* est un datif pluriel.","source":"hueber"},{"label":"5","text":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch ___ im Bereich der Sportmedizin sammeln.","gaps":[["Erfahrungen","erste Erfahrungen"]],"solution":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch **Erfahrungen** im Bereich der Sportmedizin sammeln.","en":"J'ai ensuite travaillé deux ans au cabinet Kunz & Rosenthal. J'ai aussi pu y acquérir de l'expérience dans le domaine de la médecine du sport.","why":"*Erfahrungen sammeln* = acquérir de l'expérience.","source":"hueber"},{"label":"6","text":"___ ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","gaps":[["Meine Muttersprache"]],"solution":"**Meine Muttersprache** ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","en":"Ma langue maternelle est le polonais. Mais je parle aussi très bien l'allemand et l'anglais.","why":"*die Muttersprache* = langue maternelle ; *meine* parce que le mot est féminin.","source":"hueber"},{"label":"7","text":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es ___ grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","gaps":[["macht mir"]],"solution":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es **macht mir** grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","en":"Le poste dans une maison de retraite est quelque chose de complètement nouveau pour moi. J'aime beaucoup apprendre de nouvelles choses. En outre, j'aime m'occuper des autres et je me réjouis du contact avec les résidents.","why":"*Es macht mir Freude, … zu* + infinitif, comme en a.","source":"hueber"},{"label":"8","text":"Über eine Einladung ___ würde ich mich freuen.","gaps":[["zu einem persönlichen Gespräch"]],"solution":"Über eine Einladung **zu einem persönlichen Gespräch** würde ich mich freuen.","en":"Je serais heureuse d'être conviée à un entretien.","why":"Phrase finale fixe : *eine Einladung zu* + datif.","source":"hueber"},{"label":"9","text":"___ Alina Jankowska","gaps":[["Freundliche Grüsse"]],"solution":"**Freundliche Grüsse** Alina Jankowska","en":"Meilleures salutations, Alina Jankowska","why":"Formule de politesse ; orthographe suisse *Grüsse*.","source":"hueber"}]},{"no":"9","part":"c","part_instruction":"Wählen Sie ein Stelleninserat und schreiben Sie eine Bewerbung.","part_instruction_en":"Choisissez une des trois offres d'emploi du Zirkus Tortellini et écrivez une lettre de candidature. Utilisez les parties de a et b. La réponse modèle n'est qu'une possibilité.","reading":[{"label":"1","text":"Zirkus Tortellini sucht Dompteur/-in\nWir erwarten: + Ausbildung als Tierpfleger/-in + Erfahrung mit wilden Tieren (Tiger, …)\nInfos und Bewerbung bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"2","text":"Sind Sie ein fröhlicher, positiver Mensch? Dann arbeiten Sie bei uns als Clown/-in\nSie haben Berufserfahrung als Kleinkinderzieher/-in oder als Schauspieler/-in? Sie können gut mit Kindern umgehen und haben viele lustige Ideen? Dann sind Sie die Richtige oder der Richtige für uns!\nGleich bewerben bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"3","text":"Wir suchen zwei Artisten für unseren Zirkus.\nSie haben: + eine Ausbildung als Tänzer/-in + erste Berufserfahrung an einem Theater gesammelt oder schon als Artist/-in in einem Zirkus gearbeitet\nSenden Sie Ihre Bewerbung an Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"}],"example":[{"label":"Beispiel","text":"Sehr geehrter Herr Tortellini / Mit grossem Interesse …"}],"items":[{"label":"1","lead":"Inserat 3: Artist/-in","text":"","open":true,"solution":"Bewerbung als Artistin / Sehr geehrter Herr Tortellini / Mit grossem Interesse habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Artistin in Ihrem Zirkus. Wie Sie meinen Unterlagen entnehmen können, habe ich eine Ausbildung als Tänzerin gemacht. Danach habe ich drei Jahre an einem Theater in Bern getanzt und dort erste Erfahrungen auf der Bühne gesammelt. Es macht mir grosse Freude, vor Publikum aufzutreten. Ich kann mir gut vorstellen, mit Ihrem Zirkus durch die Schweiz zu reisen. Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. / Freundliche Grüsse / Lara Steiner / Beilagen: Lebenslauf, Arbeitszeugnis","en":"Candidature au poste d'acrobate / Monsieur Tortellini / J'ai lu votre offre d'emploi avec grand intérêt et je pose ma candidature pour le poste d'acrobate dans votre cirque. Comme vous pouvez le voir dans mon dossier, j'ai suivi une formation de danseuse. J'ai ensuite dansé trois ans dans un théâtre à Berne, où j'ai acquis une première expérience de la scène. J'aime beaucoup me produire devant un public. Je peux bien m'imaginer voyager à travers la Suisse avec votre cirque. Je serais heureuse d'être conviée à un entretien. / Meilleures salutations / Lara Steiner / Annexes : CV, certificat de travail","why":"Les huit mêmes parties qu'en a ; chacune répond à un point de l'annonce (formation de danseuse, première expérience dans un théâtre). *auf**zu**treten* : *auftreten* est séparable.","source":"g4069"}]}]},{"page":"AB 144","heading":"B  Während seines letzten Schuljahres …","heading_en":"Pendant sa dernière année d'école …","exercises":[{"no":"10","tag":"B1","instruction":"Ergänzen Sie in der richtigen Form: *während – innerhalb – ausserhalb*.","instruction_en":"Complétez avec *während* (pendant), *innerhalb* (dans un délai de) ou *ausserhalb* (en dehors de), plus le mot entre parenthèses à la bonne forme. Les trois se construisent avec le génitif.","example":[{"label":"a","text":"Man sollte schon **während der** (die) Schulzeit Schnupperlehren machen."}],"items":[{"label":"b","lead":"(wenige)","text":"Vielen Dank für Ihre Bewerbung. Sie erhalten ___ Wochen unsere Antwort.","gaps":[["innerhalb weniger"]],"solution":"Vielen Dank für Ihre Bewerbung. Sie erhalten **innerhalb weniger** Wochen unsere Antwort.","en":"Merci beaucoup pour votre candidature. Vous recevrez notre réponse dans un délai de quelques semaines.","why":"Un délai = *innerhalb* ; génitif pluriel sans article : *weniger Wochen*.","source":"prep"},{"label":"c","lead":"(unsere)","text":"Sie rufen ___ Geschäftszeiten an. Diese sind von …","gaps":[["ausserhalb unserer"]],"solution":"Sie rufen **ausserhalb unserer** Geschäftszeiten an. Diese sind von …","en":"Vous appelez en dehors de nos heures d'ouverture. Celles-ci sont de …","why":"En dehors d'une période = *ausserhalb* ; génitif pluriel *unserer Geschäftszeiten*.","source":"prep"},{"label":"d","lead":"(die)","text":"Sie können sich ___ Wartezeit gern einen Kaffee nehmen.","gaps":[["während der"]],"solution":"Sie können sich **während der** Wartezeit gern einen Kaffee nehmen.","en":"Pendant l'attente, vous pouvez volontiers vous servir un café.","why":"En même temps que = *während* ; génitif féminin *der Wartezeit*.","source":"g299310"},{"label":"e","lead":"(die)","text":"Die Firma möchte ihre Ergebnisse ___ nächsten zwei Jahre um 20 % verbessern.","gaps":[["innerhalb der"]],"solution":"Die Firma möchte ihre Ergebnisse **innerhalb der** nächsten zwei Jahre um 20 % verbessern.","en":"L'entreprise veut améliorer ses résultats de 20 % au cours des deux prochaines années.","why":"Un délai = *innerhalb* ; génitif pluriel *der nächsten zwei Jahre*.","source":"prep"}]},{"no":"11","tag":"B2","instruction":"Ordnen Sie zu.","instruction_en":"Complétez l'interview avec les prépositions de temps de l'encadré. Chacune est utilisée une fois ; *während* figure deux fois dans l'encadré. Le *von … an* barré est utilisé dans l'exemple.","phrases":["ausserhalb","bei","von … bis","nach","von … an (Beispiel)","Vor","während","während"],"reading":[{"label":"Karrierestart","text":"Technikerin HF Maschinenbau – ein Beruf auch für Mädchen? Interview mit Samira\nKarrierestart: Warum machst du eine Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie lange dauert die Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie sieht dein Arbeitstag aus?\nKarrierestart: Welche Erfahrungen hast du als Frau … deiner Arbeit gemacht?"}],"example":[{"label":"d","text":"Ich durfte **von** Anfang **an** selbstständig Probleme lösen."}],"items":[{"label":"a","text":"Technik hat mich schon immer interessiert. Schon ___ meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","gaps":[["während"]],"solution":"Technik hat mich schon immer interessiert. Schon **während** meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","en":"La technique m'a toujours intéressée. Déjà pendant ma scolarité, j'ai travaillé chez un électricien.","why":"*während* + génitif (*meiner Schulzeit*) = pendant.","source":"g299310"},{"label":"b","text":"Gleich ___ der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","gaps":[["nach"]],"solution":"Gleich **nach** der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","en":"Juste après l'école, j'ai fait un stage dans une grande entreprise d'énergie.","why":"*nach* + datif (*der Schule*) = après.","source":"prep"},{"label":"c","text":"Aber schon ___ des ersten Jahres lernt man die wichtigsten Dinge kennen.","gaps":[["während"]],"solution":"Aber schon **während** des ersten Jahres lernt man die wichtigsten Dinge kennen.","en":"Mais dès la première année, on apprend les choses les plus importantes.","why":"*während* + génitif *des ersten Jahres*.","source":"g299310"},{"label":"e","text":"___ der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","gaps":[["Vor"]],"solution":"**Vor** der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","en":"Avant l'examen final, je dois quand même encore beaucoup apprendre.","why":"*vor* + datif (*der Abschlussprüfung*) = avant ; majuscule en début de phrase.","source":"prep"},{"label":"f","text":"Ich bin ___ morgens ___ zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","gaps":[["von"],["bis"]],"solution":"Ich bin **von** morgens **bis** zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","en":"Du matin jusqu'à la fin de la journée de travail, je me déplace sur le site de notre entreprise et je répare des installations.","why":"*von … bis* = de … jusqu'à ; *bis zum Feierabend* (*zum* = *zu dem*).","source":"prep"},{"label":"g","text":"Welche Erfahrungen hast du als Frau ___ deiner Arbeit gemacht?","gaps":[["bei"]],"solution":"Welche Erfahrungen hast du als Frau **bei** deiner Arbeit gemacht?","en":"Quelles expériences as-tu faites en tant que femme dans ton travail ?","why":"*bei* + datif (*deiner Arbeit*) = au cours de, dans le cadre de.","source":"prep"},{"label":"h","text":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also ___ der Arbeitszeit.","gaps":[["ausserhalb"]],"solution":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also **ausserhalb** der Arbeitszeit.","en":"Que des bonnes ! Mes collègues et moi, nous nous retrouvons souvent le soir, donc en dehors des heures de travail.","why":"*ausserhalb* + génitif (*der Arbeitszeit*) = en dehors de.","source":"prep"}]},{"no":"12","tag":"B2","instruction":"Lesen Sie den Text und schliessen Sie die Lücken 1–6. Welche Lösung (a, b oder c) passt am besten?","instruction_en":"Préparation à l'examen : lisez l'e-mail et complétez les trous 1–6. Quelle option (a, b ou c) convient le mieux ? Tapez le mot (ou sa lettre).","reading":[{"label":"E-Mail senden","text":"Sehr (0) Herr Nemati\nVielen Dank (1) Ihre Bewerbung als Automobil-Mechatroniker. Wir freuen uns über Ihr (2) an unserer Firma und laden Sie zu einem Vorstellungsgespräch am 25. Mai um 11.30 Uhr ein. Bitte geben Sie uns (3) der nächsten Tage Bescheid, (4) Sie zu diesem Termin kommen können. Bringen Sie noch folgende (5) mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat. Für Fragen und weitere Informationen (6) wir Ihnen gern zur Verfügung.\nFreundliche Grüsse\nFranziska Leumann – Garage Leumann"}],"example":[{"label":"0","lead":"a geehrter · b lieber · c freundlicher","text":"Sehr **geehrter** Herr Nemati"}],"items":[{"label":"1","lead":"a um · b für · c bei","text":"Vielen Dank ___ Ihre Bewerbung als Automobil-Mechatroniker.","gaps":[["für","b","b für"]],"solution":"Vielen Dank **für** Ihre Bewerbung als Automobil-Mechatroniker.","en":"Merci beaucoup pour votre candidature au poste de mécatronicien automobile.","why":"*Vielen Dank für* + accusatif.","source":"hueber"},{"label":"2","lead":"a Bewerbung · b Interesse · c Mitarbeit","text":"Wir freuen uns über Ihr ___ an unserer Firma …","gaps":[["Interesse","b","b Interesse"]],"solution":"Wir freuen uns über Ihr **Interesse** an unserer Firma …","en":"Nous nous réjouissons de l'intérêt que vous portez à notre entreprise …","why":"*Interesse an* + datif = intérêt pour ; *Ihr* correspond au neutre *das Interesse*.","source":"hueber"},{"label":"3","lead":"a innerhalb · b ausserhalb · c bis","text":"Bitte geben Sie uns ___ der nächsten Tage Bescheid, …","gaps":[["innerhalb","a","a innerhalb"]],"solution":"Bitte geben Sie uns **innerhalb** der nächsten Tage Bescheid, …","en":"Veuillez nous donner une réponse dans les prochains jours …","why":"Un délai avec le génitif (*der nächsten Tage*) = *innerhalb*. *bis* demanderait *bis zum …*.","source":"prep"},{"label":"4","lead":"a wenn · b wann · c ob","text":"…, ___ Sie zu diesem Termin kommen können.","gaps":[["ob","c","c ob"]],"solution":"…, **ob** Sie zu diesem Termin kommen können.","en":"… si vous pouvez venir à ce rendez-vous.","why":"Une question indirecte fermée (réponse oui ou non) exige *ob* (si).","source":"hueber"},{"label":"5","lead":"a Zeugnisse · b Sachen · c Dokumente","text":"Bringen Sie noch folgende ___ mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","gaps":[["Dokumente","c","c Dokumente"]],"solution":"Bringen Sie noch folgende **Dokumente** mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","en":"Veuillez apporter aussi les documents suivants : l'original de votre certificat d'école professionnelle et votre certificat B2.","why":"Un certificat et un diplôme sont des *Dokumente* ; *Zeugnisse* ne couvrirait pas aussi le certificat B2, et *Sachen* est trop vague pour une lettre formelle.","source":"hueber"},{"label":"6","lead":"a stellen · b stehen · c haben","text":"Für Fragen und weitere Informationen ___ wir Ihnen gern zur Verfügung.","gaps":[["stehen","b","b stehen"]],"solution":"Für Fragen und weitere Informationen **stehen** wir Ihnen gern zur Verfügung.","en":"Nous restons volontiers à votre disposition pour toute question ou information complémentaire.","why":"Expression fixe : *jemandem zur Verfügung stehen* = être à la disposition de quelqu'un.","source":"hueber"}]}]},{"page":"AB 145","heading":"B  Während seines letzten Schuljahres …","heading_en":"Pendant sa dernière année d'école …","exercises":[{"no":"14","tag":"B3","instruction":"Verbinden Sie.","instruction_en":"Associez chaque question ou remarque d'un entretien d'embauche à la réponse (1–7). Tapez le numéro. (L'exercice 13 est une compréhension orale et n'est pas repris.)","phrases":["1 Ich war zuständig für die Kontrolle von Haushalts-, Garten- und Freizeitartikeln.","2 Ich beherrsche die üblichen Programme und habe mich letztes Jahr im Bereich Lagerdatenbank weitergebildet.","3 Ja, ich würde gern wissen, wie gross das Lager hier ist.","4 Vielen Dank auch Ihnen.","5 Vielen Dank.","6 Ja, ich spreche drei Sprachen.","7 Also, ich bin Baumaschinenmechaniker und mache gerade den Führerausweis Kategorie BE."],"example":[{"label":"a","text":"Guten Tag, Herr Trantow. Nehmen Sie doch bitte Platz. → **5** Vielen Dank."}],"items":[{"label":"b","text":"Erzählen Sie doch bitte etwas über sich. → ___","gaps":[["7"]],"solution":"Erzählen Sie doch bitte etwas über sich. → **7**","en":"Parlez-nous un peu de vous, s'il vous plaît. → 7 Eh bien, je suis mécanicien en machines de chantier et je passe mon permis de conduire catégorie BE.","why":"Vous vous présentez : votre métier et ce que vous faites actuellement.","source":"hueber"},{"label":"c","text":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → ___","gaps":[["1"]],"solution":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → **1**","en":"Quelles tâches aviez-vous chez votre dernier employeur ? → 1 J'étais responsable du contrôle des articles de ménage, de jardin et de loisirs.","why":"*zuständig sein für* = être responsable de (vos tâches).","source":"hueber"},{"label":"d","text":"Haben Sie noch andere Fähigkeiten? → ___","gaps":[["6"]],"solution":"Haben Sie noch andere Fähigkeiten? → **6**","en":"Avez-vous d'autres compétences ? → 6 Oui, je parle trois langues.","why":"Une question fermée sur les compétences : *Ja, …*","source":"hueber"},{"label":"e","text":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → ___","gaps":[["2"]],"solution":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → **2**","en":"Pouvez-vous m'en dire plus sur vos connaissances en informatique ? → 2 Je connais les programmes courants et j'ai suivi l'an dernier une formation continue sur les bases de données d'entrepôt.","why":"*beherrschen* = maîtriser ; *sich weiterbilden* = suivre une formation continue.","source":"hueber"},{"label":"f","text":"Haben Sie noch eine Frage? → ___","gaps":[["3"]],"solution":"Haben Sie noch eine Frage? → **3**","en":"Avez-vous encore une question ? → 3 Oui, j'aimerais savoir quelle est la taille de l'entrepôt ici.","why":"Une question indirecte : *wie gross das Lager hier ist* (verbe à la fin).","source":"hueber"},{"label":"g","text":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → ___","gaps":[["4"]],"solution":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → **4**","en":"Merci beaucoup d'être venu, Monsieur Trantow. → 4 Merci à vous aussi.","why":"Vous retournez le remerciement : *Vielen Dank auch Ihnen.*","source":"hueber"}]},{"no":"15","tag":"B3","instruction":"Das kann ich! Ergänzen Sie Informationen über sich.","instruction_en":"Je sais le faire ! Complétez les phrases avec des informations sur vous. Les réponses modèles ne sont qu'une possibilité.","items":[{"label":"a","lead":"Ich habe schon während der Schulzeit/des Studiums …","text":"","open":true,"solution":"Ich habe schon während der Schulzeit in einem Café gejobbt.","en":"Déjà pendant ma scolarité, j'avais un petit boulot dans un café.","why":"*während* + génitif ; Perfekt avec le participe à la fin.","source":"g299310"},{"label":"b","lead":"Ich bin/war zuständig für …","text":"","open":true,"solution":"Ich war zuständig für die Buchhaltung in einem kleinen Büro.","en":"J'étais responsable de la comptabilité dans un petit bureau.","why":"*zuständig für* + accusatif.","source":"hueber"},{"label":"c","lead":"Ich beherrsche …","text":"","open":true,"solution":"Ich beherrsche Excel und die üblichen Office-Programme.","en":"Je maîtrise Excel et les programmes de bureautique courants.","why":"*beherrschen* + accusatif = maîtriser une compétence ou une langue.","source":"hueber"},{"label":"d","lead":"Ich habe auch (sehr) gute Kenntnisse in …","text":"","open":true,"solution":"Ich habe auch sehr gute Kenntnisse in Englisch und Italienisch.","en":"J'ai aussi de très bonnes connaissances en anglais et en italien.","why":"*Kenntnisse in* + datif.","source":"hueber"},{"label":"e","lead":"Es fällt mir leicht, …","text":"","open":true,"solution":"Es fällt mir leicht, im Team zu arbeiten und auf neue Kunden zuzugehen.","en":"Il m'est facile de travailler en équipe et d'aller vers de nouveaux clients.","why":"*Es fällt mir leicht* + *zu* + infinitif ; *zugehen* est séparable : *zu**zu**gehen*.","source":"g4069"}]}]},{"page":"AB 146","heading":"C  Berufsberatung","heading_en":"Orientation professionnelle","exercises":[{"no":"16","tag":"C2","instruction":"Was ist richtig? Lesen Sie und kreuzen Sie an.","instruction_en":"Qu'est-ce qui est juste ? Lisez les textes. Tapez *richtig* (juste) ou *falsch* (faux) après chaque phrase ; dans le livre, vous cochez seulement les phrases justes.","reading":[{"label":"Was wollt ihr werden? – Jacqueline","text":"Ich gehe noch zur Schule. Nächstes Jahr mache ich die Matura. Ein Studium ist aber nichts für mich. Das dauert zu lange. Planung und Organisation sind kein Problem für mich. Deshalb möchte ich einen kaufmännischen Beruf ergreifen. Kommenden Montag habe ich einen Termin bei der Berufsberatung."},{"label":"Konstantinos","text":"In der Schule war ich gut in Mathematik und Kunst. Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte. Und ich wollte auch künstlerisch tätig sein. Aber ich wusste nicht, wie ich das zusammenbringen sollte. Deshalb bin ich zur Berufsberatung gegangen. Der Berater hat mir eine Lehre als Zeichner Landschaftsarchitektur empfohlen. Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt."}],"items":[{"label":"a","text":"Jacqueline hat keine Lust zu studieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Jacqueline hat keine Lust zu studieren. → **richtig**","en":"Jacqueline n'a pas envie de faire des études. → juste","why":"*Ein Studium ist aber nichts für mich. Das dauert zu lange.*","source":"hueber"},{"label":"b","text":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → ___","gaps":[["falsch","f","nein"]],"solution":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → **falsch**","en":"Elle trouve difficile de planifier ou d'organiser quelque chose. → faux","why":"Le contraire : *Planung und Organisation sind kein Problem für mich.*","source":"hueber"},{"label":"c","text":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → **richtig**","en":"La semaine prochaine, elle veut se renseigner sur les formations commerciales. → juste","why":"*Kommenden Montag habe ich einen Termin bei der Berufsberatung*, au sujet d'un métier commercial.","source":"hueber"},{"label":"d","text":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → ___","gaps":[["richtig","r","ja"]],"solution":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → **richtig**","en":"Konstantinos avait l'intention de travailler dans le domaine de la technique après l'école. → juste","why":"*Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte.*","source":"hueber"},{"label":"e","text":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → ___","gaps":[["richtig","r","ja"]],"solution":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → **richtig**","en":"Au début, il a trouvé difficile de combiner ses centres d'intérêt. → juste","why":"*Aber ich wusste nicht, wie ich das zusammenbringen sollte.*","source":"hueber"},{"label":"f","text":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → ___","gaps":[["falsch","f","nein"]],"solution":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → **falsch**","en":"Il s'attendait à ce que l'apprentissage de dessinateur en architecture paysagère lui plaise. → faux","why":"*Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt* = il ne s'y attendait pas.","source":"hueber"}]},{"no":"17","tag":"C2","instruction":"Schreiben Sie Sätze (a–e). Ordnen Sie dann den passenden Ratschlag (1–5) zu.","instruction_en":"Écrivez une phrase avec *zu* + infinitif pour chaque consigne (a–e). Trouvez ensuite le conseil (1–5) qui correspond ; la solution indique son numéro.","phrases":["1 Du könntest Busfahrer werden.","2 Dann werde doch Schreiner.","3 Hm, schwierig. Vielleicht Modedesigner?","4 Wie wäre es mit einer Tätigkeit als Bäcker?","5 An deiner Stelle würde ich Köchin werden."],"example":[{"label":"a","lead":"sich gut vorstellen können – im handwerklichen Bereich arbeiten","text":"**Ich kann mir gut vorstellen, im handwerklichen Bereich zu arbeiten.** → 2"}],"items":[{"label":"b","lead":"es nicht schwer finden – früh aufstehen","text":"","accept":["Ich finde es nicht schwer, früh aufzustehen.","Es fällt mir nicht schwer, früh aufzustehen."],"solution":"**Ich finde es nicht schwer, früh aufzustehen.** → 4","en":"Je ne trouve pas difficile de me lever tôt. → 4 Et un emploi de boulanger ?","why":"*Ich finde es* + adjectif + *zu* + infinitif ; *aufstehen* est séparable : *auf**zu**stehen*. Les boulangers commencent très tôt.","source":"g4069","check":"Le corrigé officiel écrit *Es fällt mir nicht schwer, früh aufzustehen*, ce qui signifie la même chose ; la consigne *es nicht schwer finden* donne *Ich finde es nicht schwer, …*. Les deux phrases sont correctes."},{"label":"c","lead":"Lust haben – viel unterwegs sein","text":"","accept":["Ich habe Lust, viel unterwegs zu sein."],"solution":"**Ich habe Lust, viel unterwegs zu sein.** → 1","en":"J'ai envie d'être beaucoup en déplacement. → 1 Tu pourrais devenir chauffeur de bus.","why":"*Lust haben* + *zu* + infinitif.","source":"g6865"},{"label":"d","lead":"Freude machen – für andere kochen","text":"","accept":["Es macht mir Freude, für andere zu kochen.","Mir macht es Freude, für andere zu kochen."],"solution":"**Es macht mir Freude, für andere zu kochen.** → 5","en":"J'aime cuisiner pour les autres. → 5 À ta place, je deviendrais cuisinier.","why":"*Es macht mir Freude* + *zu* + infinitif.","source":"g6865"},{"label":"e","lead":"Interesse haben – Neues entwickeln","text":"","accept":["Ich habe Interesse daran, Neues zu entwickeln.","Ich habe Interesse, Neues zu entwickeln."],"solution":"**Ich habe Interesse daran, Neues zu entwickeln.** → 3","en":"Ça m'intéresse de développer de nouvelles choses. → 3 Hmm, difficile. Peut-être styliste ?","why":"*Interesse haben (daran)* + *zu* + infinitif ; *daran* annonce la proposition en *zu*.","source":"g6865"}]},{"no":"18","tag":"C2","instruction":"Wörter mit -ng","instruction_en":"Mots en -ng","part":"a","part_instruction":"Bilden Sie Wörter mit *-ung*.","part_instruction_en":"Formez des noms en *-ung* à partir des verbes, avec l'article. (Les parties b–d sont des compréhensions orales et ne sont pas reprises.)","example":[{"label":"1","text":"beraten → **die Beratung**"},{"label":"4","text":"entwickeln → **die Entwicklung**"}],"items":[{"label":"2","text":"erfahren → ___","gaps":[["die Erfahrung","Erfahrung"]],"solution":"erfahren → **die Erfahrung**","en":"vivre, découvrir → expérience","why":"Radical du verbe + *-ung* ; les noms en *-ung* sont toujours féminins : *die*.","source":"hueber"},{"label":"3","text":"verantworten → ___","gaps":[["die Verantwortung","Verantwortung"]],"solution":"verantworten → **die Verantwortung**","en":"être responsable de → responsabilité","why":"Radical *verantwort-* + *-ung* : *die Verantwortung*.","source":"hueber"},{"label":"5","text":"beschäftigen → ___","gaps":[["die Beschäftigung","Beschäftigung"]],"solution":"beschäftigen → **die Beschäftigung**","en":"employer / occuper → emploi, occupation","why":"Radical *beschäftig-* + *-ung*.","source":"hueber"},{"label":"6","text":"unterstützen → ___","gaps":[["die Unterstützung","Unterstützung"]],"solution":"unterstützen → **die Unterstützung**","en":"soutenir → soutien","why":"Radical *unterstütz-* + *-ung*.","source":"hueber"}]}]},{"page":"AB 147","heading":"D  Small Talk: Von der Arbeit erzählen","heading_en":"Small talk : parler du travail","exercises":[{"no":"19","tag":"D2","instruction":"Ordnen Sie zu.","instruction_en":"Complétez le dialogue de small talk entre Bettina (○) et un ami (◆) avec les expressions des deux encadrés (réunis ici en un seul). Chaque expression est utilisée une fois ; celle qui est barrée est utilisée dans l'exemple.","box":["es ist total stressig","Hast du noch nie daran gedacht","muss zwei Kollegen vertreten","Hast du immer noch so viel Arbeit","schon mehrere Bewerbungen geschrieben","suche immer noch eine Stelle","Wie läuft's denn so","Ist das nicht anstrengend","machst du jetzt eigentlich genau","habe kein Interesse","komme gut mit den Kunden und den Kollegen zurecht","muss jetzt leider gehen"],"box_used":[6],"box_exact":true,"example":[{"label":"a","text":"◆ Hoi, Bettina. Das ist aber schön, dich zu sehen. **Wie läuft's denn so** mit der Jobsuche?"}],"items":[{"label":"b","text":"○ Schwierig. Ich ___ als Übersetzerin.","gaps":[["suche immer noch eine Stelle"]],"solution":"○ Schwierig. Ich **suche immer noch eine Stelle** als Übersetzerin.","en":"○ Difficile. Je cherche toujours un poste de traductrice.","why":"Après *Ich* vient le verbe *suche*.","source":"hueber"},{"label":"c","text":"○ Ich habe ___, aber nur Absagen erhalten.","gaps":[["schon mehrere Bewerbungen geschrieben"]],"solution":"○ Ich habe **schon mehrere Bewerbungen geschrieben**, aber nur Absagen erhalten.","en":"○ J'ai déjà écrit plusieurs candidatures, mais je n'ai reçu que des refus.","why":"Perfekt : *habe … geschrieben*, comme *erhalten*.","source":"hueber"},{"label":"d","text":"◆ ___, dich selbstständig zu machen? Das machen doch viele Übersetzer.","gaps":[["Hast du noch nie daran gedacht"]],"solution":"◆ **Hast du noch nie daran gedacht**, dich selbstständig zu machen? Das machen doch viele Übersetzer.","en":"◆ Tu n'as jamais pensé à te mettre à ton compte ? Beaucoup de traducteurs le font.","why":"*daran denken* + *zu* + infinitif ; *daran* annonce la proposition en *zu*.","source":"hueber"},{"label":"e","text":"○ Ja, das stimmt. Aber ___, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","gaps":[["es ist total stressig"]],"solution":"○ Ja, das stimmt. Aber **es ist total stressig**, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","en":"○ Oui, c'est vrai. Mais c'est vraiment stressant de toujours chercher des mandats. Et en plus, il y a beaucoup de concurrence.","why":"*Es ist* + adjectif + *zu* + infinitif.","source":"hueber"},{"label":"f","text":"○ Aber wie geht es dir denn? ___?","gaps":[["Hast du immer noch so viel Arbeit"]],"solution":"○ Aber wie geht es dir denn? **Hast du immer noch so viel Arbeit**?","en":"○ Mais toi, comment vas-tu ? Tu as toujours autant de travail ?","why":"La réponse *Ja, leider* exige une question fermée (réponse oui ou non).","source":"hueber"},{"label":"g","text":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich ___. Und das jetzt, wo wir so viele Aufträge haben!","gaps":[["muss zwei Kollegen vertreten"]],"solution":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich **muss zwei Kollegen vertreten**. Und das jetzt, wo wir so viele Aufträge haben!","en":"◆ Oui, malheureusement. Dans notre entreprise, plusieurs personnes sont malades en ce moment. Je dois remplacer deux collègues. Et ça maintenant, alors que nous avons tant de commandes !","why":"*vertreten* = remplacer quelqu'un.","source":"hueber"},{"label":"h","text":"○ Was ___?","gaps":[["machst du jetzt eigentlich genau"]],"solution":"○ Was **machst du jetzt eigentlich genau**?","en":"○ Au fait, qu'est-ce que tu fais exactement maintenant ?","why":"Une question avec un mot interrogatif : *Was* + verbe *machst* + *du*.","source":"hueber"},{"label":"i","lead":"◆ Ich bin als Heizungsinstallateur tätig. Ich habe die Verantwortung für zwei Baustellen und soll nebenbei die Baustellen meiner Kollegen betreuen.","text":"○ ___, immer von Baustelle zu Baustelle zu fahren?","gaps":[["Ist das nicht anstrengend"]],"solution":"○ **Ist das nicht anstrengend**, immer von Baustelle zu Baustelle zu fahren?","en":"○ Ce n'est pas fatigant d'aller toujours d'un chantier à l'autre ?","why":"*Ist das nicht anstrengend, … zu* + infinitif ?","source":"hueber"},{"label":"j","text":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich ___. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","gaps":[["komme gut mit den Kunden und den Kollegen zurecht"]],"solution":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich **komme gut mit den Kunden und den Kollegen zurecht**. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","en":"◆ Parfois si, mais la plupart du temps, j'aime mon travail. Je m'entends bien avec les clients et les collègues. Au fait, mon entreprise cherche justement quelqu'un pour le bureau. Tu ne veux pas postuler ?","why":"*mit jemandem gut zurechtkommen* = bien s'entendre avec quelqu'un (verbe à particule séparable).","source":"hueber"},{"label":"k","text":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich ___ an einer Tätigkeit als Sekretärin.","gaps":[["habe kein Interesse"]],"solution":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich **habe kein Interesse** an einer Tätigkeit als Sekretärin.","en":"○ Mais qu'est-ce que tu t'imagines ! Je suis traductrice. Un poste de secrétaire ne m'intéresse pas.","why":"*Interesse an* + datif (*an einer Tätigkeit*).","source":"hueber"},{"label":"l","lead":"◆ Warum nicht? Als Übersetzerin sitzt du doch auch am Computer, schreibst und telefonierst. Der Job ist sicher und unsere Firma zahlt nicht schlecht. Überleg es dir doch einmal.","text":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich ___.","gaps":[["muss jetzt leider gehen"]],"solution":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich **muss jetzt leider gehen**.","en":"○ D'accord, je vais le faire. Merci pour le conseil. Oh, je dois malheureusement y aller maintenant.","why":"Une façon typique de terminer une conversation de small talk.","source":"hueber"}]},{"no":"20","tag":"D2","instruction":"Ergänzen Sie.","instruction_en":"Complétez les petites annonces. Le livre donne quelques lettres de chaque mot ; tapez le mot en entier.","example":[{"label":"Beispiel","text":"In den Semesterferien **jobben** – …"}],"items":[{"label":"A","lead":"Ü _ _ _ s _ tz _ _ /in","text":"In den Semesterferien jobben – wir suchen dich als ___/in von kurzen Werbetexten.","gaps":[["Übersetzer"]],"solution":"In den Semesterferien jobben – wir suchen dich als **Übersetzer**/in von kurzen Werbetexten.","en":"Un job pendant les vacances semestrielles : nous te cherchons comme traducteur ou traductrice de courts textes publicitaires.","why":"*der Übersetzer / die Übersetzerin* = traducteur / traductrice.","source":"hueber"},{"label":"B","lead":"A _ f _ _ ä _ _ n","text":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach ___ suchen.","gaps":[["Aufträgen"]],"solution":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach **Aufträgen** suchen.","en":"Travailler à son compte comme aide de ménage : sur Putzfee.net, vous pouvez proposer vos services et chercher des mandats.","why":"*der Auftrag, die Aufträge* = commande, mandat ; *nach* + datif pluriel ajoute *-n* : *Aufträgen*.","source":"hueber"},{"label":"C1","lead":"F _ _ _ b _ _ _ _ g","text":"Machen Sie eine ___. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","gaps":[["Fortbildung"]],"solution":"Machen Sie eine **Fortbildung**. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","en":"Suivez une formation continue. Nous proposons des séminaires intéressants dans les domaines de la technique et du commerce.","why":"*eine Fortbildung machen* = suivre une formation continue.","source":"hueber"},{"label":"C2","lead":"K _ _ k _ _ _ e _ z","text":"Denn die ___ schläft nicht!","gaps":[["Konkurrenz"]],"solution":"Denn die **Konkurrenz** schläft nicht!","en":"Car la concurrence ne dort pas !","why":"*die Konkurrenz* = la concurrence (les rivaux).","source":"hueber"},{"label":"D","lead":"v _ _ tr _ _ _ n","text":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter ___ können.","gaps":[["vertreten"]],"solution":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter **vertreten** können.","en":"Flexible et motivé ? Nous cherchons des personnes qui peuvent remplacer nos collaborateurs d'entrepôt, sur une base horaire.","why":"Verbe de modalité *können* + infinitif *vertreten* (sans *zu*).","source":"hueber"}]}]},{"page":"AB 148","heading":"Test Lektion 5","heading_en":"Test de la leçon 5","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Complétez les phrases. Le livre donne quelques lettres de chaque mot ; tapez le mot en entier.","example":[{"label":"d","text":"Frau Angst will bald **aufhören** zu arbeiten und in Pension gehen."}],"items":[{"label":"a","lead":"A _ _ t _ ä _ e","text":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele ___.","gaps":[["Aufträge"]],"solution":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele **Aufträge**.","en":"L'entreprise Müller & Müller est très bonne et a donc beaucoup de commandes.","why":"*der Auftrag, die Aufträge* = commande(s) ; *viele* exige le pluriel."},{"label":"b","lead":"V _ r _ n _ w _ _ t _ _ g","text":"Frau Brügger hat die ___ für 200 Mitarbeiter.","gaps":[["Verantwortung"]],"solution":"Frau Brügger hat die **Verantwortung** für 200 Mitarbeiter.","en":"Mme Brügger est responsable de 200 collaborateurs.","why":"*die Verantwortung für* + accusatif = la responsabilité de."},{"label":"c","lead":"_ t _ _ _ _ … h _ _","text":"Die Firma ___ die Möbel aus Schweizer Holz ___.","gaps":[["stellt"],["her"]],"solution":"Die Firma **stellt** die Möbel aus Schweizer Holz **her**.","en":"L'entreprise fabrique les meubles en bois suisse.","why":"*herstellen* = fabriquer, produire ; séparable : *stellt … her*."},{"label":"e","lead":"S _ _ v _ _ _ a _ g _ _ _ _ _ _ _ _ r","text":"Mario ist als ___ in einem Restaurant tätig.","gaps":[["Serviceangestellter"]],"solution":"Mario ist als **Serviceangestellter** in einem Restaurant tätig.","en":"Mario travaille comme serveur dans un restaurant.","why":"*der Serviceangestellte* = serveur (usage suisse) ; après *als* sans article, la terminaison est *-er* : *als Serviceangestellter*."},{"label":"f","lead":"z _ st _ _ _ _ g","text":"Peter ist ___ für die Kontrolle und Reparatur der Werkzeugmaschinen.","gaps":[["zuständig"]],"solution":"Peter ist **zuständig** für die Kontrolle und Reparatur der Werkzeugmaschinen.","en":"Peter est responsable du contrôle et de la réparation des machines-outils.","why":"*zuständig sein für* = être responsable de."},{"label":"g","lead":"F _ _ _ b _ _ d _ _ g _ n","text":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele ___ an.","gaps":[["Fortbildungen"]],"solution":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele **Fortbildungen** an.","en":"L'entreprise Müller & Müller offre de nombreuses formations continues à ses collaborateurs.","why":"*die Fortbildung, die Fortbildungen* ; *viele* exige le pluriel."}]},{"no":"2","instruction":"Schreiben Sie die Sätze neu.","instruction_en":"Réécrivez chaque phrase avec le début donné, en utilisant *zu* + infinitif. Tapez seulement la partie après la virgule.","example":[{"label":"a","lead":"Fortbildungen interessieren mich nicht!","text":"Ich habe kein Interesse, **Fortbildungen zu machen**."}],"items":[{"label":"b","lead":"Die Zusammenarbeit mit meinen Kollegen macht mir Freude.","text":"Es macht mir Freude, ___.","gaps":[["mit meinen Kollegen zusammenzuarbeiten"]],"solution":"Es macht mir Freude, **mit meinen Kollegen zusammenzuarbeiten**.","en":"J'aime travailler avec mes collègues.","why":"*die Zusammenarbeit* → le verbe *zusammenarbeiten*, séparable : *zusammen**zu**arbeiten*.","source":"g4069"},{"label":"c","lead":"Ich könnte mir eine Arbeit als Pflegefachmann gut vorstellen.","text":"Ich könnte mir gut vorstellen, ___.","gaps":[["als Pflegefachmann zu arbeiten"]],"solution":"Ich könnte mir gut vorstellen, **als Pflegefachmann zu arbeiten**.","en":"Je pourrais bien m'imaginer travailler comme infirmier.","why":"*eine Arbeit als …* → *als … zu arbeiten*.","source":"g6865"},{"label":"d","lead":"Der Berufsberater verspricht Hilfe bei der Berufswahl.","text":"Der Berufsberater verspricht, ___.","gaps":[["bei der Berufswahl zu helfen","mir bei der Berufswahl zu helfen","uns bei der Berufswahl zu helfen","bei der Berufswahl zu unterstützen"]],"solution":"Der Berufsberater verspricht, **bei der Berufswahl zu helfen**.","en":"Le conseiller en orientation promet d'aider à choisir un métier.","why":"*die Hilfe* → le verbe *helfen* : *zu helfen* à la fin.","source":"g6865"}]},{"no":"3","instruction":"Ergänzen Sie: *während – innerhalb – ausserhalb* und *der – ein – …* in der richtigen Form.","instruction_en":"Complétez avec *während*, *innerhalb* ou *ausserhalb* plus l'article à la bonne forme (génitif). Le livre donne la première lettre de l'article.","example":[{"label":"a","text":"Sehr geehrter Herr Safak, vielen Dank für Ihre Bewerbung. Wir melden uns **innerhalb der** nächsten Tage bei Ihnen."}],"items":[{"label":"b1","lead":"Sehr geehrter Herr Safak, wir laden Sie zu einem Vorstellungsgespräch am 2.8. um 10 Uhr ein.","text":"___ Gesprächs können Sie natürlich gern Fragen stellen.","gaps":[["Während des"]],"solution":"**Während des** Gesprächs können Sie natürlich gern Fragen stellen.","en":"Pendant l'entretien, vous pouvez bien sûr poser des questions.","why":"*während* + génitif neutre : *des Gesprächs*.","source":"g299310"},{"label":"b2","text":"Bitte geben Sie ___ Woche Bescheid, ob Sie kommen.","gaps":[["innerhalb einer"]],"solution":"Bitte geben Sie **innerhalb einer** Woche Bescheid, ob Sie kommen.","en":"Veuillez nous faire savoir dans un délai d'une semaine si vous venez.","why":"*innerhalb* + génitif féminin : *einer Woche*.","source":"prep"},{"label":"b3","text":"Sie erreichen mich per Telefon oder ___ Bürozeiten per E-Mail.","gaps":[["ausserhalb der"]],"solution":"Sie erreichen mich per Telefon oder **ausserhalb der** Bürozeiten per E-Mail.","en":"Vous pouvez me joindre par téléphone ou, en dehors des heures de bureau, par e-mail.","why":"*ausserhalb* + génitif pluriel : *der Bürozeiten*.","source":"prep"}]},{"no":"4","instruction":"Verbinden Sie.","instruction_en":"Associez chaque question à la réponse (1–5). Tapez le numéro.","phrases":["1 Nein, das kann ich mir nicht vorstellen.","2 Nein, das finde ich nicht.","3 Ja, ich muss eine Kollegin vertreten.","4 Ich beende gerade meine Lehre als Maler.","5 Danke, recht gut. Wir haben viel Arbeit."],"example":[{"label":"a","text":"Wie läuft's denn so in der Firma? → **5** Danke, recht gut. Wir haben viel Arbeit."}],"items":[{"label":"b","text":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → ___","gaps":[["1"]],"solution":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → **1**","en":"Tu n'as jamais pensé à changer de poste ? → 1 Non, je ne peux pas m'imaginer ça.","why":"Une question sur une idée : *Nein, das kann ich mir nicht vorstellen.*"},{"label":"c","text":"Was machst du jetzt eigentlich genau? → ___","gaps":[["4"]],"solution":"Was machst du jetzt eigentlich genau? → **4**","en":"Qu'est-ce que tu fais exactement maintenant ? → 4 Je termine justement mon apprentissage de peintre.","why":"Une question avec un mot interrogatif sur votre métier appelle un fait comme réponse."},{"label":"d","text":"Ist es nicht stressig, nachts zu arbeiten? → ___","gaps":[["2"]],"solution":"Ist es nicht stressig, nachts zu arbeiten? → **2**","en":"Ce n'est pas stressant de travailler la nuit ? → 2 Non, je ne trouve pas.","why":"*Ist es nicht stressig …?* demande un avis : *Nein, das finde ich nicht.*"},{"label":"e","text":"Hast du immer noch so viel Arbeit? → ___","gaps":[["3"]],"solution":"Hast du immer noch so viel Arbeit? → **3**","en":"Tu as toujours autant de travail ? → 3 Oui, je dois remplacer une collègue.","why":"Question fermée (réponse oui ou non) ; la raison de tout ce travail : *eine Kollegin vertreten*."}]}]},{"page":"AB 149","heading":"Fokus Beruf: Etwas verhandeln","heading_en":"Focus métier : négocier","exercises":[{"no":"1","instruction":"Vier gute Tipps","instruction_en":"Quatre bons conseils","part":"a","part_instruction":"Wofür bekommt man hier Tipps? Überfliegen Sie den Text und kreuzen Sie an.","part_instruction_en":"À quoi servent ces conseils ? Parcourez le texte et tapez la bonne réponse. (Les exercices 2 et 3 de cette page sont des compréhensions orales et ne sont pas repris.)","reading":[{"label":"So kommen Sie weiter!","text":"Ist das Bewerbungsgespräch gut gelaufen? Herzlichen Glückwunsch! Jetzt haben Sie es fast geschafft. Aber wenn es im Bewerbungsgespräch zum Thema Geld kommt, machen viele Bewerber Fehler: Sie fordern zu viel Lohn – oder zu wenig. Unsere Tipps helfen Ihnen bei diesem schwierigen Thema.\n1  Sprechen Sie das Thema Geld nicht selbst an. Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.\n2  Nennen Sie Ihre Gehaltsvorstellung. Wenn Sie vorher in anderen Unternehmen gearbeitet haben, ist Ihr letztes Gehalt die Grundlage.\n3  Natürlich können Sie an einem neuen Arbeitsplatz mehr Lohn verlangen, aber bleiben Sie realistisch und begründen Sie Ihre Gehaltsvorstellung: Haben Sie mehr Verantwortung? Können Sie mit besonderen Kenntnissen, Fähigkeiten oder Erfahrungen punkten? War der alte Arbeitgeber besonders zufrieden mit Ihnen?\n4  Was ist, wenn die Personalchefin oder der Personalchef negativ auf Ihre Gehaltsvorstellung reagiert? Dann müssen Sie flexibel sein und andere Vorschläge machen. Erklären Sie zum Beispiel, dass Sie mit weniger Lohn einverstanden sind, wenn die Firma Ihnen eine Weiter- oder Fortbildung bezahlt. Oder wenn Sie nach sechs Monaten mehr Lohn bekommen."}],"items":[{"label":"1","lead":"○ Für Gespräche mit der Bank   ○ Für Gespräche mit dem Arbeitgeber","text":"___","gaps":[["Für Gespräche mit dem Arbeitgeber","mit dem Arbeitgeber","Arbeitgeber","dem Arbeitgeber"]],"solution":"**Für Gespräche mit dem Arbeitgeber**","en":"Pour les entretiens avec l'employeur","why":"Les conseils portent sur la manière de parler d'argent pendant l'entretien d'embauche, avec la cheffe ou le chef du personnel.","source":"hueber"}]},{"no":"1","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Qu'est-ce qui est juste ? Relisez. Tapez *richtig* (juste) ou *falsch* (faux) après chaque phrase ; dans le livre, vous cochez seulement les phrases justes.","items":[{"label":"1","text":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → ___","gaps":[["richtig","r","ja"]],"solution":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → **richtig**","en":"C'est à la cheffe ou au chef du personnel d'aborder la question du salaire. → juste","why":"Conseil 1 : *Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.*","source":"hueber"},{"label":"2","text":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → ___","gaps":[["falsch","f","nein"]],"solution":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → **falsch**","en":"Dans le nouvel emploi, vous recevez d'abord le même salaire que dans l'ancienne entreprise. → faux","why":"Conseils 2 et 3 : votre dernier salaire n'est qu'une base ; vous pouvez demander plus.","source":"hueber"},{"label":"3","text":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → ___","gaps":[["richtig","r","ja"]],"solution":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → **richtig**","en":"Si vous voulez un salaire plus élevé, vous devriez donner de bons arguments. → juste","why":"Conseil 3 : *begründen Sie Ihre Gehaltsvorstellung*.","source":"hueber"},{"label":"4","text":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → ___","gaps":[["falsch","f","nein"]],"solution":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → **falsch**","en":"Si la cheffe ou le chef du personnel n'est pas d'accord avec votre proposition, vous ne pouvez plus rien faire. → faux","why":"Conseil 4 : soyez flexible et faites d'autres propositions (formation payée, salaire plus élevé après six mois).","source":"hueber"}]}]}]},{"id":"05-um-zu-damit-statt-ohne-reklamation","no":5,"title":"Lektion 6","title_en":"Le but avec um … zu et damit, au lieu de / sans, verbes avec es, entretien de vente et réclamations · Test de la leçon 6","added":"2026-11-18","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 6","pages":[{"page":"AB 150","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"Ce n'est pas facile, mais ça en vaut la peine.","exercises":[{"no":"1","tag":"A2","instruction":"Ordnen Sie zu.","instruction_en":"Complétez l'e-mail d'Anna avec les expressions avec *es* de l'encadré. Chacune est utilisée une fois ; *geht es* est utilisé dans l'exemple. Quand une expression contient *…*, d'autres mots se placent entre ses parties : tapez les deux parties dans les deux trous.","phrases":["geht es (Beispiel)","Es war","Es gibt","ist es … gelaufen","es … dunkel ist","wird es … schwierig","schwer es mir fällt","Es ist Sommer","regnet es","hat es … gefallen","es ist … kalt","ist es … ein Uhr","lohnt es sich"],"example":[{"label":"a","text":"Hallo Tim / Wie **geht es** Dir? Bei mir ist alles bestens."}],"items":[{"label":"b","text":"___, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","gaps":[["Es ist Sommer"]],"solution":"**Es ist Sommer**, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","en":"C'est l'été, on voit des fleurs partout et je suis beaucoup dehors. J'adore cette saison !","why":"*es* + *sein* + une saison ou un moment de la journée : *Es ist Sommer / Nacht / vier Uhr*.","source":"platzhalter"},{"label":"c","text":"Seit ein paar Tagen ___ zwar, aber schlechtes Wetter stört mich ja nicht.","gaps":[["regnet es"]],"solution":"Seit ein paar Tagen **regnet es** zwar, aber schlechtes Wetter stört mich ja nicht.","en":"Il pleut certes depuis quelques jours, mais le mauvais temps ne me dérange pas.","why":"Les verbes de météo ont toujours *es* comme sujet. *Seit ein paar Tagen* est en position 1, donc *es* vient après le verbe : *regnet es*.","source":"platzhalter"},{"label":"d","text":"Hauptsache, ___ nicht ___.","gaps":[["es ist"],["kalt"]],"solution":"Hauptsache, **es ist** nicht **kalt**.","en":"L'essentiel, c'est qu'il ne fasse pas froid.","why":"La météo avec un adjectif : *es ist kalt / heiss*. *nicht* se place devant *kalt*.","source":"platzhalter"},{"label":"e","text":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! ___ wirklich aufregend, …","gaps":[["Es war"]],"solution":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! **Es war** wirklich aufregend, …","en":"Dis donc, j'ai eu un entretien d'embauche ce matin ! C'était vraiment excitant, …","why":"*es* général + *sein* + adjectif, ici au Präteritum : *Es war aufregend*.","source":"korrelat"},{"label":"f","text":"… aber eigentlich ___ ziemlich gut ___. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","gaps":[["ist es"],["gelaufen"]],"solution":"… aber eigentlich **ist es** ziemlich gut **gelaufen**. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","en":"… mais en fait, ça s'est plutôt bien passé. Les gens sont très gentils et le travail est varié.","why":"*Es ist gut gelaufen* = ça s'est bien passé (Perfekt avec *sein*). *eigentlich* est en position 1, donc *ist es*.","source":"platzhalter"},{"label":"g","text":"___ nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","gaps":[["Es gibt"]],"solution":"**Es gibt** nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","en":"Il y a malheureusement juste un problème : je dois commencer à travailler à 7 heures (!) du matin. Quelle horreur !","why":"*es gibt* + accusatif = il y a : *Es gibt ein Problem*.","source":"platzhalter"},{"label":"h","text":"Du weisst doch, wie ___, früh aufzustehen.","gaps":[["schwer es mir fällt"]],"solution":"Du weisst doch, wie **schwer es mir fällt**, früh aufzustehen.","en":"Tu sais bien à quel point j'ai du mal à me lever tôt.","why":"*Es fällt mir schwer, … zu …* = j'ai du mal à … Dans la subordonnée en *wie*, le verbe va à la fin : *wie schwer es mir fällt*.","source":"korrelat"},{"label":"i","text":"Vor allem im Winter, wenn ___ noch ___, …","gaps":[["es"],["dunkel ist"]],"solution":"Vor allem im Winter, wenn **es** noch **dunkel ist**, …","en":"Surtout en hiver, quand il fait encore nuit, …","why":"*Es ist dunkel* (moment de la journée, lumière). Dans la subordonnée en *wenn*, le verbe va à la fin : *wenn es noch dunkel ist*.","source":"platzhalter"},{"label":"j","text":"… dann ___ wirklich ___ für mich.","gaps":[["wird es"],["schwierig"]],"solution":"… dann **wird es** wirklich **schwierig** für mich.","en":"… là, ça devient vraiment difficile pour moi.","why":"*Es wird schwierig* = ça devient difficile. *dann* est en position 1, donc *wird es*.","source":"korrelat"},{"label":"k","text":"Mir ___ in der Firma zwar sehr gut ___, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","gaps":[["hat es"],["gefallen"]],"solution":"Mir **hat es** in der Firma zwar sehr gut **gefallen**, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","en":"L'entreprise m'a certes beaucoup plu, mais je ne sais pas si j'arriverai à me lever si tôt. Que me conseilles-tu ?","why":"*Es gefällt mir* = ça me plaît ; au Perfekt : *Es hat mir gefallen*. Ici, *Mir* est en position 1.","source":"korrelat"},{"label":"l","text":"P.S.: Oh je, jetzt ___ schon wieder ___ nachts.","gaps":[["ist es"],["ein Uhr"]],"solution":"P.S.: Oh je, jetzt **ist es** schon wieder **ein Uhr** nachts.","en":"P.-S. : Oh là là, il est déjà de nouveau une heure du matin.","why":"L'heure : *Es ist ein Uhr*. *jetzt* est en position 1, donc *ist es*.","source":"platzhalter"},{"label":"m","text":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht ___ und ich bin dann am Morgen plötzlich immer topfit?","gaps":[["lohnt es sich"]],"solution":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht **lohnt es sich** und ich bin dann am Morgen plötzlich immer topfit?","en":"Peut-être que je devrais simplement aller me coucher plus tôt ? Qui sait, peut-être que ça en vaut la peine et que je serai alors soudain toujours en pleine forme le matin ?","why":"*Es lohnt sich* = ça en vaut la peine. *vielleicht* est en position 1, donc *lohnt es sich*.","source":"platzhalter"}]},{"no":"2","tag":"A2","instruction":"Machen Sie eine Tabelle und ergänzen Sie die Ausdrücke mit *es* aus 1.","instruction_en":"Classez les expressions avec *es* de l'exercice 1 en quatre groupes. Tapez le groupe : *Allgemein* (général), *Tages-/Jahreszeiten* (moments de la journée et saisons), *Wetter* (météo) ou *Befinden* (comment va quelqu'un).","example":[{"label":"Befinden","text":"Wie geht es Dir? → **Befinden**"}],"items":[{"label":"1","text":"Es ist Sommer. → ___","gaps":[["Tages-/Jahreszeiten","Jahreszeiten","Tageszeiten","Jahreszeit","Tages- und Jahreszeiten"]],"solution":"Es ist Sommer. → **Tages-/Jahreszeiten**","en":"C'est l'été. → moments de la journée et saisons","why":"Une saison.","source":"hueber"},{"label":"2","text":"regnet es → ___","gaps":[["Wetter"]],"solution":"regnet es → **Wetter**","en":"il pleut → météo","why":"Verbe de météo.","source":"hueber"},{"label":"3","text":"es ist kalt → ___","gaps":[["Wetter"]],"solution":"es ist kalt → **Wetter**","en":"il fait froid → météo","why":"La température fait partie de la météo.","source":"hueber"},{"label":"4","text":"Es war (aufregend) → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es war (aufregend) → **Allgemein**","en":"C'était (excitant) → général","why":"*es* + *sein* + adjectif pour parler d'une situation.","source":"hueber"},{"label":"5","text":"es ist gelaufen → ___","gaps":[["Allgemein","allgemein"]],"solution":"es ist gelaufen → **Allgemein**","en":"ça s'est (bien) passé → général","why":"Comment quelque chose s'est passé : une expression générale.","source":"hueber"},{"label":"6","text":"Es gibt → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es gibt → **Allgemein**","en":"Il y a → général","why":"*es gibt* = il y a.","source":"hueber"},{"label":"7","text":"schwer es mir fällt → ___","gaps":[["Allgemein","allgemein"]],"solution":"schwer es mir fällt → **Allgemein**","en":"à quel point j'ai du mal → général","why":"*es fällt mir schwer* = j'ai du mal.","source":"hueber"},{"label":"8","text":"es dunkel ist → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"es dunkel ist → **Tages-/Jahreszeiten**","en":"il fait nuit → moments de la journée","why":"Sombre = moment de la journée.","source":"hueber","check":"Le corrigé officiel classe *es ist dunkel* avec les moments de la journée. On pourrait aussi y voir la météo ; demandez à votre enseignant si votre classe l'a classé autrement."},{"label":"9","text":"wird es schwierig → ___","gaps":[["Allgemein","allgemein"]],"solution":"wird es schwierig → **Allgemein**","en":"ça devient difficile → général","why":"*es* + *werden* + adjectif pour parler d'une situation.","source":"hueber"},{"label":"10","text":"hat es gefallen → ___","gaps":[["Allgemein","allgemein"]],"solution":"hat es gefallen → **Allgemein**","en":"ça m'a plu → général","why":"*es gefällt mir* = ça me plaît.","source":"hueber"},{"label":"11","text":"ist es ein Uhr → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"ist es ein Uhr → **Tages-/Jahreszeiten**","en":"il est une heure → moments de la journée","why":"L'heure.","source":"hueber"},{"label":"12","text":"lohnt es sich → ___","gaps":[["Allgemein","allgemein"]],"solution":"lohnt es sich → **Allgemein**","en":"ça en vaut la peine → général","why":"*es lohnt sich* = ça en vaut la peine.","source":"hueber"}]},{"no":"3","tag":"A2","instruction":"Wo fehlt *es*? Ergänzen Sie wie im Beispiel.","instruction_en":"Où manque-t-il *es* ? Lisez l'e-mail de Fatima. Réécrivez chaque phrase ci-dessous avec *es* à la bonne place. Une phrase est correcte telle quelle : tapez-la alors sans la modifier.","reading":[{"label":"E-Mail","text":"Liebe Saskia\nist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe. Ich hoffe, dass euch gut geht. Seit wir in Gossau leben, ist viel passiert. Jetzt läuft ganz gut, aber am Anfang gab viele Probleme. Für unsere Kinder war besonders schwer. Sie haben ihre Freunde sehr vermisst und hatten Probleme mit der Sprache. Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt. Sie gehen ja jetzt auch zur Schule und haben andere Kinder kennengelernt. Übrigens gehe ich jetzt auch wieder in eine Schule – in eine Sprachschule. Ich besuche einen B1-Kurs. Das macht mir grosse Freude. So, jetzt ist gleich 9 Uhr. Ich muss Schluss machen. Mein Kurs fängt in einer halben Stunde an.\nBis bald, Deine Fatima"}],"example":[{"label":"Beispiel","text":"**Es** ist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe."}],"items":[{"label":"1","lead":"Ich hoffe, dass euch gut geht.","text":"","accept":["Ich hoffe, dass es euch gut geht."],"solution":"**Ich hoffe, dass es euch gut geht.**","en":"J'espère que vous allez bien.","why":"*Wie geht es euch?* → *dass es euch gut geht* : *es* est le sujet de *gehen* dans ce sens et ne peut pas être supprimé.","source":"platzhalter"},{"label":"2","lead":"Seit wir in Gossau leben, ist viel passiert.","text":"","accept":["Seit wir in Gossau leben, ist viel passiert."],"solution":"**Seit wir in Gossau leben, ist viel passiert.**","en":"Il s'est passé beaucoup de choses depuis que nous vivons à Gossau.","why":"Pas de *es* : *viel* est le sujet, et la subordonnée en *seit* occupe la position 1.","source":"platzhalter"},{"label":"3","lead":"Jetzt läuft ganz gut, aber am Anfang gab viele Probleme.","text":"","accept":["Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme."],"solution":"**Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme.**","en":"Maintenant, ça se passe plutôt bien, mais au début, il y avait beaucoup de problèmes.","why":"Deux trous : *es läuft gut* (ça se passe bien) et *es gab* (il y avait, Präteritum de *es gibt*). Avec *jetzt* / *am Anfang* en position 1, *es* suit le verbe.","source":"platzhalter"},{"label":"4","lead":"Für unsere Kinder war besonders schwer.","text":"","accept":["Für unsere Kinder war es besonders schwer."],"solution":"**Für unsere Kinder war es besonders schwer.**","en":"Pour nos enfants, c'était particulièrement difficile.","why":"*es* + *sein* + adjectif : *es war schwer*.","source":"platzhalter"},{"label":"5","lead":"Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt.","text":"","accept":["Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt."],"solution":"**Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt.**","en":"Mais maintenant, ça va déjà beaucoup mieux et ils se sont habitués à la vie ici.","why":"*es ist besser* : la situation n'a pas d'autre sujet, *es* est donc nécessaire.","source":"platzhalter"},{"label":"6","lead":"So, jetzt ist gleich 9 Uhr.","text":"","accept":["So, jetzt ist es gleich 9 Uhr."],"solution":"**So, jetzt ist es gleich 9 Uhr.**","en":"Bon, il est bientôt 9 heures.","why":"L'heure : *es ist 9 Uhr*.","source":"platzhalter"}]}]},{"page":"AB 151","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"Ce n'est pas facile, mais ça en vaut la peine.","exercises":[{"no":"4","tag":"A3","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Qu'est-ce qui est juste ? Lisez le texte sur une rencontre au village et tapez le mot qui convient dans chaque trou. Les deux choix sont indiqués au-dessus de chaque phrase.","reading":[{"label":"Stammtisch der Kulturen","text":"In unserem Dorf gibt es seit einiger Zeit am ersten Freitag im Monat einen Stammtisch der Kulturen. Dahin kommen alle, die Interesse an einem (a) Treffen mit Menschen aus aller Welt haben. Der Stammtisch ist ein grosser Erfolg geworden. Das war nicht immer so. Am Anfang war es eigentlich ein (b) und es kamen nur sehr wenige Teilnehmer. Es waren (c) fünf bis zehn da. Es war einfach so, dass die Leute aus der Region zuerst dachten, dass das Treffen nur für Migranten ist. Inzwischen kommen aber auch immer mehr Schweizer, (d) sind es oft sogar über 30 Leute pro Treffen. Alle helfen gratis mit und so funktioniert der Stammtisch ohne (e) Unterstützung."}],"example":[{"label":"a","text":"Dahin kommen alle, die Interesse an einem **interkulturellen** Treffen mit Menschen aus aller Welt haben."}],"items":[{"label":"b","lead":"Heimweh / Experiment","text":"Am Anfang war es eigentlich ein ___ und es kamen nur sehr wenige Teilnehmer.","gaps":[["Experiment"]],"solution":"Am Anfang war es eigentlich ein **Experiment** und es kamen nur sehr wenige Teilnehmer.","en":"Au début, c'était en fait une expérience, et seuls très peu de participants sont venus.","why":"*Heimweh* (le mal du pays) n'a pas de sens ici ; une idée nouvelle qui peut marcher ou non est un *Experiment* (une expérience).","source":"hueber"},{"label":"c","lead":"mindestens / höchstens","text":"Es waren ___ fünf bis zehn da.","gaps":[["höchstens"]],"solution":"Es waren **höchstens** fünf bis zehn da.","en":"Il y en avait tout au plus cinq à dix.","why":"*nur sehr wenige* → *höchstens* (tout au plus), pas *mindestens* (au moins).","source":"hueber"},{"label":"d","lead":"mindestens / mittlerweile","text":"Inzwischen kommen aber auch immer mehr Schweizer, ___ sind es oft sogar über 30 Leute pro Treffen.","gaps":[["mittlerweile"]],"solution":"Inzwischen kommen aber auch immer mehr Schweizer, **mittlerweile** sind es oft sogar über 30 Leute pro Treffen.","en":"Entre-temps, de plus en plus de Suisses viennent aussi ; désormais, il y a même souvent plus de 30 personnes par rencontre.","why":"*mittlerweile* = désormais, entre-temps (comme *inzwischen*).","source":"hueber"},{"label":"e","lead":"finanzielle / spezielle","text":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne ___ Unterstützung.","gaps":[["finanzielle"]],"solution":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne **finanzielle** Unterstützung.","en":"Tout le monde donne un coup de main gratuitement, et ainsi la rencontre fonctionne sans soutien financier.","why":"*gratis* (gratuitement) → on n'a pas besoin d'argent : *finanzielle Unterstützung*.","source":"hueber"}]},{"no":"5","tag":"A3","instruction":"Ergänzen Sie.","instruction_en":"Complétez les phrases. Le livre donne quelques lettres de chaque mot (indiquées au-dessus de la phrase) ; tapez le mot en entier.","example":[{"label":"c","text":"Ich mag den Frühling und den Sommer. Aber der Winter ist für mich die schönste **Jahreszeit**."}],"items":[{"label":"a","lead":"H _ _ _ _ h","text":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe ___.","gaps":[["Heimweh"]],"solution":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe **Heimweh**.","en":"Je suis triste parce que je ne suis pas chez moi. J'ai le mal du pays.","why":"*das Heimweh* = le mal du pays ; *Heimweh haben*.","source":"hueber"},{"label":"b","lead":"G _ _ _ r _ _","text":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen ___.","gaps":[["Gewürze"]],"solution":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen **Gewürze**.","en":"Le plus important quand on cuisine des plats indiens, ce sont les bonnes épices.","why":"*das Gewürz, die Gewürze* = l'épice, les épices ; au pluriel à cause de *sind*.","source":"hueber"},{"label":"d","lead":"G _ _ _ _ ä _ _ _ _ _ _ _ e","text":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche ___.","gaps":[["Geschäftsleute"]],"solution":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche **Geschäftsleute**.","en":"Mes grands-parents avaient plusieurs magasins. C'étaient des commerçants prospères.","why":"*die Geschäftsleute* = pluriel de *der Geschäftsmann / die Geschäftsfrau*.","source":"hueber"},{"label":"e","lead":"R _ _ _ _ c _ _ _","text":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine ___.","gaps":[["Rücksicht"]],"solution":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine **Rücksicht**.","en":"Notre voisin écoute de la musique forte à toute heure de la journée. Cela nous dérange tous, mais il n'a aucun égard pour les autres.","why":"*Rücksicht nehmen (auf)* = avoir des égards (pour).","source":"hueber"},{"label":"f","lead":"f _ _ _ _ z _ _ _ _ _ _  R _ _ _ _ _","text":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein ___ ___.","gaps":[["finanzielles"],["Risiko"]],"solution":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein **finanzielles** **Risiko**.","en":"Quand on se met à son compte avec un commerce, c'est souvent un risque financier.","why":"*das Risiko* est neutre, donc *ein finanzielles Risiko*.","source":"hueber"},{"label":"g","lead":"l _ _ _","text":"Mein Onkel hat viele gute Ideen. Er ___ fast jedes Problem.","gaps":[["löst"]],"solution":"Mein Onkel hat viele gute Ideen. Er **löst** fast jedes Problem.","en":"Mon oncle a beaucoup de bonnes idées. Il résout presque tous les problèmes.","why":"*ein Problem lösen* = résoudre un problème ; *er löst*.","source":"hueber"}]},{"no":"6","tag":"A4","instruction":"Buchstaben und Laute: *b – p, g – k, d – t*","instruction_en":"Lettres et sons : *b – p, g – k, d – t*. (Les parties a et b sont des compréhensions orales et ne sont pas reprises.)","part":"c","part_instruction":"Ergänzen Sie die Regel.","part_instruction_en":"Complétez la règle : comment prononce-t-on *b, d, g* à la fin d'un mot ? Regardez *halb, Geld, Tag*.","items":[{"label":"c","text":"Am Wortende spricht man *b, d, g* wie ___.","gaps":[["p, t, k","p t k","p, t und k","p,t,k"]],"solution":"Am Wortende spricht man *b, d, g* wie **p, t, k**.","en":"En fin de mot, on prononce *b, d, g* comme *p, t, k*.","why":"*halb* se prononce comme « halp », *Geld* comme « Gelt », *Tag* comme « Tak ». La même chose se produit devant une autre consonne : *Erfolg*, *Auftrag*, *ab und zu*.","source":"hueber"}]}]},{"page":"AB 152","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Je veux être au magasin pour pouvoir y attendre.","exercises":[{"no":"7","tag":"B1","instruction":"Margaretas Ziele. Ergänzen Sie.","instruction_en":"Les objectifs de Margareta. Chaque ligne montre un souhait (à gauche) et la même idée exprimée comme but avec *um … zu* (à droite). Complétez les trous du côté où il manque quelque chose.","example":[{"label":"a","lead":"Wozu ist Margareta in die Schweiz gekommen?","text":"Sie möchte ihr Deutsch verbessern. → Margareta ist in die Schweiz gekommen, **um** ihr Deutsch **zu verbessern**."}],"items":[{"label":"b","text":"Sie ___ eine Ausbildung ___. → um eine Ausbildung zu machen.","gaps":[["möchte"],["machen"]],"solution":"Sie **möchte** eine Ausbildung **machen**. → um eine Ausbildung zu machen.","en":"Elle aimerait faire une formation. → pour faire une formation.","why":"Le souhait : *möchte* + infinitif à la fin. *um … zu* supprime le verbe de modalité.","source":"g6865"},{"label":"c","text":"Sie möchte selbstständiger werden. → ___ selbstständiger ___.","gaps":[["um"],["zu werden"]],"solution":"Sie möchte selbstständiger werden. → **um** selbstständiger **zu werden**.","en":"Elle aimerait devenir plus autonome. → pour devenir plus autonome.","why":"*um* ouvre le groupe, *zu* + infinitif le ferme. *möchte* disparaît.","source":"g6865"},{"label":"d","text":"Sie ___ Geld ___. → um Geld zu verdienen.","gaps":[["möchte"],["verdienen"]],"solution":"Sie **möchte** Geld **verdienen**. → um Geld zu verdienen.","en":"Elle aimerait gagner de l'argent. → pour gagner de l'argent.","why":"Retour au souhait : *Sie möchte Geld verdienen.*","source":"g6865"},{"label":"e","text":"Sie möchte in der Nähe ihres Freundes sein. → ___ in der Nähe ihres Freundes ___.","gaps":[["um"],["zu sein"]],"solution":"Sie möchte in der Nähe ihres Freundes sein. → **um** in der Nähe ihres Freundes **zu sein**.","en":"Elle aimerait être près de son ami. → pour être près de son ami.","why":"*um … zu sein* ; *ihres Freundes* est au génitif après *in der Nähe*.","source":"g6865"}]},{"no":"8","tag":"B1","instruction":"Wozu machen die Leute das? Ordnen Sie zu und ergänzen Sie die Sätze mit *um … zu*.","instruction_en":"Pourquoi ces personnes font-elles cela ? Choisissez dans l'encadré le but qui convient à chaque phrase et ajoutez-le sous la forme *um … zu* + infinitif. *gesund bleiben* est utilisé dans l'exemple.","phrases":["frische Zutaten und Gewürze kaufen","als Erster im Büro sein","gesund bleiben (Beispiel)","einen wichtigen Kunden treffen","bessere Chancen auf dem Arbeitsmarkt haben"],"example":[{"label":"a","text":"Miguel geht dreimal pro Woche ins Fitnessstudio, **um gesund zu bleiben**."}],"items":[{"label":"b","text":"Peter steht von Montag bis Freitag sehr früh auf, ___.","gaps":[["um als Erster im Büro zu sein"]],"solution":"Peter steht von Montag bis Freitag sehr früh auf, **um als Erster im Büro zu sein**.","en":"Du lundi au vendredi, Peter se lève très tôt pour être le premier au bureau.","why":"Même personne (Peter), donc *um … zu* ; *sein* va à la fin avec *zu*.","source":"g6865"},{"label":"c","text":"Am Wochenende gehe ich immer auf den Markt, ___.","gaps":[["um frische Zutaten und Gewürze zu kaufen"]],"solution":"Am Wochenende gehe ich immer auf den Markt, **um frische Zutaten und Gewürze zu kaufen**.","en":"Le week-end, je vais toujours au marché pour acheter des ingrédients frais et des épices.","why":"Tout ce qui appartient à *kaufen* se place devant *zu kaufen*.","source":"g6865"},{"label":"d","text":"Herr Aryan fährt morgen nach Genf, ___.","gaps":[["um einen wichtigen Kunden zu treffen"]],"solution":"Herr Aryan fährt morgen nach Genf, **um einen wichtigen Kunden zu treffen**.","en":"M. Aryan va demain à Genève pour rencontrer un client important.","why":"*um … zu treffen* ; le complément *einen wichtigen Kunden* se place au milieu.","source":"g6865"},{"label":"e","text":"Sabina macht eine berufliche Weiterbildung, ___.","gaps":[["um bessere Chancen auf dem Arbeitsmarkt zu haben"]],"solution":"Sabina macht eine berufliche Weiterbildung, **um bessere Chancen auf dem Arbeitsmarkt zu haben**.","en":"Sabina suit une formation continue professionnelle pour avoir de meilleures chances sur le marché du travail.","why":"Même personne (Sabina) : *um … zu haben*.","source":"g6865"}]},{"no":"9","tag":"B1","instruction":"Wozu ist Yaroslav in die Schweiz gekommen?","instruction_en":"Pourquoi Yaroslav est-il venu en Suisse ?","part":"a","part_instruction":"Lesen Sie den Text und ergänzen Sie die Gründe.","part_instruction_en":"Lisez le texte et complétez les raisons avec des mots du texte.","reading":[{"label":"Abenteuer Ausland: Wozu sind Sie in die Schweiz gekommen? – Yaroslav Ivanenko, 38","text":"Meine Frau und ich wollten schon lange eine neue Perspektive im Leben finden. Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben. Bei mir war das anders. Ich bin IT-Spezialist und habe jahrelang als Programmierer in einer Softwarefirma gearbeitet. In unserem Land gibt es aber weniger Entwicklungsmöglichkeiten für meine Berufsbranche. Auch für unsere Kinder habe ich mir gewünscht, dass sie einmal eine gute Schule besuchen können. Aber die sind in unserer Heimat teuer. In einem internationalen Job-Portal im Internet habe ich dann gesehen, dass in der Schweiz Programmierer gesucht werden. Ich habe mich bei mehreren Firmen beworben und hatte grosses Glück. Gleich eins der ersten Vorstellungsgespräche, das ich über Skype geführt habe, war so positiv, dass ich von der Firma sofort ein Jobangebot erhalten habe. Die erste Zeit habe ich noch von der Ukraine aus gearbeitet, aber nach meiner Probezeit habe ich über die Firma eine offizielle Arbeitsbewilligung für die Schweiz bekommen. Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist. So haben wir uns entschlossen, mit den Kindern in die Schweiz zu ziehen. Es war nicht immer leicht für uns, aber jetzt sind wir einfach nur dankbar, dass wir diese Chance bekommen haben."}],"example":[{"label":"1","text":"Yaroslav und seine Frau können **eine neue Perspektive** finden."}],"items":[{"label":"2","text":"Seine Frau kann ___ leben.","gaps":[["in einer Stadt im Ausland"]],"solution":"Seine Frau kann **in einer Stadt im Ausland** leben.","en":"Sa femme peut vivre dans une ville à l'étranger.","why":"*Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben.*","source":"hueber"},{"label":"3","text":"Seine Kinder können ___ besuchen.","gaps":[["eine gute Schule"]],"solution":"Seine Kinder können **eine gute Schule** besuchen.","en":"Ses enfants peuvent fréquenter une bonne école.","why":"*… dass sie einmal eine gute Schule besuchen können.*","source":"hueber"},{"label":"4","text":"Das ganze Programmiererteam ist ___.","gaps":[["in Zug"]],"solution":"Das ganze Programmiererteam ist **in Zug**.","en":"Toute l'équipe de programmeurs est à Zoug.","why":"*Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist.*","source":"hueber"}]}]},{"page":"AB 153","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Je veux être au magasin pour pouvoir y attendre.","exercises":[{"no":"9","part":"b","part_instruction":"Schreiben Sie die Sätze neu mit *damit*.","part_instruction_en":"Réécrivez les raisons de a sous forme de subordonnées en *damit* : *Yaroslav ist in die Schweiz gekommen, damit …* Le verbe va à la fin.","example":[{"label":"1","text":"Yaroslav ist in die Schweiz gekommen, **damit er und seine Frau eine neue Perspektive finden können**."}],"items":[{"label":"2","lead":"Seine Frau kann in einer Stadt im Ausland leben.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.**","en":"Yaroslav est venu en Suisse pour que sa femme puisse vivre dans une ville à l'étranger.","why":"Personne différente (sa femme), donc seulement *damit* ; *kann* va tout à la fin.","source":"damit"},{"label":"3","lead":"Seine Kinder können eine gute Schule besuchen.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.**","en":"Yaroslav est venu en Suisse pour que ses enfants puissent fréquenter une bonne école.","why":"Personne différente (ses enfants) : *damit … besuchen können*.","source":"damit"},{"label":"4","lead":"Das ganze Programmiererteam ist in Zug.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.**","en":"Yaroslav est venu en Suisse pour que toute l'équipe de programmeurs soit à Zoug.","why":"Sujet différent (l'équipe) : *damit … ist*.","source":"damit"}]},{"no":"10","tag":"B1","instruction":"Warum steht Yaroslav früh auf? Lesen Sie und markieren Sie wie im Beispiel. Ergänzen Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"Pourquoi Yaroslav se lève-t-il tôt ? Regardez qui fait la deuxième action. Même personne : écrivez *damit* et *um … zu*. Personne différente : seul *damit* fonctionne.","example":[{"label":"A","lead":"Yaroslav steht früh auf. Er will vor der Arbeit joggen.","text":"Yaroslav steht früh auf, **damit er vor der Arbeit joggen kann**. / Yaroslav steht früh auf, **um vor der Arbeit zu joggen**."},{"label":"B","lead":"Yaroslav steht früh auf. Seine Kinder sollen pünktlich aus dem Haus gehen.","text":"Yaroslav steht früh auf, **damit seine Kinder pünktlich aus dem Haus gehen**."}],"items":[{"label":"A2","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, damit ___.","gaps":[["er in Ruhe seinen Kaffee trinken kann","er seinen Kaffee in Ruhe trinken kann"]],"solution":"Yaroslav steht früh auf, damit **er in Ruhe seinen Kaffee trinken kann**.","en":"Yaroslav se lève tôt pour pouvoir boire son café tranquillement.","why":"Même personne (*er*). *will* devient *kann* dans la subordonnée en *damit* ; le verbe va à la fin.","source":"damit"},{"label":"A3","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, ___.","gaps":[["um in Ruhe seinen Kaffee zu trinken","um seinen Kaffee in Ruhe zu trinken"]],"solution":"Yaroslav steht früh auf, **um in Ruhe seinen Kaffee zu trinken**.","en":"Yaroslav se lève tôt pour boire son café tranquillement.","why":"Même personne, donc *um … zu* fonctionne aussi : pas de sujet, pas de *will*.","source":"g6865"},{"label":"B2","lead":"Yaroslav steht früh auf. Das Badezimmer soll dann für die Familie frei sein.","text":"Yaroslav steht früh auf, ___.","gaps":[["damit das Badezimmer dann für die Familie frei ist","damit das Badezimmer für die Familie frei ist"]],"solution":"Yaroslav steht früh auf, **damit das Badezimmer dann für die Familie frei ist**.","en":"Yaroslav se lève tôt pour que la salle de bains soit ensuite libre pour la famille.","why":"Sujet différent (*das Badezimmer*) : seulement *damit*. *soll* est supprimé : *damit … frei ist*.","source":"damit"}]},{"no":"11","tag":"B1","instruction":"Eine typische Woche von Marcello und seiner Familie. Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"Une semaine type de Marcello (A), de sa femme (B) et de leurs enfants (C). Reliez chaque paire en une seule phrase. Employez *um … zu* quand la personne est la même, sinon *damit*. Quand les deux fonctionnent, les deux sont acceptés.","example":[{"label":"A1","lead":"Ich gehe am Morgen früh zur Arbeit. Ich möchte am Abend nicht so spät nach Hause kommen.","text":"Ich gehe am Morgen früh zur Arbeit, **damit ich am Abend nicht so spät nach Hause komme**. / Ich gehe am Morgen früh zur Arbeit, **um am Abend nicht so spät nach Hause zu kommen**."}],"items":[{"label":"A2","lead":"Marcello: Ich fahre einmal pro Woche zum Supermarkt. Meine Frau muss die schweren Einkäufe nicht machen.","text":"","accept":["Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss."],"solution":"**Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss.**","en":"Je vais au supermarché une fois par semaine pour que ma femme n'ait pas à faire les courses lourdes.","why":"Personne différente (*meine Frau*) : seulement *damit*. Ici, *muss* reste, car il porte le sens (*nicht machen muss* = n'a pas à le faire).","source":"damit"},{"label":"B1","lead":"Frau: Ich koche am Mittag zu Hause. Die Kinder sollen etwas Warmes zu essen haben, wenn sie von der Schule kommen.","text":"","accept":["Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen."],"solution":"**Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen.**","en":"À midi, je cuisine à la maison pour que les enfants aient quelque chose de chaud à manger quand ils rentrent de l'école.","why":"Personne différente (*die Kinder*) : *damit* ; *sollen* est supprimé.","source":"damit"},{"label":"B2","lead":"Frau: Ich verbessere mein Deutsch in einem Sprachkurs. Ich will im Alltag gut zurechtkommen.","text":"","accept":["Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.","Ich verbessere mein Deutsch in einem Sprachkurs, damit ich im Alltag gut zurechtkomme."],"solution":"**Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.**","en":"J'améliore mon allemand dans un cours de langue pour bien me débrouiller au quotidien.","why":"Même personne : les deux fonctionnent. *zurechtkommen* est un verbe à particule séparable : *zurecht**zu**kommen*. *will* est supprimé.","source":"g6865"},{"label":"C1","lead":"Kinder: Wir lernen nach der Schule viel am Nachmittag. Wir wollen gute Noten haben und einen guten Abschluss machen.","text":"","accept":["Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.","Wir lernen nach der Schule viel am Nachmittag, damit wir gute Noten haben und einen guten Abschluss machen."],"solution":"**Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.**","en":"Après l'école, nous étudions beaucoup l'après-midi pour avoir de bonnes notes et obtenir un bon diplôme de fin d'études.","why":"Même personne (*wir*) : les deux fonctionnent. Avec deux verbes, chacun reçoit son propre *zu*.","source":"g6865"},{"label":"C2","lead":"Kinder: Wir helfen im Haushalt. Mama soll nicht alles allein machen.","text":"","accept":["Wir helfen im Haushalt, damit Mama nicht alles allein macht.","Wir helfen im Haushalt, damit Mama nicht alles allein machen muss."],"solution":"**Wir helfen im Haushalt, damit Mama nicht alles allein macht.**","en":"Nous aidons au ménage pour que maman ne fasse pas tout toute seule.","why":"Personne différente (*Mama*) : seulement *damit* ; *soll* est supprimé.","source":"damit"}]}]},{"page":"AB 154","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Je veux être au magasin pour pouvoir y attendre.","exercises":[{"no":"12","tag":"B1","marker":"◇","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Qu'est-ce qui est juste ? Tapez *um* ou *damit*. Regardez la fin de la phrase : *zu* + infinitif demande *um* ; un verbe conjugué à la fin demande *damit*.","example":[{"label":"a","text":"Frau Alt betreut ihre Enkel zu Hause, **damit** ihre Tochter berufstätig sein kann."}],"items":[{"label":"b","text":"Jaime lernt und arbeitet viel, ___ sich bald selbstständig zu machen.","gaps":[["um"]],"solution":"Jaime lernt und arbeitet viel, **um** sich bald selbstständig zu machen.","en":"Jaime étudie et travaille beaucoup pour se mettre bientôt à son compte.","why":"*zu machen* à la fin → *um*.","source":"g6865"},{"label":"c","text":"Said lernt neben Deutsch auch Englisch, ___ bessere Chancen auf dem Arbeitsmarkt zu haben.","gaps":[["um"]],"solution":"Said lernt neben Deutsch auch Englisch, **um** bessere Chancen auf dem Arbeitsmarkt zu haben.","en":"En plus de l'allemand, Said apprend aussi l'anglais pour avoir de meilleures chances sur le marché du travail.","why":"*zu haben* à la fin → *um*.","source":"g6865"},{"label":"d","text":"Irina arbeitet jetzt Vollzeit, ___ ihr Mann eine teure Weiterbildung machen kann.","gaps":[["damit"]],"solution":"Irina arbeitet jetzt Vollzeit, **damit** ihr Mann eine teure Weiterbildung machen kann.","en":"Irina travaille maintenant à plein temps pour que son mari puisse suivre une formation continue coûteuse.","why":"Nouveau sujet *ihr Mann* et *kann* à la fin → *damit*.","source":"damit"},{"label":"e","text":"Herr Pfister bezahlt viel Geld, ___ seine Eltern von einer privaten Pflegehelferin gepflegt werden.","gaps":[["damit"]],"solution":"Herr Pfister bezahlt viel Geld, **damit** seine Eltern von einer privaten Pflegehelferin gepflegt werden.","en":"M. Pfister paie beaucoup d'argent pour que ses parents soient soignés par une aide-soignante privée.","why":"Nouveau sujet *seine Eltern*, passif *gepflegt werden* à la fin → *damit*.","source":"damit"}]},{"no":"13","tag":"B1","marker":"◆","instruction":"Wozu macht Marcello das?","instruction_en":"Pourquoi Marcello fait-il cela ?","part":"a","part_instruction":"Verbinden Sie.","part_instruction_en":"Associez chaque chose que fait Marcello (1–6) à la personne qui en profite (*Er, Seine Frau, Sein Team*) et au but (a–f). Tapez la personne, puis la lettre.","phrases":["Er","Seine Frau","Sein Team","a soll abends etwas Ruhe haben.","b kann das gemeinsame Projekt pünktlich abschliessen.","c will wochentags früher gehen.","d kann tagsüber die Einkäufe mit dem Auto erledigen.","e kann ungestört seinen Arbeitstag planen.","f will fit bleiben."],"example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen. → **Er**, **f**"}],"items":[{"label":"2","text":"Er ist als Erster im Büro. → ___, ___","gaps":[["Er"],["e"]],"solution":"Er ist als Erster im Büro. → **Er**, **e**","en":"Il est le premier au bureau. → Il, e (peut planifier sa journée de travail sans être dérangé).","why":"Un bureau vide signifie pas d'interruptions.","source":"hueber"},{"label":"3","text":"Er lässt das Auto zu Hause. → ___, ___","gaps":[["Seine Frau"],["d"]],"solution":"Er lässt das Auto zu Hause. → **Seine Frau**, **d**","en":"Il laisse la voiture à la maison. → Sa femme, d (peut faire les courses en voiture pendant la journée).","why":"S'il ne prend pas la voiture, sa femme peut l'utiliser.","source":"hueber"},{"label":"4","text":"Er macht manchmal Überstunden. → ___, ___","gaps":[["Sein Team"],["b"]],"solution":"Er macht manchmal Überstunden. → **Sein Team**, **b**","en":"Il fait parfois des heures supplémentaires. → Son équipe, b (peut terminer à temps le projet commun).","why":"Les heures supplémentaires aident le projet commun.","source":"hueber"},{"label":"5","text":"Er arbeitet auch mal am Samstag. → ___, ___","gaps":[["Er"],["c"]],"solution":"Er arbeitet auch mal am Samstag. → **Er**, **c**","en":"Il travaille aussi parfois le samedi. → Il, c (veut partir plus tôt en semaine).","why":"Travailler le samedi lui permet d'avoir des journées plus courtes en semaine.","source":"hueber"},{"label":"6","text":"Er bringt die Kinder ins Bett. → ___, ___","gaps":[["Seine Frau"],["a"]],"solution":"Er bringt die Kinder ins Bett. → **Seine Frau**, **a**","en":"Il met les enfants au lit. → Sa femme, a (doit avoir un peu de calme le soir).","why":"Elle a une soirée tranquille.","source":"hueber"}]},{"no":"13","part":"b","part_instruction":"Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","part_instruction_en":"Écrivez des phrases à partir de vos réponses en a. Même personne (*Er*) : *um … zu* ou *damit*. Autre personne : seulement *damit*. Supprimez *will* et *soll*.","example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen, **damit er fit bleibt**. / Marcello geht dreimal pro Woche joggen, **um fit zu bleiben**."}],"items":[{"label":"2","lead":"Er ist als Erster im Büro. / Er kann ungestört seinen Arbeitstag planen.","text":"","accept":["Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.","Er ist als Erster im Büro, damit er ungestört seinen Arbeitstag planen kann.","Marcello ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen."],"solution":"**Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.**","en":"Il est le premier au bureau pour planifier sa journée de travail sans être dérangé.","why":"Même personne : les deux fonctionnent.","source":"g6865"},{"label":"3","lead":"Er lässt das Auto zu Hause. / Seine Frau kann tagsüber die Einkäufe mit dem Auto erledigen.","text":"","accept":["Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann."],"solution":"**Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann.**","en":"Il laisse la voiture à la maison pour que sa femme puisse faire les courses en voiture pendant la journée.","why":"Autre personne : seulement *damit*.","source":"damit"},{"label":"4","lead":"Er macht manchmal Überstunden. / Sein Team kann das gemeinsame Projekt pünktlich abschliessen.","text":"","accept":["Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann."],"solution":"**Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann.**","en":"Il fait parfois des heures supplémentaires pour que son équipe puisse terminer à temps le projet commun.","why":"Autre sujet : seulement *damit*.","source":"damit"},{"label":"5","lead":"Er arbeitet auch mal am Samstag. / Er will wochentags früher gehen.","text":"","accept":["Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.","Er arbeitet auch mal am Samstag, damit er wochentags früher gehen kann."],"solution":"**Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.**","en":"Il travaille aussi parfois le samedi pour partir plus tôt en semaine.","why":"Même personne : les deux fonctionnent ; *will* est supprimé.","source":"g6865"},{"label":"6","lead":"Er bringt die Kinder ins Bett. / Seine Frau soll abends etwas Ruhe haben.","text":"","accept":["Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat."],"solution":"**Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat.**","en":"Il met les enfants au lit pour que sa femme ait un peu de calme le soir.","why":"Autre personne : *damit* ; *soll* est supprimé.","source":"damit"}]},{"no":"14","tag":"B3","instruction":"Beruf und Karriere – was ist wichtig, um Erfolg im Job zu haben? Markieren Sie noch fünf Wörter und ordnen Sie zu.","instruction_en":"Métier et carrière : qu'est-ce qui compte pour réussir au travail ? Trouvez cinq autres mots dans la grille de lettres et complétez les phrases. *Kompetenzen* est l'exemple. Tapez les adjectifs en minuscules.","reading":[{"label":"Buchstabengitter","text":"DLKJLDGDKJLKDLGKOMPETENZENLLSKOMMUNIKATIVEDJG\nLSKDENGAGEMENTJGKDÖLGÖGLLKGLKONFLIKTFÄHIGLÖFJA\nFLAGJSTEAMFÄHIGJGSLGJSLMOTIVATIONSLGSLKGDJAFJFLA"}],"example":[{"label":"a","text":"Personalfachleute sagen: Man braucht nicht nur fachliche, sondern auch soziale **Kompetenzen**, wenn man im Beruf erfolgreich sein will."}],"items":[{"label":"b","text":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie ___.","gaps":[["teamfähig"]],"solution":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie **teamfähig**.","en":"Par exemple, il est important qu'une personne sache bien travailler en équipe et fasse aussi des compromis. Elle a alors l'esprit d'équipe.","why":"*teamfähig* = capable de travailler en équipe.","source":"hueber"},{"label":"c","text":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie ___.","gaps":[["konfliktfähig"]],"solution":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie **konfliktfähig**.","en":"Quand des collègues se disputent, mais trouvent finalement ensemble une bonne solution à leur problème, ils savent gérer les conflits.","why":"*konfliktfähig* = capable de gérer les conflits.","source":"hueber"},{"label":"d","text":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute ___ Kompetenzen.","gaps":[["kommunikative"]],"solution":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute **kommunikative** Kompetenzen.","en":"Celui qui est ouvert, qui sait bien discuter avec les gens, mais aussi bien écouter, a de bonnes compétences en communication.","why":"Adjectif devant un nom au pluriel après *gute* : *kommunikative Kompetenzen*.","source":"hueber"},{"label":"e","text":"Auf jeden Fall muss ein Mitarbeiter ___ und ___ zeigen, um im Beruf erfolgreich zu sein.","gaps":[["Motivation","Engagement"],["Engagement","Motivation"]],"solution":"Auf jeden Fall muss ein Mitarbeiter **Motivation** und **Engagement** zeigen, um im Beruf erfolgreich zu sein.","en":"Dans tous les cas, un collaborateur doit faire preuve de motivation et d'engagement pour réussir dans son métier.","why":"*die Motivation* et *das Engagement* (l'engagement) ; dans n'importe quel ordre.","source":"hueber"}]}]},{"page":"AB 155","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"Faire quelque chose au lieu de seulement rêver","exercises":[{"no":"15","tag":"C1","instruction":"Unzufrieden im Job","instruction_en":"Malheureux au travail","part":"a","part_instruction":"In welchem Satz steht *nicht/kein*? Markieren Sie.","part_instruction_en":"Comparez les deux phrases courtes avec la phrase longue. Quel mot pour « ne … pas / aucun » disparaît dans la version avec *statt … zu* ou *ohne … zu* ? Tapez-le.","example":[{"label":"1","text":"Ich bringe lieber meinen eigenen Laptop mit. Ich benütze **nicht** den alten Computer in der Firma. / Ich bringe lieber meinen eigenen Laptop mit, statt den alten Computer in der Firma zu benützen."}],"items":[{"label":"2","text":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → ___","gaps":[["keinen","kein"]],"solution":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → **keinen**","en":"Le chef est toujours de mauvaise humeur. Il n'a aucune raison pour cela. / Le chef est toujours de mauvaise humeur sans avoir de raison pour cela. → keinen","why":"*ohne* veut déjà dire « ne … pas » : *keinen Grund* devient *einen Grund* après *ohne*.","source":"komma"}]},{"no":"15","part":"b","part_instruction":"Welche Sätze sind richtig? Vergleichen Sie mit a und kreuzen Sie an.","part_instruction_en":"Quelle fin est juste ? Les deux choix sont indiqués au-dessus de chaque phrase. Tapez la bonne fin.","items":[{"label":"1","lead":"statt mich weiter über die Arbeit zu ärgern / statt mich nicht weiter über die Arbeit zu ärgern","text":"Ich wechsle den Job, ___.","gaps":[["statt mich weiter über die Arbeit zu ärgern"]],"solution":"Ich wechsle den Job, **statt mich weiter über die Arbeit zu ärgern**.","en":"Je change de travail au lieu de continuer à m'énerver à cause du travail.","why":"Pas de *nicht* après *statt* : *statt* dit déjà « pas cela ».","source":"komma"},{"label":"2","lead":"ohne den Chef nicht zu informieren / ohne den Chef zu informieren","text":"Ich suche eine neue Stelle, ___.","gaps":[["ohne den Chef zu informieren"]],"solution":"Ich suche eine neue Stelle, **ohne den Chef zu informieren**.","en":"Je cherche un nouveau poste sans informer le chef.","why":"Pas de *nicht* après *ohne* : *ohne den Chef nicht zu informieren* dirait le contraire.","source":"komma"}]},{"no":"16","tag":"C1","instruction":"Homeoffice. Ergänzen Sie die Sätze mit *statt … zu*.","instruction_en":"Le télétravail. Transformez la deuxième partie (ce que l'on ne fait pas) en *statt … zu* + infinitif. Supprimez *nicht / keine*.","example":[{"label":"a","lead":"Sie können bei der Arbeit eine bequeme Sporthose tragen und müssen keine unbequeme Berufskleidung anziehen.","text":"Sie können bei der Arbeit eine bequeme Sporthose tragen, **statt unbequeme Berufskleidung anzuziehen**."}],"items":[{"label":"b","lead":"Sie haben flexible Arbeitszeiten und arbeiten nicht von 9 bis 17 Uhr.","text":"Sie haben flexible Arbeitszeiten, ___.","gaps":[["statt von 9 bis 17 Uhr zu arbeiten"]],"solution":"Sie haben flexible Arbeitszeiten, **statt von 9 bis 17 Uhr zu arbeiten**.","en":"Vous avez des horaires de travail flexibles au lieu de travailler de 9 h à 17 h.","why":"*nicht* disparaît ; *zu arbeiten* va à la fin.","source":"komma"},{"label":"c","lead":"Sie haben keine Fahrtkosten und geben nicht viel Geld für Benzin aus.","text":"Sie haben keine Fahrtkosten, ___.","gaps":[["statt viel Geld für Benzin auszugeben"]],"solution":"Sie haben keine Fahrtkosten, **statt viel Geld für Benzin auszugeben**.","en":"Vous n'avez pas de frais de déplacement au lieu de dépenser beaucoup d'argent en essence.","why":"*ausgeben* est un verbe à particule séparable : *aus**zu**geben*.","source":"komma"},{"label":"d","lead":"Sie räumen die Wohnung auf und arbeiten nicht.","text":"Sie räumen die Wohnung auf, ___.","gaps":[["statt zu arbeiten"]],"solution":"Sie räumen die Wohnung auf, **statt zu arbeiten**.","en":"Vous rangez l'appartement au lieu de travailler.","why":"Rien d'autre n'appartient à *arbeiten* ; le groupe est donc simplement *statt zu arbeiten*.","source":"komma"},{"label":"e","lead":"Sie müssen viele Probleme allein lösen und besprechen sie nicht mit Kollegen.","text":"Sie müssen viele Probleme allein lösen, ___.","gaps":[["statt sie mit Kollegen zu besprechen"]],"solution":"Sie müssen viele Probleme allein lösen, **statt sie mit Kollegen zu besprechen**.","en":"Vous devez résoudre beaucoup de problèmes seul au lieu d'en discuter avec des collègues.","why":"*sie* = les problèmes ; ce pronom reste à l'intérieur du groupe.","source":"komma"}]},{"no":"17","tag":"C2","instruction":"Meine fleissige Arbeitskollegin Olga. Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"Ma collègue travailleuse Olga. Reliez les deux phrases. Une chose qu'elle fait *au lieu* d'une autre → *statt … zu*. Une chose qui n'a pas lieu *en même temps* → *ohne … zu*. Supprimez *nicht / kein*.","example":[{"label":"a","lead":"Sie steht jeden Tag um fünf Uhr auf. Sie beschwert sich nicht.","text":"Sie steht jeden Tag um fünf Uhr auf, **ohne sich zu beschweren**."}],"items":[{"label":"b","lead":"Sie kommt schon um 7 Uhr ins Büro. Sie fängt nicht erst um 9 Uhr an.","text":"","accept":["Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen."],"solution":"**Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen.**","en":"Elle arrive au bureau dès 7 heures au lieu de ne commencer qu'à 9 heures.","why":"7 heures remplace 9 heures → *statt*. *anfangen* : *an**zu**fangen*.","source":"komma"},{"label":"c","lead":"Sie fährt immer mit dem Velo zur Arbeit. Sie nimmt nicht das Auto.","text":"","accept":["Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen."],"solution":"**Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen.**","en":"Elle va toujours au travail à vélo au lieu de prendre la voiture.","why":"Le vélo remplace la voiture → *statt*. (*das Velo* = mot suisse pour le vélo.)","source":"komma"},{"label":"d","lead":"Sie geht in der Mittagszeit joggen. Sie isst nicht.","text":"","accept":["Sie geht in der Mittagszeit joggen, statt etwas zu essen.","Sie geht in der Mittagszeit joggen, statt zu essen.","Sie geht in der Mittagszeit joggen, ohne etwas zu essen.","Sie geht in der Mittagszeit joggen, ohne zu essen."],"solution":"**Sie geht in der Mittagszeit joggen, statt etwas zu essen.**","en":"À midi, elle va faire du jogging au lieu de manger quelque chose.","why":"Le jogging remplace le repas de midi → *statt*.","source":"komma","check":"Le corrigé officiel donne *statt etwas zu essen*. *ohne etwas zu essen* (elle fait du jogging et ne mange rien) est aussi de l'allemand correct et a presque le même sens ici."},{"label":"e","lead":"Sie arbeitet viele Stunden am Stück. Sie macht keine Pause.","text":"","accept":["Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.","Sie arbeitet viele Stunden am Stück, ohne Pause zu machen."],"solution":"**Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.**","en":"Elle travaille de nombreuses heures d'affilée sans faire de pause.","why":"La pause n'a pas lieu pendant qu'elle travaille → *ohne*. *keine Pause* devient *eine Pause*.","source":"komma"},{"label":"f","lead":"Sie sollte sich mehr um sich selbst kümmern. Sie arbeitet so viel.","text":"","accept":["Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten."],"solution":"**Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten.**","en":"Elle devrait davantage prendre soin d'elle-même au lieu de travailler autant.","why":"Prendre soin d'elle-même devrait remplacer le fait de tant travailler → *statt*.","source":"komma"}]}]},{"page":"AB 156","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"Faire quelque chose au lieu de seulement rêver","exercises":[{"no":"18","tag":"C2","marker":"◇","instruction":"Morgengewohnheiten. Was ist richtig? Kreuzen Sie an.","instruction_en":"Habitudes du matin. Tapez *ohne* ou *statt*. *statt* = au lieu de (une chose en remplace une autre) ; *ohne* = sans (quelque chose n'a pas lieu en même temps).","example":[{"label":"a","text":"Ich fahre zu jeder Jahreszeit mit dem Velo zur Arbeit, **statt** das Auto zu nehmen."}],"items":[{"label":"b","text":"Ich dusche am Morgen immer kalt, ___ warm zu baden.","gaps":[["statt"]],"solution":"Ich dusche am Morgen immer kalt, **statt** warm zu baden.","en":"Le matin, je prends toujours une douche froide au lieu de prendre un bain chaud.","why":"Une douche froide remplace un bain chaud.","source":"komma"},{"label":"c","text":"Ich trinke nie Kaffee, ___ Zeitung zu lesen.","gaps":[["ohne"]],"solution":"Ich trinke nie Kaffee, **ohne** Zeitung zu lesen.","en":"Je ne bois jamais de café sans lire le journal.","why":"*nie … ohne* = chaque fois que je bois un café, je lis le journal.","source":"komma"},{"label":"d","text":"Ich gehe nie aus dem Haus, ___ meinen Regenschirm mitzunehmen.","gaps":[["ohne"]],"solution":"Ich gehe nie aus dem Haus, **ohne** meinen Regenschirm mitzunehmen.","en":"Je ne sors jamais de la maison sans prendre mon parapluie.","why":"*nie … ohne* = je le prends toujours.","source":"komma"},{"label":"e","text":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, ___ sofort aufzustehen.","gaps":[["statt"]],"solution":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, **statt** sofort aufzustehen.","en":"Le matin, après le réveil, je reste toujours encore une demi-heure au lit au lieu de me lever tout de suite.","why":"Rester au lit remplace le fait de se lever.","source":"komma"}]},{"no":"19","tag":"C2","marker":"◆","instruction":"Was würden Sie in Ihrem Leben gern machen? Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"Qu'aimeriez-vous faire dans votre vie ? Combinez un souhait de la partie gauche de l'encadré avec un élément de la partie droite, en utilisant *ohne … zu* ou *statt … zu*. Les mots barrés sont utilisés dans l'exemple. La réponse modèle n'est qu'une possibilité.","box":["beruflich selbstständig sein","mehr Geld verdienen","kaputte Sachen reparieren","eine Wohnung kaufen","mit meiner Familie in der Heimat telefonieren","gut Deutsch sprechen","mit dem Velo fahren","mit meiner Familie zusammenwohnen","…","viele Sprachkurse machen","immer zu Fuss gehen","allein leben","viel Geld ausgeben","sie in den Abfall werfen","Heimweh haben","jeden Franken sparen müssen","ein finanzielles Risiko eingehen","…"],"box_used":[0,16],"example":[{"label":"Beispiel","text":"Ich wäre gern beruflich selbstständig, **ohne ein finanzielles Risiko einzugehen**. Ich würde gern …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gern mehr Geld verdienen, statt jeden Franken sparen zu müssen. Ich würde gern kaputte Sachen reparieren, statt sie in den Abfall zu werfen. Ich würde gern mit meiner Familie in der Heimat telefonieren, ohne Heimweh zu haben. Ich würde gern mit dem Velo fahren, statt immer zu Fuss zu gehen. Ich würde gern gut Deutsch sprechen, ohne viele Sprachkurse zu machen. Ich würde gern mit meiner Familie zusammenwohnen, statt allein zu leben.","en":"J'aimerais gagner plus d'argent au lieu de devoir économiser chaque franc. J'aimerais réparer les objets cassés au lieu de les jeter à la poubelle. J'aimerais téléphoner à ma famille au pays sans avoir le mal du pays. J'aimerais aller à vélo au lieu de toujours marcher. J'aimerais bien parler allemand sans suivre beaucoup de cours de langue. J'aimerais vivre avec ma famille au lieu de vivre seul.","why":"Le souhait avec *würde gern* / *wäre gern*, puis *statt … zu* (remplacement) ou *ohne … zu* (cela n'a pas lieu). Avec un verbe de modalité : *sparen **zu müssen***.","source":"hueber"}]},{"no":"20","tag":"C3","instruction":"Unglücklich im neuen Job – Ratschläge für eine Freundin","instruction_en":"Malheureuse dans un nouveau travail : des conseils pour une amie","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Complétez les conseils avec les expressions de l'encadré. Chacune est utilisée une fois ; *Wie wäre es, wenn* est utilisé dans l'exemple.","box":["An deiner Stelle","Du könntest zum Beispiel","Ich kann dir nur raten","Wie wäre es, wenn","Wie findest du die Idee","solltest du vielleicht"],"box_used":[3],"box_exact":true,"example":[{"label":"1","text":"**Wie wäre es, wenn** du mit deinen Kollegen zusammen Mittagspause machen würdest, statt allein zu essen?"}],"items":[{"label":"2","text":"Wenn du Kollegen besser kennenlernen möchtest, ___ öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","gaps":[["solltest du vielleicht"]],"solution":"Wenn du Kollegen besser kennenlernen möchtest, **solltest du vielleicht** öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","en":"Si tu veux mieux connaître tes collègues, tu devrais peut-être passer plus souvent dans la journée à la cuisine-cafétéria. Là, tu peux discuter tranquillement avec tout le monde sans les déranger dans leur travail.","why":"Après la subordonnée en *wenn*, le verbe vient en premier : *…, solltest du vielleicht …* ; *gehen* va à la fin.","source":"hueber"},{"label":"3","text":"___, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","gaps":[["Wie findest du die Idee"]],"solution":"**Wie findest du die Idee**, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","en":"Que penses-tu de l'idée d'apporter un jour un gâteau pour les collègues de ton service et de fêter ton premier mois dans la nouvelle entreprise ? Tout le monde est content d'avoir du gâteau.","why":"*Wie findest du die Idee, … zu …?* est une question avec *zu* + infinitif.","source":"g6865"},{"label":"4","text":"___ würde ich überallhin gehen, wo man Kollegen treffen kann. ___ am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","gaps":[["An deiner Stelle"],["Du könntest zum Beispiel"]],"solution":"**An deiner Stelle** würde ich überallhin gehen, wo man Kollegen treffen kann. **Du könntest zum Beispiel** am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","en":"À ta place, j'irais partout où l'on peut rencontrer des collègues. Tu pourrais par exemple participer au programme sportif de l'entreprise. Là, tu feras aussi la connaissance de gens d'autres services.","why":"*An deiner Stelle würde ich …* (à ta place, je …) ; *Du könntest zum Beispiel …* + infinitif à la fin.","source":"hueber"},{"label":"5","text":"___, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","gaps":[["Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten**, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","en":"Je ne peux que te conseiller d'être ouverte et de penser de façon positive. Tu verras, dans quelques semaines, tu iras déjà mieux.","why":"*Ich kann dir nur raten, … zu …* : le conseil prend la forme *zu* + infinitif.","source":"g6865"}]},{"no":"20","part":"b","part_instruction":"Schreiben Sie zwei weitere Ratschläge.","part_instruction_en":"Écrivez deux autres conseils pour l'amie. La réponse modèle n'est qu'une possibilité.","example":[{"label":"Beispiel","text":"Ich kann dir nur raten, …"}],"items":[{"label":"1","lead":"Ihre Ratschläge","text":"","open":true,"solution":"Ich kann dir nur raten, mit deiner Chefin zu sprechen. Wie findest du die Idee, dich nach der Arbeit mit deinen Kollegen zu verabreden?","en":"Je ne peux que te conseiller de parler à ta cheffe. Que penses-tu de l'idée de te donner rendez-vous avec tes collègues après le travail ?","why":"Les deux formules ont *zu* + infinitif à la fin ; avec un verbe pronominal, le pronom reste à l'intérieur : *dich … zu verabreden*.","source":"g6865"}]}]},{"page":"AB 157","heading":"D  Verkaufsgespräche","heading_en":"Entretiens de vente","exercises":[{"no":"21","tag":"D3","instruction":"Ich hätte gern …","instruction_en":"J'aimerais …","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie: Kundin (K), Verkäuferin (V).","part_instruction_en":"Qui dit quoi ? Tapez *K* pour la cliente (*Kundin*) ou *V* pour la vendeuse (*Verkäuferin*).","example":[{"label":"4 / c","text":"Vielen Dank für Ihre Hilfe. → **K** / Vielen Dank für Ihre Beratung. → **K**"}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … empfehlen? → **V**","en":"Puis-je vous recommander … ? → vendeuse","why":"Recommander, c'est le travail de la vendeuse.","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["K","Kundin"]],"solution":"Das muss ich mir noch überlegen. → **K**","en":"Je dois encore y réfléchir. → cliente","why":"La cliente ne s'est pas encore décidée.","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["V","Verkäuferin"]],"solution":"Brauchen Sie Hilfe? → **V**","en":"Avez-vous besoin d'aide ? → vendeuse","why":"Elle propose son aide.","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["V","Verkäuferin"]],"solution":"Was wünschen Sie? → **V**","en":"Que désirez-vous ? → vendeuse","why":"La vendeuse demande ce que vous voulez.","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["K","Kundin"]],"solution":"Entschuldigung, ist es möglich, …? → **K**","en":"Excusez-moi, est-il possible de … ? → cliente","why":"La cliente demande quelque chose.","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie noch einen Wunsch? → **V**","en":"Désirez-vous encore autre chose ? → vendeuse","why":"Se demande vers la fin d'une vente.","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["K","Kundin"]],"solution":"Ich bin auf der Suche nach … → **K**","en":"Je suis à la recherche de … → cliente","why":"La cliente dit ce dont elle a besoin.","source":"hueber"},{"label":"a","text":"Ich hätte gern … → ___","gaps":[["K","Kundin"]],"solution":"Ich hätte gern … → **K**","en":"J'aimerais … → cliente","why":"Façon polie de demander quelque chose (Konjunktiv II).","source":"hueber"},{"label":"b","text":"Wie kann ich Ihnen helfen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Wie kann ich Ihnen helfen? → **V**","en":"Comment puis-je vous aider ? → vendeuse","why":"Elle propose son aide.","source":"hueber"},{"label":"d","text":"Haben Sie einen bestimmten Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie einen bestimmten Wunsch? → **V**","en":"Vous cherchez quelque chose de précis ? → vendeuse","why":"La vendeuse demande ce que vous voulez.","source":"hueber"},{"label":"e","text":"Darf ich Ihnen … anbieten? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … anbieten? → **V**","en":"Puis-je vous proposer … ? → vendeuse","why":"Elle propose quelque chose.","source":"hueber"},{"label":"f","text":"Ich kann mich noch nicht entscheiden. → ___","gaps":[["K","Kundin"]],"solution":"Ich kann mich noch nicht entscheiden. → **K**","en":"Je n'arrive pas encore à me décider. → cliente","why":"La cliente ne s'est pas décidée.","source":"hueber"},{"label":"g","text":"Dürfte ich Sie etwas fragen? Kann man … → ___","gaps":[["K","Kundin"]],"solution":"Dürfte ich Sie etwas fragen? Kann man … → **K**","en":"Pourrais-je vous demander quelque chose ? Est-ce qu'on peut … → cliente","why":"Question polie (Konjunktiv II *dürfte*).","source":"hueber"},{"label":"h","text":"Möchten Sie sonst noch etwas? → ___","gaps":[["V","Verkäuferin"]],"solution":"Möchten Sie sonst noch etwas? → **V**","en":"Vous désirez autre chose ? → vendeuse","why":"Se demande vers la fin d'une vente.","source":"hueber"}]},{"no":"21","part":"b","part_instruction":"Wie kann man auch sagen? Verbinden Sie die Sätze in a.","part_instruction_en":"Quelle phrase de droite (a–h) a le même sens que chaque phrase de gauche ? Tapez la lettre.","phrases":["a Ich hätte gern …","b Wie kann ich Ihnen helfen?","c Vielen Dank für Ihre Beratung.","d Haben Sie einen bestimmten Wunsch?","e Darf ich Ihnen … anbieten?","f Ich kann mich noch nicht entscheiden.","g Dürfte ich Sie etwas fragen? Kann man …","h Möchten Sie sonst noch etwas?"],"example":[{"label":"4","text":"Vielen Dank für Ihre Hilfe. → **c** Vielen Dank für Ihre Beratung."}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["e"]],"solution":"Darf ich Ihnen … empfehlen? → **e**","en":"Puis-je vous recommander … ? → e Puis-je vous proposer … ?","why":"Les deux proposent quelque chose à la cliente.","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["f"]],"solution":"Das muss ich mir noch überlegen. → **f**","en":"Je dois encore y réfléchir. → f Je n'arrive pas encore à me décider.","why":"Les deux disent : pas encore décidé.","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["b"]],"solution":"Brauchen Sie Hilfe? → **b**","en":"Avez-vous besoin d'aide ? → b Comment puis-je vous aider ?","why":"Les deux proposent de l'aide.","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["d"]],"solution":"Was wünschen Sie? → **d**","en":"Que désirez-vous ? → d Vous cherchez quelque chose de précis ?","why":"Les deux demandent ce que veut la cliente.","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["g"]],"solution":"Entschuldigung, ist es möglich, …? → **g**","en":"Excusez-moi, est-il possible de … ? → g Pourrais-je vous demander quelque chose ? Est-ce qu'on peut … ?","why":"Les deux sont des questions polies de la cliente.","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["h"]],"solution":"Haben Sie noch einen Wunsch? → **h**","en":"Désirez-vous encore autre chose ? → h Vous désirez autre chose ?","why":"Les deux demandent si la cliente veut autre chose.","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["a"]],"solution":"Ich bin auf der Suche nach … → **a**","en":"Je suis à la recherche de … → a J'aimerais …","why":"Les deux disent ce que veut la cliente.","source":"hueber"}]}]},{"page":"AB 158","heading":"E  Reklamation","heading_en":"Réclamations","exercises":[{"no":"23","tag":"E2","instruction":"Ergänzen Sie.","instruction_en":"Complétez les phrases tirées de lettres de réclamation. Le livre donne quelques lettres de chaque mot (indiquées au-dessus de la phrase) ; tapez le mot en entier. (L'exercice 22 est une compréhension orale et n'est pas repris.)","items":[{"label":"a","lead":"f _ _ _ _ _ _  …  _ _ _","text":"Ich ___ Sie jetzt zum letzten Mal ___, mir bis 31.03. zu antworten.","gaps":[["fordere"],["auf"]],"solution":"Ich **fordere** Sie jetzt zum letzten Mal **auf**, mir bis 31.03. zu antworten.","en":"Je vous somme maintenant pour la dernière fois de me répondre d'ici le 31 mars.","why":"*jemanden auffordern, … zu …* = sommer quelqu'un de … ; verbe à particule séparable : *ich fordere … auf*.","source":"hueber"},{"label":"b","lead":"S _ _ _ _ _ _ _  /  E _ _ _ _ _  /  A _ s p _ _ _ _","text":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. ___ Sie mir bitte einen ___. Ich habe ___ auf eine neue Uhr.","gaps":[["Schicken"],["Ersatz"],["Anspruch"]],"solution":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. **Schicken** Sie mir bitte einen **Ersatz**. Ich habe **Anspruch** auf eine neue Uhr.","en":"Malheureusement, la montre que j'ai achetée hier ne fonctionne pas. Veuillez m'envoyer un article de remplacement. J'ai droit à une nouvelle montre.","why":"*der Ersatz* = le remplacement ; *Anspruch haben auf* + accusatif = avoir droit à.","source":"hueber"},{"label":"c","lead":"b _ _ _ _ ä _ _ _ t","text":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … ___ ist.","gaps":[["beschädigt"]],"solution":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … **beschädigt** ist.","en":"En ouvrant le colis, j'ai malheureusement constaté que le/la … est endommagé(e).","why":"*beschädigt* = endommagé.","source":"hueber"},{"label":"d","lead":"ä _ g _ _ l _ _ _","text":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr ___.","gaps":[["ärgerlich"]],"solution":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr **ärgerlich**.","en":"Je vous ai déjà écrit deux fois sans recevoir de réponse. C'est vraiment très contrariant.","why":"*ärgerlich* = contrariant, fâcheux.","source":"hueber"},{"label":"e","lead":"u _ _ a _ _ _ _ _ _","text":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser ___.","gaps":[["umtauschen"]],"solution":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser **umtauschen**.","en":"Le pull est beau, mais malheureusement il ne va pas à mon mari. J'aimerais donc l'échanger contre une taille au-dessus.","why":"*umtauschen* = échanger (dans un magasin).","source":"hueber"},{"label":"f","lead":"A _ _ _ o _ _","text":"Leider habe ich immer noch keine ___ erhalten.","gaps":[["Antwort"]],"solution":"Leider habe ich immer noch keine **Antwort** erhalten.","en":"Malheureusement, je n'ai toujours pas reçu de réponse.","why":"*die Antwort* = la réponse.","source":"hueber"},{"label":"g","lead":"B _ _ t _ _ _ _ e _","text":"___ Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","gaps":[["Bestätigen"]],"solution":"**Bestätigen** Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","en":"Veuillez me confirmer par écrit que vous avez bien reçu ma réclamation.","why":"*bestätigen* = confirmer.","source":"hueber"},{"label":"h","lead":"v _ _ ä _ _ _ r _  /  e _ _ t _ _ _ _ _ _","text":"Ich bin sehr ___ und von Ihrem Service sehr ___.","gaps":[["verärgert"],["enttäuscht"]],"solution":"Ich bin sehr **verärgert** und von Ihrem Service sehr **enttäuscht**.","en":"Je suis très fâché et très déçu de votre service.","why":"*verärgert* = fâché ; *enttäuscht von* = déçu de.","source":"hueber"}]},{"no":"24","tag":"E2","instruction":"Eine schriftliche Reklamation","instruction_en":"Une réclamation écrite","part":"a","part_instruction":"Was bedeuten die Sätze? Ordnen Sie zu.","part_instruction_en":"Les phrases de gauche montrent comment on écrit dans une lettre de réclamation ; l'encadré montre comment on le dirait au quotidien. Tapez la lettre (a–g) qui a le même sens.","phrases":["a Wenn ich bis … nichts gehört habe, dann will ich den/die … nicht mehr haben.","b Ich habe Ihnen schon zweimal geschrieben und gesagt, dass ich eine(n) neue(n) … möchte.","c Schade. Der/Die … ist kaputt.","d Ich sage es Ihnen jetzt noch ein letztes Mal: Bitte schicken Sie mir spätestens am … eine(n) neue(n) …","e Ich habe wirklich gedacht, dass Ihr Service viel besser ist.","f Ich bin enttäuscht, dass ich immer noch nichts von Ihnen gehört habe.","g Ich habe am 16. Februar von Ihnen … bekommen."],"example":[{"label":"2","text":"Leider ist … defekt. → **c** Schade. Der/Die … ist kaputt."}],"items":[{"label":"1","text":"Am 16.2. haben Sie mir … geliefert. → ___","gaps":[["g"]],"solution":"Am 16.2. haben Sie mir … geliefert. → **g**","en":"Le 16 février, vous m'avez livré … → g","why":"Les deux disent ce que vous avez reçu et quand.","source":"hueber"},{"label":"3","text":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → ___","gaps":[["b"]],"solution":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → **b**","en":"Je vous ai déjà écrit deux fois un e-mail pour vous demander de m'envoyer un article de remplacement. → b","why":"*bereits* = *schon* ; *Ersatz* = un nouvel article. (*das E-Mail* est l'usage suisse.)","source":"hueber"},{"label":"4","text":"Leider habe ich immer noch keine Antwort erhalten. → ___","gaps":[["f"]],"solution":"Leider habe ich immer noch keine Antwort erhalten. → **f**","en":"Malheureusement, je n'ai toujours pas reçu de réponse. → f","why":"Toujours pas de réponse → déçu.","source":"hueber"},{"label":"5","text":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → ___","gaps":[["e"]],"solution":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → **e**","en":"Je dois dire que votre service m'a beaucoup déçu. → e","why":"Vous attendiez un meilleur service.","source":"hueber"},{"label":"6","text":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → ___","gaps":[["d"]],"solution":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → **d**","en":"Je vous somme pour la dernière fois de m'envoyer un article de remplacement d'ici le … → d","why":"*zum letzten Mal* = *ein letztes Mal*.","source":"hueber"},{"label":"7","text":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → ___","gaps":[["a"]],"solution":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → **a**","en":"Si je n'ai pas de nouvelles de votre part d'ici le …, je renonce à la commande. → a","why":"*auf etwas verzichten* = se passer de quelque chose, y renoncer.","source":"hueber"}]},{"no":"24","tag":"Schreibtraining","part":"b","part_instruction":"Wählen Sie eine Situation und schreiben Sie eine Reklamation wie in a. Die Sätze 1–7 helfen Ihnen.","part_instruction_en":"Choisissez une situation et écrivez une réclamation comme en a. Les phrases 1–7 vous aident. Les réponses modèles ne sont chacune qu'une possibilité.","reading":[{"label":"1","text":"Kopfhörer bestellt – funktioniert nicht – schon einmal geschrieben, aber keine Antwort erhalten – bitte Ersatz bis … senden – wenn wieder keine Antwort, auf Bestellung verzichten"},{"label":"2","text":"Laptoptasche bestellt – Trageriemen nach einer Woche gerissen – zurückschicken – umtauschen oder Ersatz – bitte Reklamation bestätigen"}],"example":[{"label":"Beispiel","text":"Sehr geehrte Damen und Herren / Am 12.3. … / Freundliche Grüsse"}],"items":[{"label":"1","lead":"Situation 1: Kopfhörer","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 12.3. haben Sie mir Kopfhörer geliefert. Leider funktionieren sie nicht. Ich habe Ihnen schon einmal geschrieben, aber keine Antwort erhalten. Ich fordere Sie zum letzten Mal auf, mir bis 12.4. einen Ersatz zu schicken. Wenn ich wieder keine Antwort von Ihnen erhalte, dann verzichte ich auf die Bestellung. / Freundliche Grüsse / Luca Carelli","en":"Madame, Monsieur, / Le 12 mars, vous m'avez livré un casque audio. Malheureusement, il ne fonctionne pas. Je vous ai déjà écrit une fois, mais je n'ai pas reçu de réponse. Je vous somme pour la dernière fois de m'envoyer un article de remplacement d'ici le 12 avril. Si je ne reçois de nouveau aucune réponse de votre part, je renoncerai à la commande. / Meilleures salutations / Luca Carelli","why":"Les points clés dans l'ordre : ce que vous avez reçu et quand, ce qui ne va pas, ce que vous avez fait, ce que l'entreprise doit faire (*auffordern, … zu …*), ce que vous ferez sinon.","source":"hueber"},{"label":"2","lead":"Situation 2: Laptoptasche","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 3.5. haben Sie mir eine Laptoptasche geliefert. Leider ist der Trageriemen schon nach einer Woche gerissen. Das ist sehr ärgerlich. Ich schicke Ihnen die Tasche heute zurück und bitte Sie, sie umzutauschen oder mir einen Ersatz zu schicken. Im Anhang finden Sie eine Kopie der Rechnung. Bestätigen Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben. / Freundliche Grüsse / Maria Keller","en":"Madame, Monsieur, / Le 3 mai, vous m'avez livré une sacoche pour ordinateur portable. Malheureusement, la bandoulière s'est déchirée après une semaine seulement. C'est très contrariant. Je vous renvoie la sacoche aujourd'hui et vous prie de l'échanger ou de m'envoyer un article de remplacement. Vous trouverez en annexe une copie de la facture. Veuillez me confirmer par écrit que vous avez bien reçu ma réclamation. / Meilleures salutations / Maria Keller","why":"Notre propre modèle (le corrigé n'en donne pas pour la situation 2). *bitten, … zu …* : *umzutauschen* (verbe à particule séparable).","source":"g6865"}]}]},{"page":"AB 159","heading":"Test Lektion 6","heading_en":"Test de la leçon 6","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Complétez le texte. Le livre donne quelques lettres de chaque mot (indiquées au-dessus de la phrase) ; tapez le mot en entier.","example":[{"label":"a","text":"Ich war **jahrelang** angestellt, …"}],"items":[{"label":"b","lead":"b: e _ t _ _ _ _ l _ s _ _ n  /  c: K _ _ _ _ a _ _","text":"… aber irgendwann war ich unzufrieden und habe mich ___: Ich mache mich als ___ selbstständig und gründe eine Firma.","gaps":[["entschlossen"],["Kaufmann","Kauffrau"]],"solution":"… aber irgendwann war ich unzufrieden und habe mich **entschlossen**: Ich mache mich als **Kaufmann** selbstständig und gründe eine Firma.","en":"… mais à un moment donné, je n'étais plus satisfait et j'ai pris une décision : je me mets à mon compte comme commerçant et je fonde une entreprise.","why":"*sich entschliessen* (Perfekt : *hat sich entschlossen*) = se décider. *der Kaufmann* = le commerçant, le négociant.","source":"g6865","check":"Les lettres données indiquent *Kaufmann* ; une femme écrirait *Kauffrau*, qui suit un autre schéma. Les deux sont acceptés. Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."},{"label":"d","lead":"G _ _ _ _ ä _ _ _ l _ _ _ e","text":"Ein paar Freunde, die gute ___ sind, helfen mir dabei.","gaps":[["Geschäftsleute"]],"solution":"Ein paar Freunde, die gute **Geschäftsleute** sind, helfen mir dabei.","en":"Quelques amis qui sont de bons commerçants m'aident dans ce projet.","why":"*die Geschäftsleute* = les commerçants, les gens d'affaires (pluriel).","source":"g6865","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."},{"label":"e","lead":"e: f _ _ _ _ z _ _ _ _ _ s  /  f: l _ _ _ t","text":"Ich glaube nicht, dass es ein ___ Risiko ist. Im Gegenteil, ich denke es ___ sich.","gaps":[["finanzielles"],["lohnt"]],"solution":"Ich glaube nicht, dass es ein **finanzielles** Risiko ist. Im Gegenteil, ich denke es **lohnt** sich.","en":"Je ne crois pas que ce soit un risque financier. Au contraire, je pense que ça en vaut la peine.","why":"*ein finanzielles Risiko* (neutre) ; *es lohnt sich* = ça en vaut la peine.","source":"platzhalter","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit *damit* oder – wenn möglich – *um … zu*.","instruction_en":"Reliez les deux phrases. Employez *um … zu* quand la personne est la même ; sinon, employez *damit*.","example":[{"label":"a","lead":"Erika lernt Englisch. Sie möchte ausländische Kunden besser verstehen.","text":"Erika lernt Englisch, **um ausländische Kunden besser zu verstehen**."}],"items":[{"label":"b","lead":"Tomás macht eine Weiterbildung. Er möchte seine kommunikativen Kompetenzen verbessern.","text":"","accept":["Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern."],"solution":"**Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern.**","en":"Tomás suit une formation continue pour améliorer ses compétences en communication.","why":"Même personne (Tomás) → *um … zu* ; *möchte* est supprimé.","source":"g6865","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."},{"label":"c","lead":"Frau Seil arbeitet nur halbtags. Die Kinder sollen nicht allein sein, wenn sie aus der Schule kommen.","text":"","accept":["Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen."],"solution":"**Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen.**","en":"Mme Seil ne travaille qu'à mi-temps pour que les enfants ne soient pas seuls quand ils rentrent de l'école.","why":"Autre personne (les enfants) → *damit* ; *sollen* est supprimé.","source":"damit","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."},{"label":"d","lead":"Rodolfo kümmert sich diese Woche um die Kinder. Seine Frau kann ihre kranke Mutter besuchen.","text":"","accept":["Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann."],"solution":"**Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann.**","en":"Cette semaine, Rodolfo s'occupe des enfants pour que sa femme puisse rendre visite à sa mère malade.","why":"Autre personne (sa femme) → *damit* ; *kann* va à la fin.","source":"damit","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."}]},{"no":"3","instruction":"Ergänzen Sie: *ohne … zu* oder *statt … zu*.","instruction_en":"Tapez *ohne* ou *statt* dans le premier trou et *zu* dans le second.","example":[{"label":"a","text":"Wenn man streiten kann, **ohne** alles persönlich **zu** nehmen, dann ist man konfliktfähig."}],"items":[{"label":"b","text":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, ___ ergebnislos ___ streiten.","gaps":[["statt"],["zu"]],"solution":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, **statt** ergebnislos **zu** streiten.","en":"On sait faire des compromis quand on se met d'accord avec quelqu'un sur des points litigieux au lieu de se disputer sans résultat.","why":"Se mettre d'accord remplace le fait de se disputer → *statt*.","source":"komma","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."},{"label":"c","text":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, ___ sich selbst zu wichtig ___ nehmen.","gaps":[["ohne"],["zu"]],"solution":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, **ohne** sich selbst zu wichtig **zu** nehmen.","en":"Un bon chef, c'est quelqu'un qui dirige ses collaborateurs sans se prendre trop au sérieux.","why":"Il dirige et, en même temps, ne se prend pas trop au sérieux → *ohne*. Le premier *zu* signifie « trop ».","source":"komma","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."},{"label":"d","text":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, ___ immer nur alles allein ___ machen.","gaps":[["statt"],["zu"]],"solution":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, **statt** immer nur alles allein **zu** machen.","en":"Celui qui a l'esprit d'équipe aime travailler avec ses collègues au lieu de toujours tout faire seul.","why":"Le travail d'équipe remplace le travail en solitaire → *statt*.","source":"komma","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."},{"label":"e","text":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, ___ gestresst ___ sein.","gaps":[["ohne"],["zu"]],"solution":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, **ohne** gestresst **zu** sein.","en":"Est flexible quelqu'un qui peut s'habituer à de nouvelles situations rapidement et sans problème, sans être stressé.","why":"Le stress n'a pas lieu → *ohne*.","source":"komma","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."}]},{"no":"4","instruction":"Vor dem Bewerbungsgespräch. Was ist richtig? Kreuzen Sie an.","instruction_en":"Avant l'entretien d'embauche : des conseils pour un ami. Tapez l'expression qui convient au reste de la phrase. Les deux choix sont indiqués au-dessus de chaque phrase.","example":[{"label":"a","text":"**An deiner Stelle würde** ich heute noch ein bisschen über die Firma im Internet recherchieren."}],"items":[{"label":"b","lead":"Wie wäre es, wenn / Ich kann dir nur raten,","text":"___ du dir ein paar Fragen überlegst, die du morgen stellen kannst?","gaps":[["Wie wäre es, wenn","Wie wäre es wenn"]],"solution":"**Wie wäre es, wenn** du dir ein paar Fragen überlegst, die du morgen stellen kannst?","en":"Et si tu réfléchissais à quelques questions que tu pourras poser demain ?","why":"*du … überlegst* avec le verbe à la fin demande *wenn* : *Wie wäre es, wenn …?*","source":"g6865","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."},{"label":"c","lead":"Was hältst du davon, / Du könntest zum Beispiel","text":"___ fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","gaps":[["Du könntest zum Beispiel"]],"solution":"**Du könntest zum Beispiel** fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","en":"Tu pourrais par exemple demander quelle est la taille de l'équipe ou quelles seront tes tâches.","why":"Un infinitif simple (*fragen*) suit un verbe de modalité : *Du könntest … fragen*.","source":"g6865","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."},{"label":"d","lead":"An deiner Stelle würde ich / Ich kann dir nur raten,","text":"___ du selbst zu sein. Das ist das Allerwichtigste.","gaps":[["Ich kann dir nur raten,","Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten,** du selbst zu sein. Das ist das Allerwichtigste.","en":"Je ne peux que te conseiller d'être toi-même. C'est le plus important de tout.","why":"*zu sein* demande une formule qui se construit avec *zu* + infinitif : *Ich kann dir nur raten, …*","source":"g6865","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."},{"label":"e","lead":"Wie wäre es, wenn / Was hältst du davon,","text":"___ heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","gaps":[["Was hältst du davon,","Was hältst du davon"]],"solution":"**Was hältst du davon,** heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","en":"Qu'est-ce que tu penses d'aller manger au restaurant ce soir ? Ça te changera les idées.","why":"*essen zu gehen* (zu + infinitif) convient à *Was hältst du davon, … zu …?*","source":"g6865","check":"Le corrigé de l'Arbeitsbuch ne couvre pas le test de la leçon ; cette réponse est la nôtre, vérifiée avec grammis."}]}]},{"page":"AB 160","heading":"Fokus Beruf: Kundenwünsche","heading_en":"Focus métier : demandes des clients","exercises":[{"no":"3","instruction":"Arbeiten Sie zu dritt. Wählen Sie je eine Rolle und spielen Sie drei Telefongespräche.","instruction_en":"Travaillez à trois : chaque personne prend un rôle et vous jouez trois appels téléphoniques. Exercez-vous à l'écrit ou à l'oral ; les dialogues modèles ne sont qu'une possibilité. (Les exercices 1 et 2 sont des compréhensions orales et ne sont pas repris.)","reading":[{"label":"A  Kundin/Kunde","text":"Sie machen heute eine Grillparty. Sie haben beim Getränkeservice *Getränkeblitz* drei Harasse Mineralwasser und vier Harasse Süssmost bestellt."},{"label":"B  Angestellte/Angestellter","text":"Sie arbeiten bei der Firma *Getränkeblitz* und bekommen einen Beschwerdeanruf von einer Kundin. Sie können nicht direkt helfen. Sie müssen zuerst mit dem Fahrer sprechen und rufen die Kundin dann zurück."},{"label":"C  Fahrerin/Fahrer","text":"Sie arbeiten als Fahrer/in für die Firma *Getränkeblitz*. Sie haben für die Grillparty sieben Harasse Mineralwasser geliefert."}],"phrases":["Gespräch 1 – Kunde: Ich habe bei Ihnen … bestellt. | Jetzt ist die Lieferung gekommen, aber … | Sie haben wohl einen Fehler gemacht. | Ich habe … bestellt und nicht …","Gespräch 1 – Angestellte: Oh, das tut mir leid. | Da ist wohl ein Fehler/ein Irrtum passiert. | Ich rufe sofort meine Kollegin/meinen Kollegen an. | Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","Gespräch 2 – Angestellte: Frau/Herr … hat angerufen. | Du hast ihm/ihr … statt … geliefert. | Wir machen Folgendes: … | Ich rufe an und frage nach, ob das okay ist.","Gespräch 2 – Fahrer: Oh je, da habe ich wohl einen Fehler gemacht. | Da habe ich wohl etwas verwechselt. | Was machen wir denn jetzt? | Ich könnte …","Gespräch 3 – Angestellte: Es tut mir wahnsinnig leid. | Meine Kollegin/Mein Kollege hat einen Fehler gemacht. | Wir könnten Ihnen … | Selbstverständlich geben wir Ihnen einen Rabatt.","Gespräch 3 – Kunde: Ja, damit bin ich einverstanden. | Nein, tut mir leid. Das war doch Ihr Fehler, nicht meiner. | Ich mache Ihnen einen anderen Vorschlag: …"],"items":[{"label":"1","lead":"Gespräch 1: Kundin und Angestellter","text":"","open":true,"solution":"Kundin: Grüezi, hier ist Meier. Ich habe bei Ihnen drei Harasse Mineralwasser und vier Harasse Süssmost bestellt. Jetzt ist die Lieferung gekommen, aber es sind sieben Harasse Mineralwasser. Ich habe Süssmost bestellt und nicht nur Wasser! / Angestellter: Oh, das tut mir leid. Da ist wohl ein Fehler passiert. Ich rufe sofort meinen Kollegen an. Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","en":"Cliente : Bonjour, ici Meier. Je vous ai commandé trois harasses d'eau minérale et quatre harasses de jus de pomme. La livraison vient d'arriver, mais ce sont sept harasses d'eau minérale. J'ai commandé du jus de pomme, pas seulement de l'eau ! / Employé : Oh, je suis désolé. Il y a sans doute eu une erreur. J'appelle tout de suite mon collègue. Donnez-moi votre numéro de portable, s'il vous plaît, je vous rappelle immédiatement.","why":"Réclamation : dites ce que vous avez commandé et ce qui est arrivé (*bestellt … und nicht …*). L'employé s'excuse et promet de rappeler. (*der Harass* = mot suisse pour une caisse de boissons ; *der Süssmost* = jus de pomme suisse.)","source":"hueber"},{"label":"2","lead":"Gespräch 2: Angestellter und Fahrer","text":"","open":true,"solution":"Angestellter: Hallo Marco, Frau Meier hat angerufen. Du hast ihr sieben Harasse Mineralwasser statt drei Harasse Wasser und vier Harasse Süssmost geliefert. / Fahrer: Oh je, da habe ich wohl etwas verwechselt. Was machen wir denn jetzt? Ich könnte heute Nachmittag noch einmal hinfahren. / Angestellter: Gut, wir machen Folgendes: Du bringst ihr vier Harasse Süssmost und holst vier Harasse Wasser wieder ab. Ich rufe an und frage nach, ob das okay ist.","en":"Employé : Salut Marco, Mme Meier a appelé. Tu lui as livré sept harasses d'eau minérale au lieu de trois harasses d'eau et quatre harasses de jus de pomme. / Chauffeur : Oh là là, j'ai dû confondre quelque chose. Qu'est-ce qu'on fait maintenant ? Je pourrais y retourner cet après-midi. / Employé : Bien, voilà ce qu'on va faire : tu lui apportes quatre harasses de jus de pomme et tu reprends quatre harasses d'eau. J'appelle et je demande si ça lui convient.","why":"Entre collègues, on se dit *du*. *statt* + nom ici (*statt drei Harasse Wasser*) : la même idée que *statt … zu*, mais avec une chose.","source":"hueber"},{"label":"3","lead":"Gespräch 3: Angestellter und Kundin","text":"","open":true,"solution":"Angestellter: Frau Meier, es tut mir wahnsinnig leid. Mein Kollege hat einen Fehler gemacht. Wir könnten Ihnen den Süssmost noch heute bis 17 Uhr bringen. Selbstverständlich geben wir Ihnen einen Rabatt von 20 Prozent. / Kundin: Ja, damit bin ich einverstanden. Die Party fängt erst um 18 Uhr an. Vielen Dank!","en":"Employé : Madame Meier, je suis vraiment désolé. Mon collègue a fait une erreur. Nous pourrions vous apporter le jus de pomme aujourd'hui encore, d'ici 17 heures. Bien entendu, nous vous accordons un rabais de 20 pour cent. / Cliente : Oui, je suis d'accord avec cela. La fête ne commence qu'à 18 heures. Merci beaucoup !","why":"Proposez une solution avec *Wir könnten Ihnen …* (Konjunktiv II = poli). La cliente accepte : *damit bin ich einverstanden* (ici *damit* = avec cela, pas *pour que*).","source":"hueber"}]}]}],"sources":[{"id":"hueber","title":"Hueber : Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (corrigé officiel, Lektion 6)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (um … zu n'a pas de sujet propre ; il est repris de la principale)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"damit","title":"grammis, dictionnaire des connecteurs : damit (subjonction avec le verbe à la fin ; aussi adverbe signifiant « avec cela »)","url":"https://grammis.ids-mannheim.de/konnektoren/407001"},{"id":"komma","title":"grammis: Komma bei Nebensätzen (les propositions infinitives avec um, ohne, (an)statt sont séparées par une virgule)","url":"https://grammis.ids-mannheim.de/rechtschreibung/6203"},{"id":"platzhalter","title":"grammis: Platzhalter (es en position 1 ; le es formel des verbes de météo reste : Heute schneit es)","url":"https://grammis.ids-mannheim.de/vggf/2284"},{"id":"korrelat","title":"grammis: Korrelat (es qui annonce une proposition : Ich kann es nicht erwarten, euch zu sehen)","url":"https://grammis.ids-mannheim.de/vggf/2283"}]},{"id":"06-lektion-6-zusatzblaetter","no":6,"title":"Lektion 6 Homework – extra exercises from printed sheets","title_en":"Au lieu de (*anstatt … zu / anstatt dass*), sans (*ohne … zu / ohne dass*), but (*um … zu / damit*)","added":"2026-11-20","book":"Printed grammar sheets 48, 49 and 52 (extra homework for Schritte plus Neu 5, Lektion 6)","pages":[{"page":"Blatt 48 · S. 100","heading":"48  Ich lade gerne Freunde ein, anstatt allein zu essen.","heading_en":"J'aime inviter des amis chez moi au lieu de manger seul. (Proposition principale + proposition infinitive / subordonnée de manière : *anstatt … zu, anstatt dass*)","exercises":[{"no":"A","instruction":"Welches Foto passt? Kreuzen Sie an.","instruction_en":"Quelle photo correspond à la phrase ? Photo A : des amis qui mangent ensemble à une grande table. Photo B : un homme qui mange seul. Tapez A ou B. Les encadrés de règles B et C de la fiche sont présentés ci-dessous.","reading":[{"label":"B  Lesen Sie.","text":"Infinitiv mit anstatt … zu: Ich lade gerne Freunde ein, | anstatt immer allein zu essen.\nNebensatz mit anstatt dass: Ich lade gerne Freunde ein, | anstatt dass ich immer allein esse.\nDie Subjekte in Haupt- und Nebensatz sind gleich: anstatt … zu oder anstatt dass\nIch lade gerne Freunde ein, | anstatt immer allein zu essen. / anstatt dass ich immer allein esse.\nDie Subjekte in Hauptsatz und Nebensatz sind nicht gleich: immer anstatt dass\nEr lädt gerne Freunde ein, | anstatt dass wir immer allein essen."},{"label":"C  Lesen Sie.","text":"• *anstatt … zu* und *anstatt dass* signalisieren, dass eine Alternative möglich ist.\n• Im Infinitivsatz mit *anstatt … zu* steht kein Subjekt. Das Subjekt aus dem Hauptsatz ist auch Subjekt im Infinitivsatz.\n• Man kann *anstatt* oder *statt* benutzen, es gibt keinen Unterschied: Wir lachen anstatt zu weinen. = Wir lachen statt zu weinen."}],"items":[{"label":"1","text":"Ich lade gerne Freunde ein, anstatt immer allein zu essen. → Foto ___","gaps":[["A"]],"solution":"Ich lade gerne Freunde ein, anstatt immer allein zu essen. → Foto **A**","en":"J'aime inviter des amis chez moi au lieu de toujours manger seul. → Photo A","why":"La photo A montre les amis à table, l'alternative qu'il a choisie ; la photo B montre ce qu'il *ne fait pas*.","source":"anstattdass"}]},{"no":"1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Quelles phrases sont justes ? Tapez *richtig* ou *falsch*. Astuce : *anstatt* signifie déjà « pas ceci », donc il n'est suivi ni de *nicht* ni de *kein*.","example":[{"label":"1","text":"Ich verabrede mich mit Freunden, anstatt allein fernzusehen. → **richtig**"}],"items":[{"label":"2","text":"Ich verabrede mich mit Freunden, anstatt nicht allein fernzusehen. → ___","gaps":[["falsch"]],"solution":"Ich verabrede mich mit Freunden, anstatt nicht allein fernzusehen. → **falsch**","en":"Je prends rendez-vous avec des amis au lieu de ne pas regarder la télévision seul. → faux","why":"*anstatt* nie déjà : *anstatt nicht …* dit le contraire de ce que l'on veut dire.","source":"anstattdass"},{"label":"3","text":"Ich veröffentliche mein Buch bei Amazon, anstatt keinen Verlag zu suchen. → ___","gaps":[["falsch"]],"solution":"Ich veröffentliche mein Buch bei Amazon, anstatt keinen Verlag zu suchen. → **falsch**","en":"Je publie mon livre sur Amazon au lieu de ne chercher aucun éditeur. → faux","why":"Pas de *kein* après *anstatt* : l'action remplacée est *einen Verlag suchen*.","source":"anstattdass"},{"label":"4","text":"Ich veröffentliche mein Buch bei Amazon, anstatt einen Verlag zu suchen. → ___","gaps":[["richtig"]],"solution":"Ich veröffentliche mein Buch bei Amazon, anstatt einen Verlag zu suchen. → **richtig**","en":"Je publie mon livre sur Amazon au lieu de chercher un éditeur. → juste","why":"Action positive après *anstatt*, *zu* + infinitif à la fin.","source":"g6865"}]}]},{"page":"Blatt 48 · S. 101","heading":"48  Ich lade gerne Freunde ein, anstatt allein zu essen.","heading_en":"J'aime inviter des amis chez moi au lieu de manger seul.","exercises":[{"no":"2","instruction":"Vereine. Verbinden Sie die Sätze mit *anstatt … zu*. Schreiben Sie in Ihr Heft.","instruction_en":"Les associations. Reliez les deux phrases avec *anstatt … zu*. La deuxième phrase dit ce qui *n'a pas* lieu : supprimez son *nicht* et son sujet, mettez *zu* + infinitif à la fin.","example":[{"label":"1","lead":"Ich werde Mitglied in einem Fussballverein. Ich mache nicht allein Sport.","text":"Ich werde Mitglied in einem Fussballverein, **anstatt allein Sport zu machen**."}],"items":[{"label":"2","lead":"Sie können den Mitgliedsbeitrag auch monatlich überweisen. Sie zahlen nicht sofort fürs ganze Jahr.","text":"","accept":["Sie können den Mitgliedsbeitrag auch monatlich überweisen, anstatt sofort fürs ganze Jahr zu zahlen.","Sie können den Mitgliedsbeitrag auch monatlich überweisen, statt sofort fürs ganze Jahr zu zahlen."],"solution":"**Sie können den Mitgliedsbeitrag auch monatlich überweisen, anstatt sofort fürs ganze Jahr zu zahlen.**","en":"Vous pouvez aussi payer la cotisation par virement chaque mois au lieu de payer tout de suite pour l'année entière.","why":"*nicht* disparaît ; *zu zahlen* va à la fin.","source":"g6865"},{"label":"3","lead":"Wir nehmen Tom in unseren Verein auf. Wir sagen ihm nicht wieder ab.","text":"","accept":["Wir nehmen Tom in unseren Verein auf, anstatt ihm wieder abzusagen.","Wir nehmen Tom in unseren Verein auf, statt ihm wieder abzusagen."],"solution":"**Wir nehmen Tom in unseren Verein auf, anstatt ihm wieder abzusagen.**","en":"Nous accueillons Tom dans notre association au lieu de lui dire non encore une fois.","why":"Verbe séparable : *zu* se place entre la particule et le verbe : *abzusagen* (ab + zu + sagen).","source":"g6865"},{"label":"4","lead":"Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen. Sie werden nicht sofort Mitglied.","text":"","accept":["Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, anstatt sofort Mitglied zu werden.","Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, statt sofort Mitglied zu werden."],"solution":"**Sie können auch erst einmal einfach so zu unseren Veranstaltungen kommen, anstatt sofort Mitglied zu werden.**","en":"Vous pouvez aussi d'abord venir simplement à nos événements au lieu de devenir membre tout de suite.","why":"Même sujet *Sie* : *anstatt … Mitglied zu werden*.","source":"g6865"}]},{"no":"3","instruction":"Unterstreichen Sie die Subjekte. Welche sind gleich? Kreuzen Sie an.","instruction_en":"Trouvez le sujet de chaque phrase (qui fait l'action), puis dites s'il s'agit de la même personne ou chose. Tapez les deux sujets, puis *gleich* (identiques) ou *nicht gleich* (pas identiques). Attention : le sujet n'est pas toujours en position 1.","example":[{"label":"1","text":"Sie möchte Bücher schreiben. Sie arbeitet nicht weiter im Büro. → **Sie** / **Sie** → **gleich**"}],"items":[{"label":"2","text":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher. → ___ / ___ → ___","gaps":[["Der Verlag"],["Die Autoren"],["nicht gleich"]],"solution":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher. → **Der Verlag** / **Die Autoren** → **nicht gleich**","en":"La maison d'édition ne veut plus que développer des applications. Les auteurs n'écrivent pas de livres. → pas identiques","why":"Deux sujets différents : *der Verlag* et *die Autoren*.","source":"anstattdass"},{"label":"3","text":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag. → ___ / ___ → ___","gaps":[["Sie"],["sie"],["gleich"]],"solution":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag. → **Sie** / **sie** → **gleich**","en":"Elle publie le roman à compte d'auteur. Le manuscrit, elle ne l'envoie pas à un éditeur. → identiques","why":"*Das Manuskript* est l'objet (c'est lui qu'on envoie) ; le sujet *sie* vient après le verbe.","source":"g6865"},{"label":"4","text":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher. → ___ / ___ → ___","gaps":[["Der Verlag"],["Er"],["gleich"]],"solution":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher. → **Der Verlag** / **Er** → **gleich**","en":"La maison d'édition ne publie plus qu'en ligne. Elle n'imprime pas de livres. → identiques","why":"*Er* renvoie à *der Verlag*.","source":"g6865"}]},{"no":"4","instruction":"Verbinden Sie die Sätze aus 4 mit *anstatt … zu* und / oder *anstatt dass*.","instruction_en":"Reliez les phrases de l'exercice 3 (la fiche indique « aus 4 » par erreur). Même sujet : les deux formes fonctionnent. Sujets différents : seulement *anstatt dass*. Supprimez *nicht* / transformez *kein* en *ein* ou supprimez-le.","example":[{"label":"1","text":"anstatt … zu: Sie möchte Bücher schreiben, **anstatt weiter im Büro zu arbeiten**.\nanstatt dass: Sie möchte Bücher schreiben, **anstatt dass sie weiter im Büro arbeitet**."}],"items":[{"label":"2 · anstatt dass","lead":"Der Verlag möchte nur noch Apps entwickeln. Die Autoren schreiben keine Bücher.","text":"","accept":["Der Verlag möchte nur noch Apps entwickeln, anstatt dass die Autoren Bücher schreiben.","Der Verlag möchte nur noch Apps entwickeln, statt dass die Autoren Bücher schreiben."],"solution":"**Der Verlag möchte nur noch Apps entwickeln, anstatt dass die Autoren Bücher schreiben.**","en":"La maison d'édition ne veut plus que développer des applications, au lieu que les auteurs écrivent des livres.","why":"Sujets différents → seulement *anstatt dass* ; *keine Bücher* → *Bücher* ; verbe à la fin.","source":"anstattdass"},{"label":"3 · anstatt … zu","lead":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag.","text":"","accept":["Sie veröffentlicht den Roman im Selbstverlag, anstatt das Manuskript an einen Verlag zu schicken.","Sie veröffentlicht den Roman im Selbstverlag, statt das Manuskript an einen Verlag zu schicken."],"solution":"**Sie veröffentlicht den Roman im Selbstverlag, anstatt das Manuskript an einen Verlag zu schicken.**","en":"Elle publie le roman à compte d'auteur au lieu d'envoyer le manuscrit à un éditeur.","why":"Même sujet : pas de *sie* dans la proposition infinitive, pas de virgule avant *zu*.","source":"g6865"},{"label":"3 · anstatt dass","lead":"Sie veröffentlicht den Roman im Selbstverlag. Das Manuskript schickt sie nicht an einen Verlag.","text":"","accept":["Sie veröffentlicht den Roman im Selbstverlag, anstatt dass sie das Manuskript an einen Verlag schickt.","Sie veröffentlicht den Roman im Selbstverlag, statt dass sie das Manuskript an einen Verlag schickt."],"solution":"**Sie veröffentlicht den Roman im Selbstverlag, anstatt dass sie das Manuskript an einen Verlag schickt.**","en":"Elle publie le roman à compte d'auteur au lieu d'envoyer le manuscrit à un éditeur.","why":"*anstatt dass* demande son propre sujet *sie* ; le verbe *schickt* va à la fin.","source":"anstattdass"},{"label":"4 · anstatt … zu","lead":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher.","text":"","accept":["Der Verlag veröffentlicht nur noch online, anstatt Bücher zu drucken.","Der Verlag veröffentlicht nur noch online, statt Bücher zu drucken."],"solution":"**Der Verlag veröffentlicht nur noch online, anstatt Bücher zu drucken.**","en":"La maison d'édition ne publie plus qu'en ligne au lieu d'imprimer des livres.","why":"*keine Bücher* → *Bücher* ; *zu drucken* à la fin.","source":"g6865"},{"label":"4 · anstatt dass","lead":"Der Verlag veröffentlicht nur noch online. Er druckt keine Bücher.","text":"","accept":["Der Verlag veröffentlicht nur noch online, anstatt dass er Bücher druckt.","Der Verlag veröffentlicht nur noch online, statt dass er Bücher druckt."],"solution":"**Der Verlag veröffentlicht nur noch online, anstatt dass er Bücher druckt.**","en":"La maison d'édition ne publie plus qu'en ligne au lieu d'imprimer des livres.","why":"Sujet *er* + verbe *druckt* à la fin.","source":"anstattdass"}]},{"no":"5","instruction":"Was würden Sie gerne machen? Schreiben Sie Sätze mit *anstatt … zu*.","instruction_en":"Qu'aimeriez-vous faire ? Combinez un souhait de la première partie de l'encadré (*Ich würde gerne …*) avec un élément de la deuxième partie (*anstatt … zu*). Les expressions barrées sont utilisées dans l'exemple. La réponse modèle n'est qu'une possibilité.","box":["Sport in einem Verein machen","an einem Tag Homeoffice machen","öfter an die frische Luft gehen","schöne Dinge kaufen","etwas mit meiner Familie unternehmen","immer nur sparen","jeden Tag ins Büro fahren","immer allein joggen","am Wochenende arbeiten","immer im klimatisierten Büro sitzen"],"box_used":[0,7],"example":[{"label":"Beispiel","text":"Ich würde gerne Sport in einem Verein machen, **anstatt immer allein zu joggen**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gerne an einem Tag Homeoffice machen, anstatt jeden Tag ins Büro zu fahren. Ich würde gerne öfter an die frische Luft gehen, anstatt immer im klimatisierten Büro zu sitzen. Ich würde gerne schöne Dinge kaufen, anstatt immer nur zu sparen. Ich würde gerne etwas mit meiner Familie unternehmen, anstatt am Wochenende zu arbeiten.","en":"J'aimerais faire du télétravail un jour par semaine au lieu d'aller au bureau tous les jours. J'aimerais sortir plus souvent au grand air au lieu d'être toujours assis dans le bureau climatisé. J'aimerais acheter de belles choses au lieu de ne faire qu'économiser. J'aimerais faire quelque chose avec ma famille au lieu de travailler le week-end.","why":"Souhait avec *würde gerne* + infinitif, puis *anstatt … zu* + infinitif à la fin ; *nur* reste devant *zu sparen*.","source":"g6865"}]}]},{"page":"Blatt 49 · Seite 1","heading":"49  Ich arbeite hier, ohne Stress zu haben.","heading_en":"Je travaille ici sans être stressé. (Proposition principale + proposition infinitive / subordonnée de manière : *ohne … zu, ohne dass*)","exercises":[{"no":"A","instruction":"Lesen Sie und unterstreichen Sie *ohne … zu*.","instruction_en":"Lisez la bulle et tapez la partie avec *ohne … zu*. Les encadrés de règles B et C de la fiche sont présentés ci-dessous.","reading":[{"label":"Sprechblase","text":"Homeoffice! Ja, cool! Ich arbeite hier, ohne Stress zu haben."},{"label":"B  Lesen Sie.","text":"Infinitiv mit ohne zu: Ich arbeite hier, | ohne Stress zu haben.\nNebensatz mit ohne dass: Ich arbeite hier, | ohne dass ich Stress habe.\nDie Subjekte in Haupt- und Nebensatz sind gleich: ohne zu oder ohne dass\nIch arbeite hier, | ohne Stress zu haben. / ohne dass ich Stress habe.\nDie Subjekte in Haupt- und Nebensatz sind verschieden: immer ohne dass\nIch arbeite hier, | ohne dass mein Chef Stress macht."},{"label":"C  Lesen Sie.","text":"• *ohne … zu* und *ohne dass* drücken aus, dass etwas nicht ist oder nicht passiert.\n• Im Infinitivsatz mit *ohne … zu* steht kein Subjekt. Das Subjekt aus dem Hauptsatz ist auch Subjekt im Infinitivsatz."}],"items":[{"label":"1","text":"Homeoffice! Ja, cool! Ich arbeite hier, ___.","gaps":[["ohne Stress zu haben"]],"solution":"Homeoffice! Ja, cool! Ich arbeite hier, **ohne Stress zu haben**.","en":"Le télétravail ! Oui, génial ! Je travaille ici sans être stressé.","why":"*ohne* ouvre la proposition, *zu* + infinitif la ferme.","source":"g6865"}]},{"no":"1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Quelles phrases sont justes ? Tapez *richtig* ou *falsch*. Astuce : *ohne* signifie déjà « pas », donc il n'est suivi ni de *nicht* ni de *kein*.","example":[{"label":"1","text":"Ich kann hier gut Klavier spielen, ohne die Nachbarn zu stören. → **richtig**"}],"items":[{"label":"2","text":"Ich kann hier gut Klavier spielen, ohne die Nachbarn nicht zu stören. → ___","gaps":[["falsch"]],"solution":"Ich kann hier gut Klavier spielen, ohne die Nachbarn nicht zu stören. → **falsch**","en":"Ici, je peux bien jouer du piano sans ne pas déranger les voisins. → faux","why":"*ohne … nicht* est une double négation : cela voudrait dire que l'on dérange *bel et bien* les voisins.","source":"ohnedass"},{"label":"3","text":"Er bekommt mehr Lohn, ohne eine Stunde mehr dafür zu arbeiten. → ___","gaps":[["richtig"]],"solution":"Er bekommt mehr Lohn, ohne eine Stunde mehr dafür zu arbeiten. → **richtig**","en":"Il reçoit un salaire plus élevé sans travailler une heure de plus pour cela. → juste","why":"*ohne* + groupe positif (*eine Stunde*) + *zu arbeiten*.","source":"g6865"},{"label":"4","text":"Er bekommt mehr Lohn, ohne keine Stunde mehr dafür zu arbeiten. → ___","gaps":[["falsch"]],"solution":"Er bekommt mehr Lohn, ohne keine Stunde mehr dafür zu arbeiten. → **falsch**","en":"Il reçoit un salaire plus élevé sans travailler aucune heure de plus pour cela. → faux","why":"Pas de *kein* après *ohne* : *keine Stunde* devient *eine Stunde*.","source":"ohnedass"}]}]},{"page":"Blatt 49 · Seite 2","heading":"49  Ich arbeite hier, ohne Stress zu haben.","heading_en":"Je travaille ici sans être stressé.","exercises":[{"no":"2","instruction":"Der Alltag eines Bloggers. Schreiben Sie Sätze mit *ohne … zu* in Ihr Heft.","instruction_en":"Le quotidien d'un blogueur. Reliez les deux phrases avec *ohne … zu*. Supprimez *nicht* ; transformez *kein* en *ein* (ou supprimez-le devant un pluriel).","example":[{"label":"1","lead":"Ich arbeite bequem von zu Hause. Ich fahre nicht ins Büro.","text":"Ich arbeite bequem von zu Hause, **ohne ins Büro zu fahren**."}],"items":[{"label":"2","lead":"Ich arbeite selbstständig. Ich habe keinen Vertrag.","text":"","accept":["Ich arbeite selbstständig, ohne einen Vertrag zu haben."],"solution":"**Ich arbeite selbstständig, ohne einen Vertrag zu haben.**","en":"Je travaille à mon compte sans avoir de contrat.","why":"*keinen Vertrag* → *einen Vertrag* : *ohne* dit déjà « pas de ».","source":"ohnedass"},{"label":"3","lead":"Ich mache Pausen und gehe auch mal zum Sport. Ich informiere meine Kollegen nicht.","text":"","accept":["Ich mache Pausen und gehe auch mal zum Sport, ohne meine Kollegen zu informieren."],"solution":"**Ich mache Pausen und gehe auch mal zum Sport, ohne meine Kollegen zu informieren.**","en":"Je fais des pauses et je vais aussi parfois au sport sans informer mes collègues.","why":"*nicht* disparaît ; *zu informieren* à la fin.","source":"g6865"},{"label":"4","lead":"Ich wähle die Themen für meinen Blog. Ich frage den Chef nicht.","text":"","accept":["Ich wähle die Themen für meinen Blog, ohne den Chef zu fragen."],"solution":"**Ich wähle die Themen für meinen Blog, ohne den Chef zu fragen.**","en":"Je choisis les sujets de mon blog sans demander au chef.","why":"*nicht* disparaît ; l'objet *den Chef* se place avant *zu fragen*.","source":"g6865"},{"label":"5","lead":"Ich habe viel Zeit für mein Kind. Ich mache mir keine Sorgen um meine Karriere.","text":"","accept":["Ich habe viel Zeit für mein Kind, ohne mir Sorgen um meine Karriere zu machen."],"solution":"**Ich habe viel Zeit für mein Kind, ohne mir Sorgen um meine Karriere zu machen.**","en":"J'ai beaucoup de temps pour mon enfant sans me faire de souci pour ma carrière.","why":"*keine Sorgen* → *Sorgen* (pluriel : pas d'article) ; le réfléchi *mir* reste.","source":"ohnedass"}]},{"no":"3","instruction":"Mein Leben. *ohne dass* oder *ohne*? Unterstreichen Sie.","instruction_en":"Ma vie. Tapez *ohne dass* ou *ohne*. Regardez la fin : *zu* + infinitif → *ohne* ; un nouveau sujet et un verbe conjugué à la fin → *ohne dass*.","example":[{"label":"1","text":"Ich möchte abends Musik hören, **ohne dass** sich meine Nachbarn beschweren."}],"items":[{"label":"2","text":"Ich trinke nie Kaffee, ___ dabei Zeitung zu lesen.","gaps":[["ohne"]],"solution":"Ich trinke nie Kaffee, **ohne** dabei Zeitung zu lesen.","en":"Je ne bois jamais de café sans lire le journal en même temps.","why":"*zu lesen* à la fin, pas de nouveau sujet → *ohne*.","source":"g6865"},{"label":"3","text":"Ich gehe nie ins Theater, ___ mich vorher über das Stück zu informieren.","gaps":[["ohne"]],"solution":"Ich gehe nie ins Theater, **ohne** mich vorher über das Stück zu informieren.","en":"Je ne vais jamais au théâtre sans me renseigner d'abord sur la pièce.","why":"*zu informieren* à la fin → *ohne* ; *mich* est le pronom réfléchi, pas un sujet.","source":"g6865"},{"label":"4","text":"Meine Kinder gehen nie aus, ___ ich etwas davon weiss.","gaps":[["ohne dass"]],"solution":"Meine Kinder gehen nie aus, **ohne dass** ich etwas davon weiss.","en":"Mes enfants ne sortent jamais sans que je le sache.","why":"Nouveau sujet *ich*, *weiss* à la fin → *ohne dass*.","source":"ohnedass"}]},{"no":"4","instruction":"Computer. Unterstreichen Sie die Subjekte. Sind sie (nicht) gleich? Kreuzen Sie an.","instruction_en":"Les ordinateurs. Trouvez le sujet de chaque phrase et tapez les deux sujets, puis *gleich* (identiques) ou *nicht gleich* (pas identiques). *Sie* avec une majuscule = « vous » de politesse.","example":[{"label":"1","text":"Sie verlässt einfach das Büro. Sie sichert die Daten im Computer nicht. → **Sie** / **Sie** → **gleich**"}],"items":[{"label":"2","text":"Die Firma speichert unsere Daten. Wir haben keine Ahnung. → ___ / ___ → ___","gaps":[["Die Firma"],["Wir"],["nicht gleich"]],"solution":"Die Firma speichert unsere Daten. Wir haben keine Ahnung. → **Die Firma** / **Wir** → **nicht gleich**","en":"L'entreprise enregistre nos données. Nous n'en avons aucune idée. → pas identiques","why":"Deux sujets différents : *die Firma* et *wir*.","source":"ohnedass"},{"label":"3","text":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange. → ___ / ___ → ___","gaps":[["Wir"],["Wir"],["gleich"]],"solution":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange. → **Wir** / **Wir** → **gleich**","en":"Nous devrions traiter les données électroniquement. Nous n'attendons pas longtemps. → identiques","why":"Dans les deux phrases : *wir*.","source":"g6865"},{"label":"4","text":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht. → ___ / ___ → ___","gaps":[["Sie"],["Der Techniker"],["nicht gleich"]],"solution":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht. → **Sie** / **Der Techniker** → **nicht gleich**","en":"Vous pouvez installer le logiciel. Le technicien ne vous aide pas. → pas identiques","why":"*Ihnen* est l'objet au datif ; le sujet de la deuxième phrase est *der Techniker*.","source":"ohnedass"},{"label":"5","text":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht. → ___ / ___ → ___","gaps":[["Ich"],["Ich"],["gleich"]],"solution":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht. → **Ich** / **Ich** → **gleich**","en":"Je branche l'ordinateur. Je ne demande pas au service informatique. → identiques","why":"Dans les deux phrases : *ich*.","source":"g6865"}]},{"no":"5","instruction":"Verbinden Sie die Sätze aus 4 mit *ohne dass* und, wo möglich, mit *ohne zu*. Schreiben Sie in Ihr Heft.","instruction_en":"Reliez les phrases de l'exercice 4 avec *ohne dass*, et aussi avec *ohne … zu* quand les sujets sont identiques. Supprimez *nicht* ; transformez *keine* en *eine*.","example":[{"label":"1","text":"Sie verlässt einfach das Büro, **ohne die Daten im Computer zu sichern**.\nSie verlässt einfach das Büro, **ohne dass sie die Daten im Computer sichert**."}],"items":[{"label":"2 · ohne dass","lead":"Die Firma speichert unsere Daten. Wir haben keine Ahnung.","text":"","accept":["Die Firma speichert unsere Daten, ohne dass wir eine Ahnung haben.","Die Firma speichert unsere Daten, ohne dass wir eine Ahnung davon haben."],"solution":"**Die Firma speichert unsere Daten, ohne dass wir eine Ahnung haben.**","en":"L'entreprise enregistre nos données sans que nous en ayons la moindre idée.","why":"Sujets différents → seulement *ohne dass* ; *keine Ahnung* → *eine Ahnung*.","source":"ohnedass"},{"label":"3 · ohne … zu","lead":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange.","text":"","accept":["Wir sollten die Daten elektronisch verarbeiten, ohne lange zu warten."],"solution":"**Wir sollten die Daten elektronisch verarbeiten, ohne lange zu warten.**","en":"Nous devrions traiter les données électroniquement sans attendre longtemps.","why":"Même sujet : *nicht* disparaît, *zu warten* à la fin.","source":"g6865"},{"label":"3 · ohne dass","lead":"Wir sollten die Daten elektronisch verarbeiten. Wir warten nicht lange.","text":"","accept":["Wir sollten die Daten elektronisch verarbeiten, ohne dass wir lange warten."],"solution":"**Wir sollten die Daten elektronisch verarbeiten, ohne dass wir lange warten.**","en":"Nous devrions traiter les données électroniquement sans attendre longtemps.","why":"Le sujet *wir* est répété, *warten* à la fin.","source":"ohnedass"},{"label":"4 · ohne dass","lead":"Sie können die Software installieren. Der Techniker hilft Ihnen nicht.","text":"","accept":["Sie können die Software installieren, ohne dass der Techniker Ihnen hilft.","Sie können die Software installieren, ohne dass Ihnen der Techniker hilft."],"solution":"**Sie können die Software installieren, ohne dass der Techniker Ihnen hilft.**","en":"Vous pouvez installer le logiciel sans que le technicien vous aide.","why":"Sujets différents → seulement *ohne dass* ; *hilft* à la fin.","source":"ohnedass"},{"label":"5 · ohne … zu","lead":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht.","text":"","accept":["Ich schliesse den Computer an, ohne die IT-Abteilung zu fragen."],"solution":"**Ich schliesse den Computer an, ohne die IT-Abteilung zu fragen.**","en":"Je branche l'ordinateur sans demander au service informatique.","why":"Même sujet : *ohne die IT-Abteilung zu fragen*.","source":"g6865"},{"label":"5 · ohne dass","lead":"Ich schliesse den Computer an. Ich frage die IT-Abteilung nicht.","text":"","accept":["Ich schliesse den Computer an, ohne dass ich die IT-Abteilung frage."],"solution":"**Ich schliesse den Computer an, ohne dass ich die IT-Abteilung frage.**","en":"Je branche l'ordinateur sans demander au service informatique.","why":"Le sujet *ich* est répété, *frage* à la fin.","source":"ohnedass"}]},{"no":"6","instruction":"Was würden Sie gerne machen? Schreiben Sie Sätze mit *ohne … zu* in Ihr Heft.","instruction_en":"Qu'aimeriez-vous faire ? Combinez un souhait de la première partie de l'encadré avec un élément de la deuxième partie, en utilisant *ohne … zu*. Les expressions barrées sont utilisées dans l'exemple. La réponse modèle n'est qu'une possibilité.","box":["viel Geld verdienen","eine eigene Firma gründen","fliessend Deutsch sprechen","mehrmals im Jahr verreisen","immer sparen","noch mehr arbeiten","Sprachkurse besuchen","die Risiken tragen"],"box_used":[0,5],"example":[{"label":"Beispiel","text":"Ich würde gerne viel Geld verdienen, **ohne noch mehr zu arbeiten**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gerne eine eigene Firma gründen, ohne die Risiken zu tragen. Ich würde gerne fliessend Deutsch sprechen, ohne Sprachkurse zu besuchen. Ich würde gerne mehrmals im Jahr verreisen, ohne immer zu sparen.","en":"J'aimerais créer ma propre entreprise sans en porter les risques. J'aimerais parler couramment l'allemand sans suivre de cours de langue. J'aimerais partir en voyage plusieurs fois par an sans toujours économiser.","why":"Souhait avec *würde gerne* + infinitif, puis *ohne … zu* + infinitif à la fin.","source":"g6865"}]}]},{"page":"Blatt 52 · S. 108","heading":"52  Ich fahre langsam, um Benzin zu sparen.","heading_en":"Je roule lentement pour économiser de l'essence. (Proposition principale + subordonnée de but : *um … zu, damit*)","exercises":[{"no":"A","instruction":"Lesen Sie und ordnen Sie zu.","instruction_en":"Lisez et associez chaque phrase à une photo. Photo A : un homme qui tourne le bouton d'un radiateur. Photo B : des mains sur un volant. Tapez A ou B. Les encadrés de règles B et C de la fiche sont présentés ci-dessous.","reading":[{"label":"Alles, um die Umwelt zu schützen","text":"1 Ich fahre langsam, um Benzin zu sparen.\n2 Um Energie zu sparen, schalten wir die Heizung nachts aus."},{"label":"B  Lesen Sie.","text":"Infinitiv mit um zu: Ich fahre langsam, | um Benzin zu sparen.\nNebensatz mit damit: Ich fahre langsam, | damit ich Benzin spare.\nDie Subjekte in Haupt- und Nebensatz sind gleich: um zu oder damit\nIch fahre langsam, | um Benzin zu sparen. / damit ich Benzin spare.\nDie Subjekte in Haupt- und Nebensatz sind nicht gleich: immer damit\nMeine Eltern sparen, | damit ich studieren kann."},{"label":"C  Lesen Sie.","text":"• *um … zu* und *damit* drücken einen Zweck oder eine Absicht aus.\n• Der Satz mit *um … zu* ist ein Infinitivsatz. Am Ende steht der Infinitiv."}],"items":[{"label":"1","text":"Foto ___: Ich fahre langsam, um Benzin zu sparen.","gaps":[["B"]],"solution":"Foto **B**: Ich fahre langsam, um Benzin zu sparen.","en":"Photo B : je roule lentement pour économiser de l'essence.","why":"Conduire → le volant.","source":"adverbial"},{"label":"2","text":"Foto ___: Um Energie zu sparen, schalten wir die Heizung nachts aus.","gaps":[["A"]],"solution":"Foto **A**: Um Energie zu sparen, schalten wir die Heizung nachts aus.","en":"Photo A : pour économiser de l'énergie, nous éteignons le chauffage la nuit.","why":"Chauffage → le radiateur. Quand *um … zu* vient en premier, la principale commence par le verbe : *schalten wir*.","source":"g6865"}]},{"no":"1","instruction":"Wozu das? Verbinden Sie die Sätze mit *um … zu* und schreiben Sie in Ihr Heft.","instruction_en":"Dans quel but ? Reliez chaque phrase au but entre parenthèses avec *um … zu* : *um* après la virgule, *zu* + infinitif à la fin.","example":[{"label":"1","lead":"Wir fahren in die Berge. (→ wandern und ein Picknick machen)","text":"Wir fahren in die Berge, **um zu wandern und ein Picknick zu machen**."}],"items":[{"label":"2","lead":"Wir fahren an den See. (→ dort spazieren gehen)","text":"","accept":["Wir fahren an den See, um dort spazieren zu gehen."],"solution":"**Wir fahren an den See, um dort spazieren zu gehen.**","en":"Nous allons au lac pour nous y promener.","why":"Deux verbes : *zu* se place devant le dernier : *spazieren zu gehen*.","source":"g6865"},{"label":"3","lead":"Wir haben lange gespart. (→ die Wohnung kaufen)","text":"","accept":["Wir haben lange gespart, um die Wohnung zu kaufen."],"solution":"**Wir haben lange gespart, um die Wohnung zu kaufen.**","en":"Nous avons longtemps économisé pour acheter l'appartement.","why":"*um die Wohnung zu kaufen* : l'objet se place entre *um* et *zu*.","source":"g6865"},{"label":"4","lead":"Ich muss in die Klinik. (→ meinen kranken Onkel besuchen)","text":"","accept":["Ich muss in die Klinik, um meinen kranken Onkel zu besuchen."],"solution":"**Ich muss in die Klinik, um meinen kranken Onkel zu besuchen.**","en":"Je dois aller à l'hôpital pour rendre visite à mon oncle malade.","why":"*um … zu besuchen*.","source":"g6865"},{"label":"5","lead":"Ihr müsst mehr trainieren. (→ am Marathon teilnehmen können)","text":"","accept":["Ihr müsst mehr trainieren, um am Marathon teilnehmen zu können."],"solution":"**Ihr müsst mehr trainieren, um am Marathon teilnehmen zu können.**","en":"Vous devez vous entraîner davantage pour pouvoir participer au marathon.","why":"Avec un verbe de modalité, *zu* se place devant le verbe de modalité : *teilnehmen zu können*.","source":"g6865"},{"label":"6","lead":"Du musst Sport machen. (→ gesund bleiben)","text":"","accept":["Du musst Sport machen, um gesund zu bleiben."],"solution":"**Du musst Sport machen, um gesund zu bleiben.**","en":"Tu dois faire du sport pour rester en bonne santé.","why":"*um gesund zu bleiben*.","source":"g6865"}]}]},{"page":"Blatt 52 · S. 109","heading":"52  Ich fahre langsam, um Benzin zu sparen.","heading_en":"Je roule lentement pour économiser de l'essence.","exercises":[{"no":"2","instruction":"Ordnen Sie zu und verbinden Sie Sätze mit *damit*. Beginnen Sie die Sätze auch mit *damit*. Schreiben Sie in Ihr Heft.","instruction_en":"Associez chaque question à un but (a–c), puis répondez deux fois : une fois avec *damit* après la principale, une fois en commençant par *Damit*. Dans la subordonnée en *damit*, le verbe va à la fin ; après une subordonnée en *Damit* placée en tête, la principale commence par son verbe.","phrases":["a  Wir prüfen endlich die Rechnung.","b  Meine Frau wartet nicht so lange.","c  Ich repariere ihr Fahrrad.","d  Du verstehst mich gut. (Beispiel)"],"example":[{"label":"1","lead":"Wozu übst du die Aussprache? → d","text":"Ich übe die Aussprache, **damit du mich gut verstehst**.\n**Damit du mich gut verstehst**, übe ich die Aussprache."}],"items":[{"label":"2","text":"Wozu holt Paul den Taschenrechner? → ___","gaps":[["a"]],"solution":"Wozu holt Paul den Taschenrechner? → **a**","en":"Paul va chercher la calculatrice pour que nous vérifiions enfin la facture.","why":"Trouvez le but qui correspond à la question.","source":"damit"},{"label":"2 · damit am Ende","lead":"Wozu holt Paul den Taschenrechner? → a","text":"","accept":["Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen.","Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen können."],"solution":"**Paul holt den Taschenrechner, damit wir endlich die Rechnung prüfen.**","en":"Paul va chercher la calculatrice pour que nous vérifiions enfin la facture.","why":"Nouveau sujet *wir* → *damit* ; *prüfen* à la fin.","source":"damit"},{"label":"2 · Damit am Anfang","lead":"Wozu holt Paul den Taschenrechner? → a","text":"","accept":["Damit wir endlich die Rechnung prüfen, holt Paul den Taschenrechner.","Damit wir endlich die Rechnung prüfen können, holt Paul den Taschenrechner."],"solution":"**Damit wir endlich die Rechnung prüfen, holt Paul den Taschenrechner.**","en":"Paul va chercher la calculatrice pour que nous vérifiions enfin la facture.","why":"Subordonnée en *Damit* en tête, puis le verbe : *holt Paul*.","source":"damit"},{"label":"3","text":"Wozu fahren Sie so schnell? → ___","gaps":[["b"]],"solution":"Wozu fahren Sie so schnell? → **b**","en":"Je roule si vite pour que ma femme n'attende pas si longtemps.","why":"Trouvez le but qui correspond à la question.","source":"damit"},{"label":"3 · damit am Ende","lead":"Wozu fahren Sie so schnell? → b","text":"","accept":["Ich fahre so schnell, damit meine Frau nicht so lange wartet.","Ich fahre so schnell, damit meine Frau nicht so lange warten muss."],"solution":"**Ich fahre so schnell, damit meine Frau nicht so lange wartet.**","en":"Je roule si vite pour que ma femme n'attende pas si longtemps.","why":"La question utilise *Sie*, la réponse *ich*. Ici, *nicht* reste : *damit* n'exprime pas de négation.","source":"damit"},{"label":"3 · Damit am Anfang","lead":"Wozu fahren Sie so schnell? → b","text":"","accept":["Damit meine Frau nicht so lange wartet, fahre ich so schnell.","Damit meine Frau nicht so lange warten muss, fahre ich so schnell."],"solution":"**Damit meine Frau nicht so lange wartet, fahre ich so schnell.**","en":"Je roule si vite pour que ma femme n'attende pas si longtemps.","why":"Subordonnée en *Damit* en tête, puis *fahre ich*.","source":"damit"},{"label":"4","text":"Wozu hat Emilia eine Zange mitgenommen? → ___","gaps":[["c"]],"solution":"Wozu hat Emilia eine Zange mitgenommen? → **c**","en":"Emilia a apporté une pince pour que je répare son vélo.","why":"Trouvez le but qui correspond à la question.","source":"damit"},{"label":"4 · damit am Ende","lead":"Wozu hat Emilia eine Zange mitgenommen? → c","text":"","accept":["Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad repariere.","Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad reparieren kann."],"solution":"**Emilia hat eine Zange mitgenommen, damit ich ihr Fahrrad repariere.**","en":"Emilia a apporté une pince pour que je répare son vélo.","why":"*ihr Fahrrad* = le vélo d'Emilia ; nouveau sujet *ich* → *damit*.","source":"damit"},{"label":"4 · Damit am Anfang","lead":"Wozu hat Emilia eine Zange mitgenommen? → c","text":"","accept":["Damit ich ihr Fahrrad repariere, hat Emilia eine Zange mitgenommen.","Damit ich ihr Fahrrad reparieren kann, hat Emilia eine Zange mitgenommen."],"solution":"**Damit ich ihr Fahrrad repariere, hat Emilia eine Zange mitgenommen.**","en":"Emilia a apporté une pince pour que je répare son vélo.","why":"Subordonnée en *Damit* en tête, puis *hat Emilia … mitgenommen*.","source":"damit"}]},{"no":"3","instruction":"Welche Sätze kann man mit *um … zu* verbinden? Kreuzen Sie an.","instruction_en":"Quelles paires peut-on relier avec *um … zu* ? Seulement quand les deux phrases ont le même sujet. Tapez *ja* ou *nein*.","example":[{"label":"1","text":"Ich mache eine Zusatzqualifikation. Ich möchte die Teamleitung bekommen. → **ja**"}],"items":[{"label":"2","text":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser. → ___","gaps":[["nein"]],"solution":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser. → **nein**","en":"Betty suit un cours d'été à Paris. Ses notes en français s'améliorent. → non","why":"Les sujets *Betty* et *ihre Noten* sont différents.","source":"g6865"},{"label":"3","text":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken. → ___","gaps":[["ja"]],"solution":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken. → **ja**","en":"Nous avons besoin de votre accord. Nous aimerions vous envoyer de la publicité. → oui","why":"Les deux : *wir*.","source":"g6865"},{"label":"4","text":"David hat auch abends noch genügend Energie. Er möchte Sport machen. → ___","gaps":[["ja"]],"solution":"David hat auch abends noch genügend Energie. Er möchte Sport machen. → **ja**","en":"Le soir aussi, David a encore assez d'énergie. Il aimerait faire du sport. → oui","why":"*Er* = David.","source":"g6865"},{"label":"5","text":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren. → ___","gaps":[["nein"]],"solution":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren. → **nein**","en":"Je prépare déjà tout ce soir. Vous pouvez partir très tôt demain. → non","why":"Les sujets *ich* et *ihr* sont différents.","source":"g6865"},{"label":"6","text":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen. → ___","gaps":[["nein"]],"solution":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen. → **nein**","en":"Nous achetons de plus en plus souvent des produits bio. Nos enfants peuvent manger sainement. → non","why":"Les sujets *wir* et *unsere Kinder* sont différents.","source":"g6865"},{"label":"7","text":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen. → ___","gaps":[["ja"]],"solution":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen. → **ja**","en":"Emma et Pia se retrouvent en ville. Elles aimeraient faire les magasins ensemble. → oui","why":"*Sie* = Emma et Pia.","source":"g6865"},{"label":"8","text":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen. → ___","gaps":[["ja"]],"solution":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen. → **ja**","en":"Tu as besoin d'une bonne méthode de travail. Tu aimerais résoudre les exercices rapidement. → oui","why":"Les deux : *du*.","source":"g6865"}]},{"no":"4","instruction":"Verbinden Sie die Sätze in 3 mit *damit* und, wo möglich, mit *um … zu*. Schreiben Sie in Ihr Heft.","instruction_en":"Reliez les paires de l'exercice 3 avec *damit*, et aussi avec *um … zu* quand le sujet est le même. *möchte(n)* est supprimé : le mot de but exprime déjà « vouloir ».","example":[{"label":"1","text":"Ich mache eine Zusatzqualifikation, **um die Teamleitung zu bekommen**.\nIch mache eine Zusatzqualifikation, **damit ich die Teamleitung bekomme**."}],"items":[{"label":"2 · damit","lead":"Betty macht einen Sommerkurs in Paris. Ihre Noten in Französisch werden besser.","text":"","accept":["Betty macht einen Sommerkurs in Paris, damit ihre Noten in Französisch besser werden.","Betty macht einen Sommerkurs in Paris, damit ihre Französischnoten besser werden."],"solution":"**Betty macht einen Sommerkurs in Paris, damit ihre Noten in Französisch besser werden.**","en":"Betty suit un cours d'été à Paris pour que ses notes en français s'améliorent.","why":"Sujets différents → seulement *damit* ; *werden* à la fin.","source":"damit"},{"label":"3 · um … zu","lead":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken.","text":"","accept":["Wir brauchen Ihre Zustimmung, um Ihnen Werbung zuzuschicken."],"solution":"**Wir brauchen Ihre Zustimmung, um Ihnen Werbung zuzuschicken.**","en":"Nous avons besoin de votre accord pour vous envoyer de la publicité.","why":"Verbe séparable : *zuzuschicken* (zu + zu + schicken) ; *möchten* disparaît.","source":"g6865"},{"label":"3 · damit","lead":"Wir brauchen Ihre Zustimmung. Wir möchten Ihnen Werbung zuschicken.","text":"","accept":["Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken dürfen.","Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken können.","Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken."],"solution":"**Wir brauchen Ihre Zustimmung, damit wir Ihnen Werbung zuschicken dürfen.**","en":"Nous avons besoin de votre accord pour que nous ayons le droit de vous envoyer de la publicité.","why":"*damit wir … zuschicken dürfen* : l'accord donne une permission, donc *dürfen* convient le mieux.","source":"damit","check":"La fiche n'a pas de corrigé : *dürfen*, *können* ou aucun verbe de modalité fonctionnent tous ici ; demandez à votre enseignant ce qu'il attend."},{"label":"4 · um … zu","lead":"David hat auch abends noch genügend Energie. Er möchte Sport machen.","text":"","accept":["David hat auch abends noch genügend Energie, um Sport zu machen."],"solution":"**David hat auch abends noch genügend Energie, um Sport zu machen.**","en":"Le soir aussi, David a encore assez d'énergie pour faire du sport.","why":"Même sujet : *um Sport zu machen*.","source":"g6865"},{"label":"4 · damit","lead":"David hat auch abends noch genügend Energie. Er möchte Sport machen.","text":"","accept":["David hat auch abends noch genügend Energie, damit er Sport machen kann.","David hat auch abends noch genügend Energie, damit er Sport macht."],"solution":"**David hat auch abends noch genügend Energie, damit er Sport machen kann.**","en":"Le soir aussi, David a encore assez d'énergie pour pouvoir faire du sport.","why":"Le sujet *er* est répété, verbe à la fin.","source":"damit"},{"label":"5 · damit","lead":"Ich bereite heute Abend schon alles vor. Ihr könnt morgen ganz früh losfahren.","text":"","accept":["Ich bereite heute Abend schon alles vor, damit ihr morgen ganz früh losfahren könnt."],"solution":"**Ich bereite heute Abend schon alles vor, damit ihr morgen ganz früh losfahren könnt.**","en":"Je prépare déjà tout ce soir pour que vous puissiez partir très tôt demain.","why":"Sujets différents → seulement *damit* ; *könnt* tout à la fin.","source":"damit"},{"label":"6 · damit","lead":"Wir kaufen immer öfter Bio-Qualität. Unsere Kinder können gesund essen.","text":"","accept":["Wir kaufen immer öfter Bio-Qualität, damit unsere Kinder gesund essen können."],"solution":"**Wir kaufen immer öfter Bio-Qualität, damit unsere Kinder gesund essen können.**","en":"Nous achetons de plus en plus souvent des produits bio pour que nos enfants puissent manger sainement.","why":"Sujets différents → seulement *damit*.","source":"damit"},{"label":"7 · um … zu","lead":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen.","text":"","accept":["Emma und Pia treffen sich in der Stadt, um zusammen einzukaufen."],"solution":"**Emma und Pia treffen sich in der Stadt, um zusammen einzukaufen.**","en":"Emma et Pia se retrouvent en ville pour faire les magasins ensemble.","why":"Verbe séparable : *einzukaufen* (ein + zu + kaufen).","source":"g6865"},{"label":"7 · damit","lead":"Emma und Pia treffen sich in der Stadt. Sie möchten zusammen einkaufen.","text":"","accept":["Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen können.","Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen."],"solution":"**Emma und Pia treffen sich in der Stadt, damit sie zusammen einkaufen können.**","en":"Emma et Pia se retrouvent en ville pour pouvoir faire les magasins ensemble.","why":"Le sujet *sie* est répété, verbe à la fin.","source":"damit"},{"label":"8 · um … zu","lead":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen.","text":"","accept":["Du brauchst eine gute Arbeitstechnik, um die Aufgaben schnell zu lösen."],"solution":"**Du brauchst eine gute Arbeitstechnik, um die Aufgaben schnell zu lösen.**","en":"Tu as besoin d'une bonne méthode de travail pour résoudre les exercices rapidement.","why":"Même sujet : *um … zu lösen*.","source":"g6865"},{"label":"8 · damit","lead":"Du brauchst eine gute Arbeitstechnik. Du möchtest die Aufgaben schnell lösen.","text":"","accept":["Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell lösen kannst.","Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell löst."],"solution":"**Du brauchst eine gute Arbeitstechnik, damit du die Aufgaben schnell lösen kannst.**","en":"Tu as besoin d'une bonne méthode de travail pour pouvoir résoudre les exercices rapidement.","why":"Le sujet *du* est répété, verbe à la fin.","source":"damit"}]},{"no":"5","instruction":"Lesen Sie Frau Deckers Blog und verbinden Sie die Sätze mit *um … zu* oder *damit*.","instruction_en":"Lisez le blog de Mme Decker et reliez chaque paire : même sujet → *um … zu* (le mieux) ; sujet différent → *damit*. Supprimez *möchte*.","reading":[{"label":"www.mein-tag.de","text":"1 Ich stehe morgens früh auf. Ich möchte noch vor dem Frühstück joggen.\n2 Ich fahre oft mit dem Auto ins Büro. Ich möchte pünktlich sein.\n3 Am Vormittag arbeite ich schnell und konzentriert. Meine Kunden sind zufrieden.\n4 Ich fahre in der Mittagspause in den Supermarkt. Ich kaufe schnell etwas fürs Abendessen ein.\n5 Ich verlasse die Firma um drei. Meine Kinder sind nicht zu lange allein."}],"example":[{"label":"1","text":"Ich stehe morgens früh auf, **um noch vor dem Frühstück zu joggen**."}],"items":[{"label":"2","lead":"Ich fahre oft mit dem Auto ins Büro. Ich möchte pünktlich sein.","text":"","accept":["Ich fahre oft mit dem Auto ins Büro, um pünktlich zu sein.","Ich fahre oft mit dem Auto ins Büro, damit ich pünktlich bin."],"solution":"**Ich fahre oft mit dem Auto ins Büro, um pünktlich zu sein.**","en":"Je vais souvent au bureau en voiture pour être à l'heure.","why":"Même sujet *ich* → *um pünktlich zu sein*.","source":"g6865"},{"label":"3","lead":"Am Vormittag arbeite ich schnell und konzentriert. Meine Kunden sind zufrieden.","text":"","accept":["Am Vormittag arbeite ich schnell und konzentriert, damit meine Kunden zufrieden sind."],"solution":"**Am Vormittag arbeite ich schnell und konzentriert, damit meine Kunden zufrieden sind.**","en":"Le matin, je travaille vite et de manière concentrée pour que mes clients soient satisfaits.","why":"Nouveau sujet *meine Kunden* → *damit* ; *sind* à la fin.","source":"damit"},{"label":"4","lead":"Ich fahre in der Mittagspause in den Supermarkt. Ich kaufe schnell etwas fürs Abendessen ein.","text":"","accept":["Ich fahre in der Mittagspause in den Supermarkt, um schnell etwas fürs Abendessen einzukaufen.","Ich fahre in der Mittagspause in den Supermarkt, damit ich schnell etwas fürs Abendessen einkaufe."],"solution":"**Ich fahre in der Mittagspause in den Supermarkt, um schnell etwas fürs Abendessen einzukaufen.**","en":"Pendant la pause de midi, je vais au supermarché pour acheter vite quelque chose pour le repas du soir.","why":"Même sujet ; verbe séparable : *einzukaufen* (ein + zu + kaufen).","source":"g6865"},{"label":"5","lead":"Ich verlasse die Firma um drei. Meine Kinder sind nicht zu lange allein.","text":"","accept":["Ich verlasse die Firma um drei, damit meine Kinder nicht zu lange allein sind."],"solution":"**Ich verlasse die Firma um drei, damit meine Kinder nicht zu lange allein sind.**","en":"Je quitte l'entreprise à trois heures pour que mes enfants ne restent pas seuls trop longtemps.","why":"Nouveau sujet *meine Kinder* → *damit* ; *nicht* reste (seuls *ohne* et *anstatt* l'absorbent).","source":"damit"}]},{"no":"6","instruction":"Wozu machen Sie was? Schreiben Sie 3 Sätze über Ihren Tag in Ihr Heft und nennen Sie den Zweck.","instruction_en":"Que faites-vous, et dans quel but ? Écrivez 3 phrases sur votre journée et indiquez le but avec *um … zu* ou *damit*. La réponse modèle n'est qu'une possibilité.","example":[{"label":"Beispiel","text":"Ich gehe schon um drei aus dem Büro, **um früh bei den Kindern zu sein**."}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich stehe um halb sieben auf, um den Zug nach Zürich zu erreichen. Ich nehme mein Mittagessen von zu Hause mit, um Geld zu sparen. Am Abend lerne ich eine halbe Stunde Deutsch, damit meine Chancen im Job besser werden.","en":"Je me lève à six heures et demie pour attraper le train pour Zurich. J'emporte mon repas de midi de la maison pour économiser de l'argent. Le soir, j'apprends l'allemand pendant une demi-heure pour que mes chances au travail s'améliorent.","why":"Même sujet → *um … zu* ; nouveau sujet (*meine Chancen*) → *damit*.","source":"adverbial"}]}]}],"sources":[{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (um / ohne / anstatt … zu n'ont pas de sujet propre ; il est repris de la principale)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"damit","title":"grammis, dictionnaire des connecteurs : damit (subjonction avec le verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/407001"},{"id":"adverbial","title":"grammis: Adverbial (les subordonnées avec um … zu et damit sont des compléments circonstanciels de but)","url":"https://grammis.ids-mannheim.de/vggf/2280"},{"id":"ohnedass","title":"grammis, dictionnaire des connecteurs : ohne dass (subjonction, verbe à la fin ; induit une négation : la subordonnée dit ce qui n'a pas lieu)","url":"https://grammis.ids-mannheim.de/konnektoren/406910"},{"id":"anstattdass","title":"grammis, dictionnaire des connecteurs : anstatt dass (subjonction, verbe à la fin ; substitutive et induisant une négation ; aussi statt dass)","url":"https://grammis.ids-mannheim.de/konnektoren/406953"}]}];
